        <script>
            (function () {
                const tabButtons = Array.prototype.slice.call(document.querySelectorAll('[data-maintenance-tab]'));
                const tabPanels = Array.prototype.slice.call(document.querySelectorAll('[data-maintenance-panel]'));
                const questionTypeLabels = <?php echo wp_json_encode($seed_question_type_labels); ?>;
                const loadTestGlobalToken = <?php echo wp_json_encode((string) (($load_test_runtime['global_token_meta']['token'] ?? ''))); ?>;
                const syncUrl = function (tabName) {
                    if (!window.history || !window.history.replaceState) {
                        return;
                    }

                    const url = new URL(window.location.href);
                    url.searchParams.set('cbt_maintenance_tab', tabName);
                    window.history.replaceState({}, '', url.toString());
                };
                const activateTab = function (tabName, shouldSyncUrl) {
                    tabButtons.forEach(function (button) {
                        const active = button.getAttribute('data-maintenance-tab') === tabName;
                        button.classList.toggle('is-active', active);
                        button.setAttribute('aria-selected', active ? 'true' : 'false');
                    });
                    tabPanels.forEach(function (panel) {
                        const active = panel.getAttribute('data-maintenance-panel') === tabName;
                        panel.classList.toggle('is-active', active);
                    });
                    if (shouldSyncUrl) {
                        syncUrl(tabName);
                    }
                };
                tabButtons.forEach(function (button) {
                    button.addEventListener('click', function () {
                        activateTab(button.getAttribute('data-maintenance-tab') || 'reset', true);
                    });
                });
                document.querySelectorAll('[data-maintenance-banner-close]').forEach(function (button) {
                    button.addEventListener('click', function () {
                        const banner = button.closest('[data-maintenance-banner]');
                        if (banner) {
                            banner.remove();
                        }
                    });
                });
                activateTab(<?php echo wp_json_encode($active_maintenance_tab); ?>, false);

                const numberFormatter = window.Intl ? new Intl.NumberFormat('id-ID') : null;
                const parseJson = function (value, fallbackValue) {
                    try {
                        return JSON.parse(String(value || ''));
                    } catch (error) {
                        return fallbackValue;
                    }
                };

                const initSeedPresetSummary = function () {
                    const presets = <?php echo $seed_presets_json; ?>;
                    const select = document.getElementById('cbt-seed-preset');
                    if (!select) {
                        return;
                    }

                    const breakdownContainer = document.getElementById('cbt-seed-question-breakdown');
                    const questionSummaryTextNode = document.querySelector('[data-seed-question-summary-text]');
                    const updateSummary = function () {
                        const preset = presets[select.value] || presets.small || null;
                        if (!preset) {
                            return;
                        }

                        const keys = ['subjects', 'exams', 'questions', 'students', 'teachers', 'classes', 'rooms'];
                        keys.forEach(function (key) {
                            document.querySelectorAll('[data-seed-summary="' + key + '"]').forEach(function (node) {
                                node.textContent = String(preset[key] || 0);
                            });
                        });

                        const labelNode = document.querySelector('[data-seed-summary-label]');
                        if (labelNode) {
                            labelNode.textContent = preset.label || select.value;
                        }

                        if (questionSummaryTextNode) {
                            questionSummaryTextNode.textContent = preset.question_type_summary || '';
                        }

                        if (breakdownContainer) {
                            breakdownContainer.innerHTML = '';
                            const counts = preset.question_type_counts || {};
                            Object.keys(counts).forEach(function (typeKey) {
                                const count = Number(counts[typeKey] || 0);
                                if (!count) {
                                    return;
                                }

                                const chip = document.createElement('span');
                                chip.className = 'cbt-maintenance-question-chip';
                                chip.textContent = (questionTypeLabels[typeKey] || typeKey) + ': ' + (numberFormatter ? numberFormatter.format(count) : String(count));
                                breakdownContainer.appendChild(chip);
                            });
                        }
                    };

                    select.addEventListener('change', updateSummary);
                    updateSummary();
                };

                const initLoadTestPanel = function () {
                    const form = document.querySelector('[data-load-test-form]');
                    const jobsWrap = document.querySelector('[data-load-jobs-wrap]');
                    if (!form && !jobsWrap) {
                        return;
                    }

                    const profiles = form ? parseJson(form.getAttribute('data-load-profiles'), {}) : {};
                    const exams = form ? parseJson(form.getAttribute('data-load-exams'), []) : [];
                    const k6Path = form ? String(form.getAttribute('data-load-k6-path') || 'k6') : 'k6';
                    const readyUsers = form ? Number(form.getAttribute('data-load-ready-users') || 0) : 0;
                    const presetSelect = form ? form.querySelector('[data-load-profile-preset]') : null;
                    const commandPreview = form ? form.querySelector('[data-load-command-preview]') : null;
                    const warningChip = form ? form.querySelector('[data-load-user-warning]') : null;
                    const refreshButton = form ? form.querySelector('[data-load-refresh-jobs]') : null;
                    const examPickerLabel = form ? form.querySelector('[data-load-exam-picker-label]') : null;
                    const examPickerMeta = form ? form.querySelector('[data-load-exam-picker-meta]') : null;
                    const selectedSummary = form ? form.querySelector('[data-load-selected-summary]') : null;
                    const questionsField = form ? form.querySelector('[name="questions_per_user"]') : null;
                    const questionHelp = form ? form.querySelector('[data-load-question-help]') : null;
                    const questionOptionsWrap = form ? form.querySelector('[data-load-question-options]') : null;
                    const manualTokenField = form ? form.querySelector('[name="manual_exam_token"]') : null;
                    const tokenSourceChip = form ? form.querySelector('[data-load-token-source-chip]') : null;
                    const tokenValueNode = form ? form.querySelector('[data-load-token-value]') : null;
                    const tokenHelpNode = form ? form.querySelector('[data-load-token-help]') : null;
                    const runningChip = document.querySelector('[data-load-running-chip]');
                    const fieldNames = [
                        'vus',
                        'iterations',
                        'questions_per_user',
                        'session_start_spread_ms',
                        'post_start_spread_ms',
                        'submit_mode',
                    ];

                    const buildCommand = function (exam, state) {
                        const parts = [
                            'cd ' + JSON.stringify('<workspace-for-' + String(exam.id || 0) + '>'),
                            'BASE_URL=' + JSON.stringify(state.baseUrl),
                            'EXAM_ID=' + String(exam.id || 0),
                        ];
                        if (state.examToken) {
                            parts.push('EXAM_TOKEN=' + JSON.stringify(state.examToken));
                        }
                        parts.push('VUS=' + String(state.vus));
                        parts.push('ITERATIONS=' + String(state.iterations));
                        parts.push('QUESTIONS_PER_USER=' + String(state.questionsPerUser));
                        parts.push('SESSION_START_SPREAD_MS=' + String(state.sessionSpread));
                        parts.push('POST_START_SPREAD_MS=' + String(state.postSpread));
                        parts.push('SUBMIT_MODE=' + JSON.stringify(state.submitMode));
                        parts.push('ENABLE_BATCH_SUBMIT=' + (state.enableBatchSubmit ? '1' : '0'));
                        parts.push(JSON.stringify(k6Path) + ' run --summary-export summary.json cbt_exam_1000_users.js');
                        return parts.join(' \\\n  ');
                    };

                    const getState = function () {
                        const baseUrlField = form ? form.querySelector('[name="base_url"]') : null;
                        const batchSubmitField = form ? form.querySelector('[name="enable_batch_submit"]') : null;
                        return {
                            baseUrl: baseUrlField ? String(baseUrlField.value || '').trim() : '',
                            examToken: manualTokenField && String(manualTokenField.value || '').trim() !== ''
                                ? String(manualTokenField.value || '').trim().toUpperCase()
                                : String(loadTestGlobalToken || ''),
                            vus: Number(form && form.querySelector('[name="vus"]') ? form.querySelector('[name="vus"]').value : 0) || 0,
                            iterations: Number(form && form.querySelector('[name="iterations"]') ? form.querySelector('[name="iterations"]').value : 1) || 1,
                            questionsPerUser: Number(form && form.querySelector('[name="questions_per_user"]') ? form.querySelector('[name="questions_per_user"]').value : 0) || 0,
                            sessionSpread: Number(form && form.querySelector('[name="session_start_spread_ms"]') ? form.querySelector('[name="session_start_spread_ms"]').value : 0) || 0,
                            postSpread: Number(form && form.querySelector('[name="post_start_spread_ms"]') ? form.querySelector('[name="post_start_spread_ms"]').value : 0) || 0,
                            submitMode: String(form && form.querySelector('[name="submit_mode"]') ? form.querySelector('[name="submit_mode"]').value : 'all'),
                            enableBatchSubmit: !!(batchSubmitField && batchSubmitField.checked)
                        };
                    };

                    const getSelectedExams = function () {
                        if (!form) {
                            return [];
                        }
                        const checkedIds = Array.prototype.slice.call(form.querySelectorAll('[data-load-exam-checkbox]:checked')).map(function (input) {
                            return Number(input.value || 0);
                        });
                        return exams.filter(function (exam) {
                            return checkedIds.indexOf(Number(exam.id || 0)) !== -1;
                        });
                    };

                    const renderSelectedExams = function (selectedExams) {
                        if (!selectedSummary) {
                            return;
                        }

                        selectedSummary.innerHTML = '';
                        if (!selectedExams.length) {
                            const emptyState = document.createElement('div');
                            emptyState.className = 'cbt-maintenance-load-selected-empty';
                            emptyState.textContent = 'Belum ada exam dipilih. Buka dropdown di atas lalu centang exam yang ingin dijalankan untuk load test.';
                            selectedSummary.appendChild(emptyState);
                            return;
                        }

                        selectedExams.forEach(function (exam) {
                            const card = document.createElement('article');
                            card.className = 'cbt-maintenance-load-selected-card';

                            const copy = document.createElement('div');
                            copy.className = 'cbt-maintenance-load-exam-copy';

                            const title = document.createElement('strong');
                            title.textContent = String(exam.title || ('Exam #' + String(exam.id || 0)));
                            copy.appendChild(title);

                            const meta = document.createElement('span');
                            meta.textContent = String(exam.subject_name || '') + ' · ' + String(exam.question_count || 0) + ' soal · ' + String(exam.duration_minutes || 0) + ' menit';
                            copy.appendChild(meta);

                            const schedule = document.createElement('span');
                            schedule.textContent = String(exam.schedule_label || 'Tanpa batas jadwal');
                            copy.appendChild(schedule);

                            const target = document.createElement('span');
                            const classes = Array.isArray(exam.target_kelas_list) && exam.target_kelas_list.length
                                ? exam.target_kelas_list.join(', ')
                                : 'Semua kelas';
                            target.textContent = 'Target kelas: ' + classes;
                            copy.appendChild(target);

                            card.appendChild(copy);
                            selectedSummary.appendChild(card);
                        });
                    };

                    const updateExamPickerSummary = function (selectedExams) {
                        if (examPickerLabel) {
                            if (!selectedExams.length) {
                                examPickerLabel.textContent = 'Belum ada exam dipilih';
                            } else if (selectedExams.length === 1) {
                                examPickerLabel.textContent = String(selectedExams[0].title || '1 exam dipilih');
                            } else {
                                examPickerLabel.textContent = String(selectedExams.length) + ' exam dipilih';
                            }
                        }

                        if (examPickerMeta) {
                            if (!selectedExams.length) {
                                examPickerMeta.textContent = 'Buka daftar exam aktif lalu centang exam yang ingin dijalankan.';
                            } else if (selectedExams.length === 1) {
                                examPickerMeta.textContent = '1 job k6 akan dibuat untuk exam ini.';
                            } else {
                                examPickerMeta.textContent = String(selectedExams.length) + ' job k6 akan dibuat dan dijalankan paralel.';
                            }
                        }
                    };

                    const updateTokenState = function () {
                        if (!tokenSourceChip && !tokenValueNode && !tokenHelpNode) {
                            return;
                        }

                        const manualToken = manualTokenField ? String(manualTokenField.value || '').trim().toUpperCase() : '';
                        const globalToken = String(loadTestGlobalToken || '').trim().toUpperCase();

                        if (manualToken !== '') {
                            if (tokenSourceChip) {
                                tokenSourceChip.textContent = 'Manual override';
                                tokenSourceChip.className = 'cbt-maintenance-chip cbt-maintenance-chip--running';
                            }
                            if (tokenValueNode) {
                                tokenValueNode.textContent = manualToken;
                            }
                            if (tokenHelpNode) {
                                tokenHelpNode.textContent = 'Token manual ini akan dipakai untuk run sekarang dan mengoverride token global aktif.';
                            }
                            return;
                        }

                        if (globalToken !== '') {
                            if (tokenSourceChip) {
                                tokenSourceChip.textContent = 'Global aktif';
                                tokenSourceChip.className = 'cbt-maintenance-chip cbt-maintenance-chip--done';
                            }
                            if (tokenValueNode) {
                                tokenValueNode.textContent = globalToken;
                            }
                            if (tokenHelpNode) {
                                tokenHelpNode.textContent = 'Token global aktif ini akan dipakai otomatis selama field override tetap kosong.';
                            }
                            return;
                        }

                        if (tokenSourceChip) {
                            tokenSourceChip.textContent = 'Token belum ada';
                            tokenSourceChip.className = 'cbt-maintenance-chip cbt-maintenance-chip--danger';
                        }
                        if (tokenValueNode) {
                            tokenValueNode.textContent = '-';
                        }
                        if (tokenHelpNode) {
                            tokenHelpNode.textContent = 'Belum ada token global aktif. Isi manual token override jika run ini tetap harus memakai token exam tertentu.';
                        }
                    };

                    const buildQuestionOptionValues = function (minCount, maxCount) {
                        const values = [0];
                        [10, 20, 30, 40, 50].forEach(function (value) {
                            if (value > 0 && value < minCount) {
                                values.push(value);
                            }
                        });
                        if (minCount > 0) {
                            values.push(minCount);
                        }
                        if (maxCount > minCount) {
                            values.push(maxCount);
                        }

                        return values.filter(function (value, index, array) {
                            return array.indexOf(value) === index;
                        }).sort(function (left, right) {
                            return left - right;
                        });
                    };

                    const formatNumber = function (value) {
                        return numberFormatter ? numberFormatter.format(Number(value || 0)) : String(value || 0);
                    };

                    const updateQuestionFieldMeta = function (selectedExams) {
                        if (!questionsField && !questionHelp && !questionOptionsWrap) {
                            return;
                        }

                        const counts = selectedExams.map(function (exam) {
                            return Number(exam.question_count || 0) || 0;
                        }).filter(function (count) {
                            return count > 0;
                        });

                        if (questionOptionsWrap) {
                            questionOptionsWrap.innerHTML = '';
                        }

                        if (!counts.length) {
                            if (questionHelp) {
                                questionHelp.innerHTML = '<code>0</code> berarti semua soal exam akan dipakai. Pilih exam dulu untuk melihat saran jumlah soal berdasarkan exam yang dipilih.';
                            }
                            if (questionsField) {
                                questionsField.setAttribute('max', '500');
                            }
                            return;
                        }

                        const minCount = Math.min.apply(null, counts);
                        const maxCount = Math.max.apply(null, counts);
                        const sameCount = minCount === maxCount;
                        const currentValue = questionsField ? (Number(questionsField.value || 0) || 0) : 0;

                        if (questionsField) {
                            questionsField.setAttribute('max', String(Math.min(500, maxCount)));
                        }

                        if (questionHelp) {
                            if (sameCount) {
                                questionHelp.innerHTML = 'Exam terpilih punya <code>' + formatNumber(minCount) + '</code> soal. Gunakan <code>0</code> jika ingin memakai semua soal, atau pilih angka cepat di bawah.';
                            } else {
                                questionHelp.innerHTML = 'Exam terpilih punya <code>' + formatNumber(minCount) + '</code> sampai <code>' + formatNumber(maxCount) + '</code> soal. Nilai <code>' + formatNumber(minCount) + '</code> aman untuk semua exam, sedangkan <code>0</code> berarti semua soal tiap exam dipakai.';
                            }
                        }

                        if (!questionOptionsWrap || !questionsField) {
                            return;
                        }

                        buildQuestionOptionValues(minCount, maxCount).forEach(function (value) {
                            const button = document.createElement('button');
                            button.type = 'button';
                            button.className = 'cbt-maintenance-load-quick-option' + (currentValue === value ? ' is-active' : '');
                            button.setAttribute('data-load-question-option', String(value));

                            if (value === 0) {
                                button.textContent = sameCount ? 'Semua (' + formatNumber(minCount) + ')' : 'Semua per exam';
                            } else if (!sameCount && value === minCount) {
                                button.textContent = formatNumber(value) + ' aman semua';
                            } else if (!sameCount && value === maxCount) {
                                button.textContent = formatNumber(value) + ' maks';
                            } else {
                                button.textContent = formatNumber(value);
                            }

                            button.addEventListener('click', function () {
                                questionsField.value = String(value);
                                updateQuestionFieldMeta(selectedExams);
                                updateCommandPreview();
                            });
                            questionOptionsWrap.appendChild(button);
                        });
                    };

                    const applyPreset = function () {
                        if (!form || !presetSelect) {
                            return;
                        }
                        const presetKey = String(presetSelect.value || '');
                        const preset = profiles[presetKey] || null;
                        if (!preset) {
                            return;
                        }
                        fieldNames.forEach(function (fieldName) {
                            const field = form.querySelector('[name="' + fieldName + '"]');
                            if (field && preset[fieldName] !== undefined) {
                                field.value = String(preset[fieldName]);
                            }
                        });

                        const batchField = form.querySelector('[name="enable_batch_submit"]');
                        if (batchField && preset.enable_batch_submit !== undefined) {
                            batchField.checked = Number(preset.enable_batch_submit || 0) === 1;
                        }
                    };

                    const updateCommandPreview = function () {
                        if (!commandPreview) {
                            return;
                        }
                        const selectedExams = getSelectedExams();
                        updateExamPickerSummary(selectedExams);
                        renderSelectedExams(selectedExams);
                        updateQuestionFieldMeta(selectedExams);
                        updateTokenState();
                        const state = getState();
                        if (warningChip) {
                            const needsReuse = readyUsers > 0 && state.vus > readyUsers;
                            warningChip.textContent = needsReuse ? 'User akan di-reuse' : 'User cukup';
                            warningChip.className = 'cbt-maintenance-chip cbt-maintenance-chip--' + (needsReuse ? 'danger' : 'idle');
                        }
                        if (!selectedExams.length) {
                            commandPreview.textContent = 'Belum ada exam dipilih.';
                            return;
                        }

                        const blocks = selectedExams.map(function (exam) {
                            return '# ' + String(exam.title || ('Exam #' + String(exam.id || 0))) + '\n' + buildCommand(exam, state);
                        });
                        commandPreview.textContent = blocks.join('\n\n');
                    };

                    const initLoadJobSelector = function (preferredJobId) {
                        if (!jobsWrap) {
                            return;
                        }

                        const selector = jobsWrap.querySelector('[data-load-job-selector]');
                        const cards = Array.prototype.slice.call(jobsWrap.querySelectorAll('[data-load-job-card]'));
                        if (!selector || !cards.length) {
                            return;
                        }

                        const availableIds = cards.map(function (card) {
                            return String(card.getAttribute('data-load-job-id') || '');
                        });
                        const applySelection = function (jobId) {
                            let resolvedId = String(jobId || '').trim();
                            if (availableIds.indexOf(resolvedId) === -1) {
                                resolvedId = availableIds.length ? availableIds[0] : '';
                            }
                            selector.value = resolvedId;
                            cards.forEach(function (card) {
                                const active = String(card.getAttribute('data-load-job-id') || '') === resolvedId;
                                card.hidden = !active;
                            });
                        };

                        selector.addEventListener('change', function () {
                            applySelection(String(selector.value || ''));
                        });

                        applySelection(String(preferredJobId || selector.value || ''));
                    };

                    let pollingTimer = null;
                    const schedulePolling = function (runningCount) {
                        if (pollingTimer) {
                            window.clearTimeout(pollingTimer);
                            pollingTimer = null;
                        }
                        if (Number(runningCount || 0) <= 0 || !jobsWrap) {
                            return;
                        }
                        pollingTimer = window.setTimeout(function () {
                            refreshJobs(false);
                        }, 5000);
                    };

                    const refreshJobs = function (focusLoadTab) {
                        if (!jobsWrap) {
                            return;
                        }
                        const ajaxUrl = String(jobsWrap.getAttribute('data-load-jobs-ajax-url') || '');
                        const ajaxNonce = String(jobsWrap.getAttribute('data-load-jobs-ajax-nonce') || '');
                        if (ajaxUrl === '' || ajaxNonce === '' || typeof window.fetch !== 'function') {
                            window.location.reload();
                            return;
                        }

                        const currentJobSelector = jobsWrap.querySelector('[data-load-job-selector]');
                        const currentJobId = currentJobSelector ? String(currentJobSelector.value || '') : '';
                        const url = new URL(ajaxUrl, window.location.origin);
                        url.searchParams.set('nonce', ajaxNonce);

                        window.fetch(url.toString(), {
                            credentials: 'same-origin',
                            headers: {
                                Accept: 'application/json'
                            }
                        }).then(function (response) {
                            return response.json();
                        }).then(function (payload) {
                            if (!payload || !payload.success || !payload.data) {
                                return;
                            }
                            jobsWrap.innerHTML = String(payload.data.html || '');
                            jobsWrap.setAttribute('data-load-running-count', String(payload.data.running_count || 0));
                            initLoadJobSelector(currentJobId);
                            if (runningChip) {
                                runningChip.textContent = Number(payload.data.running_count || 0) > 0
                                    ? String(payload.data.running_count || 0) + ' running'
                                    : String(payload.data.job_count || 0) + ' total';
                                runningChip.className = 'cbt-maintenance-chip cbt-maintenance-chip--' + (Number(payload.data.running_count || 0) > 0 ? 'running' : 'idle');
                            }
                            if (focusLoadTab) {
                                activateTab('load', true);
                            }
                            schedulePolling(Number(payload.data.running_count || 0));
                        }).catch(function () {
                            schedulePolling(0);
                        });
                    };

                    if (presetSelect) {
                        presetSelect.addEventListener('change', function () {
                            applyPreset();
                            updateCommandPreview();
                        });
                    }
                    if (form) {
                        Array.prototype.slice.call(form.querySelectorAll('input, select')).forEach(function (field) {
                            field.addEventListener('change', updateCommandPreview);
                            field.addEventListener('input', updateCommandPreview);
                        });
                    }
                    document.querySelectorAll('[data-load-exam-checkbox]').forEach(function (checkbox) {
                        checkbox.addEventListener('change', updateCommandPreview);
                    });
                    if (refreshButton) {
                        refreshButton.addEventListener('click', function () {
                            refreshJobs(true);
                        });
                    }
                    updateCommandPreview();
                    initLoadJobSelector('');
                    schedulePolling(Number(jobsWrap && jobsWrap.getAttribute('data-load-running-count') ? jobsWrap.getAttribute('data-load-running-count') : 0));
                };

                initSeedPresetSummary();
                initLoadTestPanel();
            }());
        </script>
        <?php
    }

    public static function render_questions_page(?string $forced_question_type = null): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        global $wpdb;

        $exam_table = $wpdb->prefix . 'cbt_exams';
        $subject_table = $wpdb->prefix . 'cbt_subjects';
        $question_table = $wpdb->prefix . 'cbt_questions';
        $option_table = $wpdb->prefix . 'cbt_options';
        $is_admin_scope = self::is_admin_scope();
        $current_user_id = get_current_user_id();
        $allowed_question_types = ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        $question_type_labels = [
            'multiple_choice' => 'Multiple Choice',
            'multiple_answer' => 'Multiple Answer',
            'true_false' => 'True/False',
            'true_false_matrix' => 'True/False Matrix',
            'short_answer' => 'Short Answer',
            'essay' => 'Essay',
        ];
        $current_page_slug = self::normalize_question_page_slug(isset($_GET['page']) ? wp_unslash($_GET['page']) : 'cbt-question-bank');
        $page_locked_type = self::forced_question_type_for_page($current_page_slug);
        $active_question_type = '';
        if (is_string($forced_question_type) && in_array($forced_question_type, $allowed_question_types, true)) {
            $active_question_type = $forced_question_type;
        } elseif ($page_locked_type !== '') {
            $active_question_type = $page_locked_type;
        } elseif (isset($_GET['question_type'])) {
            $from_query = sanitize_text_field(wp_unslash($_GET['question_type']));
            if (in_array($from_query, $allowed_question_types, true)) {
                $active_question_type = $from_query;
            }
        }
        $lock_question_type = ($active_question_type !== '');
        $import_type_help_map = [
            'multiple_choice' => 'Mode import aktif: Multiple Choice. DOCX didukung (maks 5 opsi, jawaban nomor opsi, gambar bisa ditempel).',
            'multiple_answer' => 'Mode import aktif: Multiple Answer. DOCX didukung (maks 12 opsi, jawaban bisa lebih dari satu: contoh 1,3,5).',
            'true_false' => 'Mode import aktif: True/False. DOCX didukung (jawaban: true/false).',
            'true_false_matrix' => 'Mode import aktif: True/False Matrix. DOCX didukung (isi PERNYATAAN_1..10 dan KUNCI_1..10: true/false).',
            'short_answer' => 'Mode import aktif: Short Answer. DOCX didukung (maks 8 jawaban valid per soal, gunakan placeholder [INPUT_1] s.d. [INPUT_8] di teks soal).',
            'essay' => 'Mode import aktif: Essay. DOCX didukung (wajib isi acuan jawaban/rubrik).',
        ];
        $import_active_type = $lock_question_type ? $active_question_type : 'multiple_choice';
        $import_help_text = $import_type_help_map[$import_active_type] ?? $import_type_help_map['multiple_choice'];
        $import_allow_docx = in_array($import_active_type, ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'], true);
        $import_file_accept = '.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document';

        $bank_exam_title_like = 'Bank Soal - %';
        $exam_where_parts = [
            $wpdb->prepare('e.title LIKE %s', $bank_exam_title_like),
        ];
        if (!$is_admin_scope) {
            $exam_where_parts[] = $wpdb->prepare('e.created_by = %d', $current_user_id);
        }
        $exam_where = ' WHERE ' . implode(' AND ', $exam_where_parts);
        $exams = $wpdb->get_results(
            "SELECT e.id, e.title, e.subject_id, s.name AS subject_name
             FROM {$exam_table} e
             LEFT JOIN {$subject_table} s ON s.id = e.subject_id
             {$exam_where}
             ORDER BY e.id DESC",
            ARRAY_A
        );

        if ($is_admin_scope) {
            $subjects = $wpdb->get_results(
                "SELECT id, name, code
                 FROM {$subject_table}
                 ORDER BY name ASC",
                ARRAY_A
            );
        } else {
            $subjects = $wpdb->get_results(
                $wpdb->prepare(
                    "SELECT DISTINCT s.id, s.name, s.code
                     FROM {$subject_table} s
                     INNER JOIN {$exam_table} e ON e.subject_id = s.id
                     WHERE e.created_by = %d
                     ORDER BY s.name ASC",
                    $current_user_id
                ),
                ARRAY_A
            );
        }

        $exam_subject_map = [];
        foreach ($exams as $exam) {
            $exam_subject_map[(int) $exam['id']] = (int) ($exam['subject_id'] ?? 0);
        }

        $editing_id = isset($_GET['edit']) ? absint($_GET['edit']) : 0;
        $editing_question = null;
        $editing_options = [];
        $selected_subject_id = 0;
        $editing_question_is_bank_exam = false;
        $view_id = isset($_GET['view']) ? absint($_GET['view']) : 0;
        $view_question = null;
        $view_options = [];
        $view_detail = [];

        if ($editing_id > 0) {
            if ($is_admin_scope) {
                $editing_question = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$question_table} WHERE id = %d", $editing_id), ARRAY_A);
            } else {
                $editing_question = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT q.*
                         FROM {$question_table} q
                         INNER JOIN {$exam_table} e ON e.id = q.exam_id
                         WHERE q.id = %d AND e.created_by = %d",
                        $editing_id,
                        $current_user_id
                    ),
                    ARRAY_A
                );
            }
            $editing_options = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$option_table} WHERE question_id = %d ORDER BY id ASC", $editing_id), ARRAY_A);
            if ($editing_question && isset($editing_question['exam_id'])) {
                $editing_exam_id = (int) ($editing_question['exam_id'] ?? 0);
                $selected_subject_id = (int) ($exam_subject_map[$editing_exam_id] ?? 0);
                $editing_question_is_bank_exam = $selected_subject_id > 0;
                if ($selected_subject_id <= 0 && $editing_exam_id > 0) {
                    $selected_subject_id = (int) $wpdb->get_var(
                        $wpdb->prepare(
                            "SELECT subject_id
                             FROM {$exam_table}
                             WHERE id = %d
                             LIMIT 1",
                            $editing_exam_id
                        )
                    );
                }
            }
        }

        if ($view_id > 0) {
            if ($is_admin_scope) {
                $view_question = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$question_table} WHERE id = %d", $view_id), ARRAY_A);
            } else {
                $view_question = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT q.*
                         FROM {$question_table} q
                         INNER JOIN {$exam_table} e ON e.id = q.exam_id
                         WHERE q.id = %d AND e.created_by = %d",
                        $view_id,
                        $current_user_id
                    ),
                    ARRAY_A
                );
            }

            if ($view_question) {
                $view_options = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$option_table} WHERE question_id = %d ORDER BY id ASC", $view_id), ARRAY_A);
                $view_detail = self::get_question_type_detail((int) $view_id, (string) ($view_question['question_type'] ?? ''));
            }
        }

        $notice = isset($_GET['cbt_msg']) ? sanitize_text_field(wp_unslash($_GET['cbt_msg'])) : '';
        $error = isset($_GET['cbt_err']) ? sanitize_text_field(wp_unslash($_GET['cbt_err'])) : '';
        $question_import_token = isset($_GET['cbt_question_import_token']) ? sanitize_key((string) wp_unslash($_GET['cbt_question_import_token'])) : '';
        $question_import_state = null;
        $question_import_total = 0;
        $question_import_offset = 0;
        $question_import_created = 0;
        $question_import_failed = 0;
        $question_import_progress_percent = 0.0;
        $question_import_is_running = false;
        $question_import_continue_url = '';
        if ($question_import_token !== '') {
            $question_import_state = self::get_question_import_state_for_current_user($question_import_token);
            if (is_array($question_import_state)) {
                $question_import_total = max(0, isset($question_import_state['total']) ? (int) $question_import_state['total'] : 0);
                $question_import_offset = max(0, isset($question_import_state['offset']) ? (int) $question_import_state['offset'] : 0);
                if ($question_import_total > 0 && $question_import_offset > $question_import_total) {
                    $question_import_offset = $question_import_total;
                }
                $question_import_created = max(0, isset($question_import_state['created']) ? (int) $question_import_state['created'] : 0);
                $question_import_failed = max(0, isset($question_import_state['failed']) ? (int) $question_import_state['failed'] : 0);
                $question_import_progress_percent = $question_import_total > 0
                    ? round(((float) $question_import_offset / (float) $question_import_total) * 100, 2)
                    : 0.0;
                $question_import_is_running = $question_import_total > 0 && $question_import_offset < $question_import_total;
                $question_import_continue_url = add_query_arg(
                    [
                        'action' => 'cbt_import_questions',
                        'cbt_question_import_token' => $question_import_token,
                    ],
                    admin_url('admin-post.php')
                );
            } elseif ($notice === '' && $error === '') {
                $error = 'Sesi import soal tidak ditemukan atau sudah berakhir. Silakan upload ulang file.';
            }
        }
        $show_import_panel_first = is_array($question_import_state);
        $question_delete_token = isset($_GET['cbt_question_delete_token']) ? sanitize_key((string) wp_unslash($_GET['cbt_question_delete_token'])) : '';
        $question_delete_state = null;
        $question_delete_total = 0;
        $question_delete_offset = 0;
        $question_delete_deleted = 0;
        $question_delete_failed = 0;
        $question_delete_progress_percent = 0.0;
        $question_delete_is_running = false;
        $question_delete_continue_url = '';
        if ($question_delete_token !== '') {
            $question_delete_state = self::get_question_delete_state_for_current_user($question_delete_token);
            if (is_array($question_delete_state)) {
                $question_delete_total = max(0, isset($question_delete_state['total']) ? (int) $question_delete_state['total'] : 0);
                $question_delete_offset = max(0, isset($question_delete_state['offset']) ? (int) $question_delete_state['offset'] : 0);
                if ($question_delete_total > 0 && $question_delete_offset > $question_delete_total) {
                    $question_delete_offset = $question_delete_total;
                }
                $question_delete_deleted = max(0, isset($question_delete_state['deleted']) ? (int) $question_delete_state['deleted'] : 0);
                $question_delete_failed = max(0, isset($question_delete_state['failed']) ? (int) $question_delete_state['failed'] : 0);
                $question_delete_progress_percent = $question_delete_total > 0
                    ? round(((float) $question_delete_offset / (float) $question_delete_total) * 100, 2)
                    : 0.0;
                $question_delete_is_running = $question_delete_total > 0 && $question_delete_offset < $question_delete_total;
                $question_delete_continue_url = add_query_arg(
                    [
                        'action' => 'cbt_bulk_delete_questions',
                        'cbt_question_delete_token' => $question_delete_token,
                    ],
                    admin_url('admin-post.php')
                );
            } elseif ($notice === '' && $error === '') {
                $error = 'Sesi hapus soal tidak ditemukan atau sudah berakhir. Silakan pilih ulang soal yang ingin dihapus.';
            }
        }

        if ($lock_question_type && $editing_question && (string) ($editing_question['question_type'] ?? '') !== $active_question_type) {
            $editing_question = null;
            $editing_options = [];
            $selected_subject_id = 0;
            if ($error === '') {
                $error = 'Edit dibatasi untuk jenis soal submenu ini.';
            }
        }

        $list_filter_type = '';
        if ($lock_question_type) {
            $list_filter_type = $active_question_type;
        } elseif (isset($_GET['filter_type'])) {
            $requested_filter_type = sanitize_text_field(wp_unslash($_GET['filter_type']));
            if (in_array($requested_filter_type, $allowed_question_types, true)) {
                $list_filter_type = $requested_filter_type;
            }
        }
        $list_per_page = isset($_GET['cbt_question_per_page'])
            ? self::normalize_standard_list_per_page(absint(wp_unslash($_GET['cbt_question_per_page'])))
            : 20;
        $list_current_page = isset($_GET['cbt_question_paged']) ? max(1, absint(wp_unslash($_GET['cbt_question_paged']))) : 1;

        $question_where_parts = [];
        $question_where_parts_legacy = [];
        if (!$is_admin_scope) {
            $created_by_clause = $wpdb->prepare('e.created_by = %d', $current_user_id);
            $question_where_parts[] = $created_by_clause;
            $question_where_parts_legacy[] = $created_by_clause;
        }
        if ($list_filter_type !== '') {
            $type_clause = $wpdb->prepare('q.question_type = %s', $list_filter_type);
            $question_where_parts[] = $type_clause;
            $question_where_parts_legacy[] = $type_clause;
        }
        $question_where_parts[] = $wpdb->prepare('e.title LIKE %s', $bank_exam_title_like);
        $question_where = '';
        if (!empty($question_where_parts)) {
            $question_where = ' WHERE ' . implode(' AND ', $question_where_parts);
        }
        $question_where_legacy = '';
        if (!empty($question_where_parts_legacy)) {
            $question_where_legacy = ' WHERE ' . implode(' AND ', $question_where_parts_legacy);
        }
        $total_questions = (int) $wpdb->get_var(
            "SELECT COUNT(*)
             FROM {$question_table} q
             INNER JOIN {$exam_table} e ON e.id = q.exam_id
             {$question_where}"
        );
        $active_question_where = $question_where;
        if ($total_questions === 0) {
            $active_question_where = $question_where_legacy;
            $total_questions = (int) $wpdb->get_var(
                "SELECT COUNT(*)
                 FROM {$question_table} q
                 INNER JOIN {$exam_table} e ON e.id = q.exam_id
                 {$active_question_where}"
            );
        }
        $total_question_pages = max(1, (int) ceil($total_questions / $list_per_page));
        if ($total_questions > 0 && $list_current_page > $total_question_pages) {
            $list_current_page = $total_question_pages;
        }
        $question_offset = ($list_current_page - 1) * $list_per_page;
        $question_limit = (int) $list_per_page;
        $question_offset = (int) $question_offset;
        $questions = $wpdb->get_results(
            "SELECT q.*, e.title AS exam_title, s.name AS subject_name
             FROM {$question_table} q
             INNER JOIN {$exam_table} e ON e.id = q.exam_id
             LEFT JOIN {$subject_table} s ON s.id = e.subject_id
             {$active_question_where}
             ORDER BY q.id DESC
             LIMIT {$question_limit} OFFSET {$question_offset}",
            ARRAY_A
        );
        $question_list_args = [
            'page' => $current_page_slug,
            'cbt_question_per_page' => $list_per_page,
            'cbt_question_paged' => $list_current_page,
        ];
        if ($list_filter_type !== '') {
            $question_list_args['filter_type'] = $list_filter_type;
        }

        $editing_type = $editing_question['question_type'] ?? ($lock_question_type ? $active_question_type : 'multiple_choice');
        $editing_detail = [];
        if ($editing_question && isset($editing_question['id'])) {
            $editing_detail = self::get_question_type_detail((int) $editing_question['id'], $editing_type);
        }

        $editing_short_answer_values = self::normalize_short_answer_values((string) ($editing_detail['correct_text'] ?? ($editing_question['correct_text'] ?? '')));
        $editing_short_answer_inputs = array_fill(1, 8, '');
        foreach ($editing_short_answer_values as $idx => $value) {
            $pos = $idx + 1;
            if ($pos > 8) {
                break;
            }
            $editing_short_answer_inputs[$pos] = $value;
        }
        $editing_short_answer_payload = !empty($editing_short_answer_values) ? wp_json_encode($editing_short_answer_values) : '';
        $editing_essay_answer = (string) ($editing_detail['rubric_text'] ?? ($editing_question['correct_text'] ?? ''));
        $editing_tf_matrix_values = self::normalize_true_false_matrix_config((string) ($editing_question['correct_text'] ?? ''));
        $tf_matrix_rows = array_fill(1, 10, ['text' => '', 'answer' => 'true']);
        foreach ($editing_tf_matrix_values as $idx => $row) {
            $pos = $idx + 1;
            if ($pos > 10) {
                break;
            }
            $tf_matrix_rows[$pos] = [
                'text' => (string) ($row['text'] ?? ''),
                'answer' => ((string) ($row['answer'] ?? 'true') === 'false') ? 'false' : 'true',
            ];
        }
        $editing_tf_matrix_payload = !empty($editing_tf_matrix_values)
            ? (string) wp_json_encode(['statements' => array_values($editing_tf_matrix_values)])
            : '';
        $mc_option_values = array_fill(1, 5, '');
        $ma_option_values = array_fill(1, 12, '');
        $ma_option_correct = array_fill(1, 12, false);
        $mc_correct_index = 1;
        $legacy_tf_seed = (string) ($editing_detail['correct_text'] ?? ($editing_question['correct_text'] ?? ''));
        $tf_correct = ((int) ($editing_detail['correct_value'] ?? (strtolower(trim($legacy_tf_seed)) === 'false' ? 0 : 1)) === 0)
            ? 'false'
            : 'true';

        if (!empty($editing_options)) {
            if ($editing_type === 'multiple_choice') {
                foreach ($editing_options as $idx => $opt) {
                    $pos = $idx + 1;
                    if ($pos > 5) {
                        break;
                    }
                    $mc_option_values[$pos] = (string) ($opt['option_text'] ?? '');
                    if ((int) ($opt['is_correct'] ?? 0) === 1) {
                        $mc_correct_index = $pos;
                    }
                }
            } elseif ($editing_type === 'multiple_answer') {
                foreach ($editing_options as $idx => $opt) {
                    $pos = $idx + 1;
                    if ($pos > 12) {
                        break;
                    }
                    $ma_option_values[$pos] = (string) ($opt['option_text'] ?? '');
                    $ma_option_correct[$pos] = ((int) ($opt['is_correct'] ?? 0) === 1);
                }
            } elseif ($editing_type === 'true_false' && empty($editing_detail)) {
                foreach ($editing_options as $opt) {
                    if ((int) ($opt['is_correct'] ?? 0) === 1) {
                        $txt = strtolower(trim((string) $opt['option_text']));
                        if ($txt === 'false') {
                            $tf_correct = 'false';
                        } else {
                            $tf_correct = 'true';
                        }
                        break;
                    }
                }
            }
        }

        if ($editing_type === 'short_answer') {
            $editing_short_answer_values = self::normalize_short_answer_values((string) ($editing_detail['correct_text'] ?? ($editing_question['correct_text'] ?? '')));
            $editing_short_answer_inputs = array_fill(1, 8, '');
            foreach ($editing_short_answer_values as $idx => $value) {
                $pos = $idx + 1;
                if ($pos > 8) {
                    break;
                }
                $editing_short_answer_inputs[$pos] = $value;
            }
            $editing_short_answer_payload = !empty($editing_short_answer_values) ? wp_json_encode($editing_short_answer_values) : '';
        }

        if ($editing_type === 'essay') {
            $editing_essay_answer = (string) ($editing_detail['rubric_text'] ?? ($editing_question['correct_text'] ?? ''));
        }

        if ($editing_type === 'true_false_matrix') {
            $editing_tf_matrix_values = self::normalize_true_false_matrix_config((string) ($editing_question['correct_text'] ?? ''));
            $tf_matrix_rows = array_fill(1, 10, ['text' => '', 'answer' => 'true']);
            foreach ($editing_tf_matrix_values as $idx => $row) {
                $pos = $idx + 1;
                if ($pos > 10) {
                    break;
                }
                $tf_matrix_rows[$pos] = [
                    'text' => (string) ($row['text'] ?? ''),
                    'answer' => ((string) ($row['answer'] ?? 'true') === 'false') ? 'false' : 'true',
                ];
            }
            $editing_tf_matrix_payload = !empty($editing_tf_matrix_values)
                ? (string) wp_json_encode(['statements' => array_values($editing_tf_matrix_values)])
                : '';
        }

        $initial_subject_id = $selected_subject_id > 0
            ? $selected_subject_id
            : (int) ($subjects[0]['id'] ?? 0);
        $default_question_tab = 'list';
        if ($total_questions === 0) {
            $default_question_tab = 'form';
        }
        if ($show_import_panel_first) {
            $default_question_tab = 'import';
        }
        if (!empty($editing_question)) {
            $default_question_tab = 'form';
        }
        if (!empty($view_question) || is_array($question_delete_state)) {
            $default_question_tab = 'list';
        }
        $question_tab_is_forced = !empty($editing_question) || $show_import_panel_first || !empty($view_question) || is_array($question_delete_state);
        $question_clear_edit_url = add_query_arg($question_list_args, admin_url('admin.php'));
        $question_reset_args = [
            'page' => $current_page_slug,
            'cbt_question_per_page' => $list_per_page,
        ];
        if ($lock_question_type && $list_filter_type !== '') {
            $question_reset_args['filter_type'] = $list_filter_type;
        }
        $question_reset_url = add_query_arg($question_reset_args, admin_url('admin.php'));
        $question_scope_label = $lock_question_type
            ? (string) ($question_type_labels[$active_question_type] ?? $active_question_type)
            : 'Semua tipe';
        ?>
        <div
            class="wrap cbt-questions-page"
            data-cbt-questions-default-tab="<?php echo esc_attr($default_question_tab); ?>"
            data-cbt-questions-force-tab="<?php echo $question_tab_is_forced ? '1' : '0'; ?>"
        >
            <div class="cbt-questions-shell">
                <section class="cbt-questions-hero">
                    <div class="cbt-questions-hero-copy">
                        <span class="cbt-questions-kicker">Questions</span>
                        <h1>CBT Questions</h1>
                        <p>Kelola bank soal CBT melalui tab terpisah agar proses tambah manual, import, dan peninjauan daftar soal terasa lebih fokus dan tidak padat dalam satu halaman panjang.</p>
                    </div>
                    <div class="cbt-questions-overview" aria-hidden="true">
                        <span class="cbt-questions-pill"><?php echo esc_html(sprintf('Total: %d soal', $total_questions)); ?></span>
                        <span class="cbt-questions-pill"><?php echo esc_html($question_scope_label); ?></span>
                        <span class="cbt-questions-pill"><?php echo esc_html(!empty($editing_question) ? 'Mode edit aktif' : (is_array($question_import_state) ? 'Import berjalan' : 'Input siap')); ?></span>
                    </div>
                </section>

                <?php if ($notice): ?>
                    <div class="notice notice-success is-dismissible"><p><?php echo esc_html($notice); ?></p></div>
                <?php endif; ?>
                <?php if ($error): ?>
                    <div class="notice notice-error is-dismissible"><p><?php echo esc_html($error); ?></p></div>
                <?php endif; ?>
                <?php if ($lock_question_type): ?>
                    <div class="notice notice-info"><p>
                        Submenu aktif: <strong><?php echo esc_html((string) ($question_type_labels[$active_question_type] ?? $active_question_type)); ?></strong>.
                        Form dan daftar soal difilter ke jenis ini.
                    </p></div>
                <?php endif; ?>

                <style>
                    .cbt-questions-page {
                        max-width: 1180px;
                    }
                    .cbt-questions-shell {
                        display: grid;
                        gap: 18px;
                        margin-top: 18px;
                    }
                    .cbt-questions-hero {
                        display: flex;
                        align-items: flex-start;
                        justify-content: space-between;
                        gap: 22px;
                        padding: 24px 28px;
                        border: 1px solid #d7dbe2;
                        border-radius: 22px;
                        background:
                            radial-gradient(circle at top right, rgba(34, 113, 177, 0.10), transparent 34%),
                            linear-gradient(135deg, #ffffff 0%, #f6f9fc 100%);
                        box-shadow: 0 18px 40px rgba(15, 23, 42, 0.06);
                    }
                    .cbt-questions-hero-copy {
                        max-width: 700px;
                    }
                    .cbt-questions-kicker {
                        display: inline-flex;
                        align-items: center;
                        min-height: 28px;
                        padding: 0 12px;
                        border-radius: 999px;
                        background: #e8f1ff;
                        color: #0f4fa8;
                        font-size: 12px;
                        font-weight: 700;
                        letter-spacing: 0.06em;
                        text-transform: uppercase;
                    }
                    .cbt-questions-hero h1 {
                        margin: 12px 0 8px;
                        font-size: 30px;
                        line-height: 1.15;
                    }
                    .cbt-questions-hero p {
                        margin: 0;
                        color: #4b5563;
                        font-size: 14px;
                        line-height: 1.6;
                    }
                    .cbt-questions-overview {
                        display: grid;
                        gap: 10px;
                        min-width: 260px;
                    }
                    .cbt-questions-pill {
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        min-height: 34px;
                        padding: 0 14px;
                        border-radius: 999px;
                        background: rgba(255, 255, 255, 0.92);
                        border: 1px solid #d7e4f5;
                        color: #1e3a5f;
                        font-size: 13px;
                        font-weight: 600;
                    }
                    .cbt-questions-tabs {
                        display: flex;
                        align-items: center;
                        gap: 10px;
                        flex-wrap: wrap;
                    }
                    .cbt-questions-tab {
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        min-height: 42px;
                        padding: 0 16px;
                        border: 1px solid #c9d5e6;
                        border-radius: 12px;
                        background: #ffffff;
                        color: #334155;
                        font-size: 13px;
                        font-weight: 600;
                        cursor: pointer;
                        transition: all 0.16s ease;
                    }
                    .cbt-questions-tab:hover,
                    .cbt-questions-tab:focus {
                        border-color: #2271b1;
                        color: #0f4fa8;
                        outline: none;
                        box-shadow: 0 0 0 3px rgba(34, 113, 177, 0.12);
                    }
                    .cbt-questions-tab.is-active {
                        border-color: #2271b1;
                        background: #2271b1;
                        color: #ffffff;
                        box-shadow: 0 10px 24px rgba(34, 113, 177, 0.18);
                    }
                    .cbt-questions-panel {
                        display: none;
                        padding: 24px;
                        border: 1px solid #dcdcde;
                        border-radius: 20px;
                        background: #ffffff;
                        box-shadow: 0 12px 30px rgba(15, 23, 42, 0.04);
                    }
                    .cbt-questions-panel.is-active {
                        display: block;
                    }
                    .cbt-questions-panel-header {
                        display: flex;
                        align-items: flex-start;
                        justify-content: space-between;
                        gap: 16px;
                        margin-bottom: 18px;
                    }
                    .cbt-questions-panel-header h2 {
                        margin: 0 0 6px;
                        font-size: 18px;
                        line-height: 1.2;
                    }
                    .cbt-questions-panel-header p {
                        margin: 0;
                        color: #646970;
                        line-height: 1.55;
                    }
                    .cbt-questions-chip {
                        display: inline-flex;
                        align-items: center;
                        min-height: 28px;
                        padding: 0 12px;
                        border-radius: 999px;
                        background: #f3f4f6;
                        color: #334155;
                        font-size: 12px;
                        font-weight: 600;
                        white-space: nowrap;
                    }
                    .cbt-tab-buttons {
                        display: flex;
                        gap: 10px;
                        margin: 14px 0;
                        flex-wrap: wrap;
                    }
                    .cbt-tab-buttons .button {
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        min-height: 42px;
                        padding: 0 16px;
                        border-radius: 12px;
                        border-color: #c9d5e6;
                        background: #fff;
                        color: #334155;
                        font-weight: 600;
                        box-shadow: none;
                        transition: all 0.16s ease;
                    }
                    .cbt-tab-buttons .button:hover,
                    .cbt-tab-buttons .button:focus {
                        border-color: #2271b1;
                        color: #0f4fa8;
