                <div class="cbt-results-table-shell">
            <table id="cbt-attempts-table" class="widefat striped<?php echo $show_exam_column ? '' : ' is-single-exam'; ?>">
                <thead>
                <tr>
                    <th>ID</th>
                    <th>Student</th>
                    <th><?php echo esc_html($show_exam_column ? 'Exam' : 'Status'); ?></th>
                    <th>Score</th>
