        $tables = self::cbt_data_tables($wpdb);
        $reset_user_ids = self::collect_cbt_user_ids_for_reset();
        $kelas_codes = self::build_test_data_seed_codes('KELAS_TEST_', (int) ($preset['classes'] ?? 0));
        $ruang_codes = self::build_test_data_seed_codes('RUANG_TEST_', (int) ($preset['rooms'] ?? 0));
        $seed_user_total = (int) ($preset['teachers'] ?? 0) + (int) ($preset['students'] ?? 0);
        $reset_user_total = count($reset_user_ids);
        $total_units = count($tables)
            + max(1, $reset_user_total)
            + (int) ($preset['subjects'] ?? 0)
            + $seed_user_total
            + (int) ($preset['exams'] ?? 0)
            + (int) ($preset['questions'] ?? 0)
            + 1;

        $token = strtolower((string) wp_generate_password(24, false, false));
        $state = [
            'user_id' => get_current_user_id(),
            'started_at' => time(),
            'phase' => 'reset_tables',
            'preset_key' => $preset_key,
            'preset' => $preset,
            'tables' => $tables,
            'table_index' => 0,
            'failed_tables' => [],
            'foreign_keys_disabled' => 0,
            'reset_user_total' => $reset_user_total,
            'reset_user_offset' => 0,
            'reset_users_placeholder_done' => 0,
            'deleted_user_count' => 0,
            'failed_user_delete_count' => 0,
            'kelas_codes' => $kelas_codes,
            'ruang_codes' => $ruang_codes,
            'seed_subject_offset' => 0,
            'seed_subject_created_count' => 0,
            'seed_subject_updated_count' => 0,
            'seed_subject_failed_count' => 0,
            'subjects' => [],
            'seed_user_offset' => 0,
            'seed_user_created_count' => 0,
            'seed_user_updated_count' => 0,
            'seed_user_failed_count' => 0,
            'seed_teacher_processed' => 0,
            'seed_student_processed' => 0,
            'seed_exam_offset' => 0,
            'seed_exam_created_count' => 0,
            'seed_exam_updated_count' => 0,
            'seed_exam_failed_count' => 0,
            'exams' => [],
            'seed_question_offset' => 0,
            'seed_question_created_count' => 0,
            'seed_question_failed_count' => 0,
            'question_type_counts' => [],
            'exam_question_counts' => [],
            'total_units' => max(1, $total_units),
            'processed_units' => 0,
        ];

        $state_saved = set_transient(self::get_seed_progress_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        $users_saved = set_transient(self::get_seed_progress_users_key($token), array_values($reset_user_ids), 12 * HOUR_IN_SECONDS);
        if (!$state_saved || !$users_saved) {
            self::clear_seed_progress_transients($token);
            self::redirect_maintenance_page(null, 'Gagal menyiapkan sesi generate data uji. Coba ulang lagi.', 'seed');
        }

        wp_safe_redirect(add_query_arg(
            [
                'page' => 'cbt-maintenance',
                'cbt_seed_progress_token' => $token,
            ],
            admin_url('admin.php')
        ));
        exit;
    }

    private static function continue_generate_test_dataset(string $token): void
    {
        $state = self::get_seed_progress_state_for_current_user($token);
        if (!is_array($state)) {
            self::clear_seed_progress_transients($token);
            self::redirect_maintenance_page(null, 'Sesi generate data uji berakhir. Silakan mulai ulang generator.', 'seed');
        }

        $preset = self::normalize_test_data_seed_preset((array) ($state['preset'] ?? []));
        $reset_users = get_transient(self::get_seed_progress_users_key($token));
        if (!is_array($reset_users)) {
            $reset_users = [];
        }
        $reset_users = array_values(array_map('intval', $reset_users));

        $phase = sanitize_key((string) ($state['phase'] ?? 'reset_tables'));
        $tables = isset($state['tables']) && is_array($state['tables']) ? array_values((array) $state['tables']) : [];
        $table_total = count($tables);
        $table_index = max(0, min($table_total, (int) ($state['table_index'] ?? 0)));
        $reset_user_total = max(0, isset($state['reset_user_total']) ? (int) $state['reset_user_total'] : count($reset_users));
        $reset_user_offset = max(0, min($reset_user_total, (int) ($state['reset_user_offset'] ?? 0)));
        $reset_users_placeholder_done = !empty($state['reset_users_placeholder_done']) ? 1 : 0;
        $deleted_user_count = max(0, (int) ($state['deleted_user_count'] ?? 0));
        $failed_user_delete_count = max(0, (int) ($state['failed_user_delete_count'] ?? 0));
        $seed_subject_offset = max(0, min((int) ($preset['subjects'] ?? 0), (int) ($state['seed_subject_offset'] ?? 0)));
        $seed_subject_created_count = max(0, (int) ($state['seed_subject_created_count'] ?? 0));
        $seed_subject_updated_count = max(0, (int) ($state['seed_subject_updated_count'] ?? 0));
        $seed_subject_failed_count = max(0, (int) ($state['seed_subject_failed_count'] ?? 0));
        $subjects = isset($state['subjects']) && is_array($state['subjects']) ? array_values((array) $state['subjects']) : [];
        $seed_user_total = (int) ($preset['teachers'] ?? 0) + (int) ($preset['students'] ?? 0);
        $seed_user_offset = max(0, min($seed_user_total, (int) ($state['seed_user_offset'] ?? 0)));
        $seed_user_created_count = max(0, (int) ($state['seed_user_created_count'] ?? 0));
        $seed_user_updated_count = max(0, (int) ($state['seed_user_updated_count'] ?? 0));
        $seed_user_failed_count = max(0, (int) ($state['seed_user_failed_count'] ?? 0));
        $seed_teacher_processed = max(0, (int) ($state['seed_teacher_processed'] ?? 0));
        $seed_student_processed = max(0, (int) ($state['seed_student_processed'] ?? 0));
        $seed_exam_offset = max(0, min((int) ($preset['exams'] ?? 0), (int) ($state['seed_exam_offset'] ?? 0)));
        $seed_exam_created_count = max(0, (int) ($state['seed_exam_created_count'] ?? 0));
        $seed_exam_updated_count = max(0, (int) ($state['seed_exam_updated_count'] ?? 0));
        $seed_exam_failed_count = max(0, (int) ($state['seed_exam_failed_count'] ?? 0));
        $exams = isset($state['exams']) && is_array($state['exams']) ? array_values((array) $state['exams']) : [];
        $seed_question_offset = max(0, min((int) ($preset['questions'] ?? 0), (int) ($state['seed_question_offset'] ?? 0)));
        $seed_question_created_count = max(0, (int) ($state['seed_question_created_count'] ?? 0));
        $seed_question_failed_count = max(0, (int) ($state['seed_question_failed_count'] ?? 0));
        $question_type_counts = isset($state['question_type_counts']) && is_array($state['question_type_counts'])
            ? (array) $state['question_type_counts']
            : [];
        $exam_question_counts = isset($state['exam_question_counts']) && is_array($state['exam_question_counts'])
            ? (array) $state['exam_question_counts']
            : [];
        $kelas_codes = isset($state['kelas_codes']) && is_array($state['kelas_codes'])
            ? array_values(array_filter(array_map('sanitize_text_field', (array) $state['kelas_codes'])))
            : [];
        $ruang_codes = isset($state['ruang_codes']) && is_array($state['ruang_codes'])
            ? array_values(array_filter(array_map('sanitize_text_field', (array) $state['ruang_codes'])))
            : [];
        $failed_tables = [];
        if (isset($state['failed_tables']) && is_array($state['failed_tables'])) {
            foreach ($state['failed_tables'] as $failed_table) {
                $failed_table = str_replace('`', '', (string) $failed_table);
                if ($failed_table !== '') {
                    $failed_tables[$failed_table] = $failed_table;
                }
            }
        }

        $total_units = max(1, (int) ($state['total_units'] ?? 1));
        $max_batch_seconds = self::get_test_data_seed_max_batch_seconds();
        $batch_started_at = microtime(true);

        global $wpdb;

        if ($phase === 'reset_tables') {
            if (empty($state['foreign_keys_disabled'])) {
                $wpdb->query('SET FOREIGN_KEY_CHECKS = 0');
                $state['foreign_keys_disabled'] = 1;
            }

            $processed_tables_this_round = 0;
            $table_batch_size = self::get_reset_progress_table_batch_size();
            while ($table_index < $table_total && $processed_tables_this_round < $table_batch_size) {
                $safe_table = str_replace('`', '', (string) $tables[$table_index]);
                if ($safe_table !== '') {
                    $truncated = $wpdb->query("TRUNCATE TABLE `{$safe_table}`");
                    if ($truncated === false) {
                        $deleted = $wpdb->query("DELETE FROM `{$safe_table}`");
                        if ($deleted === false) {
                            $failed_tables[$safe_table] = $safe_table;
                        } else {
                            $wpdb->query("ALTER TABLE `{$safe_table}` AUTO_INCREMENT = 1");
                        }
                    }
                }

                $table_index++;
                $processed_tables_this_round++;

                if ((microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                    break;
                }
            }

            if ($table_index >= $table_total) {
                if (!empty($state['foreign_keys_disabled'])) {
                    $wpdb->query('SET FOREIGN_KEY_CHECKS = 1');
                }
                $state['foreign_keys_disabled'] = 0;

                if (!empty($failed_tables)) {
                    self::clear_seed_progress_transients($token);
                    self::redirect_maintenance_page(
                        null,
                        'Generator data uji dibatalkan karena sebagian tabel gagal direset: ' . implode(', ', array_values($failed_tables)),
                        'seed'
                    );
                }

                $phase = 'reset_users';
            }
        }

        if ($phase === 'reset_users' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            if ($reset_user_total <= 0) {
                $reset_users_placeholder_done = 1;
                $phase = 'seed_subjects';
            } else {
                require_once ABSPATH . 'wp-admin/includes/user.php';
                $target_offset = min($reset_user_offset + self::get_reset_progress_user_batch_size(), $reset_user_total);
                for ($index = $reset_user_offset; $index < $target_offset; $index++) {
                    $user_id = isset($reset_users[$index]) ? (int) $reset_users[$index] : 0;
                    if ($user_id <= 0) {
                        continue;
                    }

                    $deleted = wp_delete_user($user_id);
                    if ($deleted) {
                        $deleted_user_count++;
                    } else {
                        $failed_user_delete_count++;
                    }

                    if (($index - $reset_user_offset) >= 1 && (microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                        $target_offset = $index + 1;
                        break;
                    }
                }
                $reset_user_offset = $target_offset;
                if ($reset_user_offset >= $reset_user_total) {
                    $phase = 'seed_subjects';
                }
            }
        }

        if ($phase === 'seed_subjects' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            $subject_total = (int) ($preset['subjects'] ?? 0);
            $subject_batch_size = self::get_test_data_seed_batch_size('subjects');
            $processed_subjects_this_round = 0;

            while ($seed_subject_offset < $subject_total && $processed_subjects_this_round < $subject_batch_size) {
                $subject_entry = self::build_test_data_seed_subject_entry($seed_subject_offset);
                $upserted_subject = self::upsert_test_data_seed_subject($subject_entry);
                $subject_id = (int) ($upserted_subject['id'] ?? 0);
                $subject_status = (string) ($upserted_subject['status'] ?? 'failed');

                if ($subject_id > 0) {
                    $subjects[$seed_subject_offset] = [
                        'id' => $subject_id,
                        'name' => (string) ($upserted_subject['name'] ?? $subject_entry['name']),
                        'code' => (string) ($upserted_subject['code'] ?? $subject_entry['code']),
                    ];
                    if ($subject_status === 'updated') {
                        $seed_subject_updated_count++;
                    } else {
                        $seed_subject_created_count++;
                    }
                } else {
                    $seed_subject_failed_count++;
                }

                $seed_subject_offset++;
                $processed_subjects_this_round++;

                if ((microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                    break;
                }
            }

            if ($seed_subject_offset >= $subject_total) {
                ksort($subjects);
                $subjects = array_values($subjects);
                if ($seed_subject_failed_count > 0 || count($subjects) < $subject_total) {
                    self::clear_seed_progress_transients($token);
                    self::redirect_maintenance_page(
                        null,
                        'Generator data uji berhenti karena ada subject yang gagal dibuat atau disinkronkan.',
                        'seed'
                    );
                }
                $phase = 'seed_users';
            }
        }

        if ($phase === 'seed_users' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            $user_batch_size = self::get_test_data_seed_batch_size('users');
            $seed_rows = self::build_test_data_seed_user_rows($preset, $seed_user_offset, $user_batch_size, $kelas_codes, $ruang_codes);
            $lookup = self::build_user_import_lookup($seed_rows, 0, count($seed_rows));
            $cache_invalidation_prev = null;
            if (function_exists('wp_suspend_cache_invalidation')) {
                $cache_invalidation_prev = wp_suspend_cache_invalidation(true);
            }

            foreach ($seed_rows as $row) {
                $seed_kind = sanitize_key((string) ($row['__seed_kind'] ?? 'student'));
                unset($row['__seed_kind']);

                try {
                    $result = self::upsert_user_from_row($row, $lookup);
                } catch (Throwable $exception) {
                    $result = 'failed';
                }

                if ($result === 'created') {
                    $seed_user_created_count++;
                } elseif ($result === 'updated') {
                    $seed_user_updated_count++;
                } else {
                    $seed_user_failed_count++;
                }

                if ($seed_kind === 'teacher') {
                    $seed_teacher_processed++;
                } else {
                    $seed_student_processed++;
                }

                $seed_user_offset++;

                if (($seed_user_offset % 2) === 0 && (microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                    break;
                }
            }

            if ($cache_invalidation_prev !== null && function_exists('wp_suspend_cache_invalidation')) {
                wp_suspend_cache_invalidation((bool) $cache_invalidation_prev);
            }

            if ($seed_user_offset >= $seed_user_total) {
                if (
                    $seed_user_failed_count > 0
                    || $seed_teacher_processed < (int) ($preset['teachers'] ?? 0)
                    || $seed_student_processed < (int) ($preset['students'] ?? 0)
                ) {
                    self::clear_seed_progress_transients($token);
                    self::redirect_maintenance_page(
                        null,
                        'Generator data uji berhenti karena ada user guru/siswa yang gagal dibuat atau disinkronkan.',
                        'seed'
                    );
                }
                $phase = 'seed_exams';
            }
        }

        if ($phase === 'seed_exams' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            $exam_total = (int) ($preset['exams'] ?? 0);
            $exam_batch_size = self::get_test_data_seed_batch_size('exams');
            $processed_exams_this_round = 0;
            $creator_id = isset($state['user_id']) ? (int) $state['user_id'] : get_current_user_id();

            while ($seed_exam_offset < $exam_total && $processed_exams_this_round < $exam_batch_size) {
                $exam_entry = self::build_test_data_seed_exam_entry(
                    $seed_exam_offset,
                    $subjects,
                    $kelas_codes,
                    (string) ($state['preset_key'] ?? 'small'),
                    $creator_id
                );
                $upserted_exam = self::upsert_test_data_seed_exam($exam_entry);
                $exam_id = (int) ($upserted_exam['id'] ?? 0);
                $exam_status = (string) ($upserted_exam['status'] ?? 'failed');

                if ($exam_id > 0) {
                    $exams[$seed_exam_offset] = [
                        'id' => $exam_id,
                        'subject_id' => (int) ($upserted_exam['subject_id'] ?? ($exam_entry['subject_id'] ?? 0)),
                        'subject_name' => (string) ($upserted_exam['subject_name'] ?? ($exam_entry['subject_name'] ?? '')),
                        'title' => (string) ($upserted_exam['title'] ?? ($exam_entry['title'] ?? '')),
                        'target_kelas' => (string) ($upserted_exam['target_kelas'] ?? ($exam_entry['target_kelas'] ?? '')),
                    ];
                    if ($exam_status === 'updated') {
                        $seed_exam_updated_count++;
                    } else {
                        $seed_exam_created_count++;
                    }
                } else {
                    $seed_exam_failed_count++;
                }

                $seed_exam_offset++;
                $processed_exams_this_round++;

                if ((microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                    break;
                }
            }

            if ($seed_exam_offset >= $exam_total) {
                ksort($exams);
                $exams = array_values($exams);
                if ($seed_exam_failed_count > 0 || count($exams) < $exam_total) {
                    self::clear_seed_progress_transients($token);
                    self::redirect_maintenance_page(
                        null,
                        'Generator data uji berhenti karena ada exam yang gagal dibuat atau disinkronkan.',
                        'seed'
                    );
                }
                $phase = 'seed_questions';
            }
        }

        if ($phase === 'seed_questions' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            $question_total = (int) ($preset['questions'] ?? 0);
            $question_batch_size = self::get_test_data_seed_batch_size('questions');
            $processed_questions_this_round = 0;

            while ($seed_question_offset < $question_total && $processed_questions_this_round < $question_batch_size) {
                $question_row = self::build_test_data_seed_question_row(
                    $seed_question_offset,
                    $exams,
                    (string) ($state['preset_key'] ?? 'small')
                );

                try {
                    $result = self::insert_test_data_seed_question($question_row);
                } catch (Throwable $exception) {
                    $result = 'failed';
                }

                if ($result === 'created') {
                    $seed_question_created_count++;
                    $question_type = sanitize_key((string) ($question_row['question_type'] ?? ''));
                    $exam_id = absint($question_row['exam_id'] ?? 0);
                    if ($question_type !== '') {
                        $question_type_counts[$question_type] = isset($question_type_counts[$question_type])
                            ? ((int) $question_type_counts[$question_type] + 1)
                            : 1;
                    }
                    if ($exam_id > 0) {
                        $exam_question_counts[$exam_id] = isset($exam_question_counts[$exam_id])
                            ? ((int) $exam_question_counts[$exam_id] + 1)
                            : 1;
                    }
                } else {
                    $seed_question_failed_count++;
                }

                $seed_question_offset++;
                $processed_questions_this_round++;

                if ((microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                    break;
                }
            }

            if ($seed_question_offset >= $question_total) {
                if ($seed_question_failed_count > 0 || $seed_question_created_count < $question_total) {
                    self::clear_seed_progress_transients($token);
                    self::redirect_maintenance_page(
                        null,
                        'Generator data uji berhenti karena ada soal yang gagal dibuat.',
                        'seed'
                    );
                }
                $phase = 'finalize';
            }
        }

        $state['phase'] = $phase;
        $state['table_index'] = $table_index;
        $state['reset_user_total'] = $reset_user_total;
        $state['reset_user_offset'] = $reset_user_offset;
        $state['reset_users_placeholder_done'] = $reset_users_placeholder_done;
        $state['deleted_user_count'] = $deleted_user_count;
        $state['failed_user_delete_count'] = $failed_user_delete_count;
        $state['failed_tables'] = array_values($failed_tables);
        $state['seed_subject_offset'] = $seed_subject_offset;
        $state['seed_subject_created_count'] = $seed_subject_created_count;
        $state['seed_subject_updated_count'] = $seed_subject_updated_count;
        $state['seed_subject_failed_count'] = $seed_subject_failed_count;
        $state['subjects'] = array_values($subjects);
        $state['seed_user_offset'] = $seed_user_offset;
        $state['seed_user_created_count'] = $seed_user_created_count;
        $state['seed_user_updated_count'] = $seed_user_updated_count;
        $state['seed_user_failed_count'] = $seed_user_failed_count;
        $state['seed_teacher_processed'] = $seed_teacher_processed;
        $state['seed_student_processed'] = $seed_student_processed;
        $state['seed_exam_offset'] = $seed_exam_offset;
        $state['seed_exam_created_count'] = $seed_exam_created_count;
        $state['seed_exam_updated_count'] = $seed_exam_updated_count;
        $state['seed_exam_failed_count'] = $seed_exam_failed_count;
        $state['exams'] = array_values($exams);
        $state['seed_question_offset'] = $seed_question_offset;
        $state['seed_question_created_count'] = $seed_question_created_count;
        $state['seed_question_failed_count'] = $seed_question_failed_count;
        $state['question_type_counts'] = $question_type_counts;
        $state['exam_question_counts'] = $exam_question_counts;
        $state['total_units'] = $total_units;
        $state['processed_units'] = self::calculate_test_data_seed_processed_units($state);

        if ($phase === 'finalize' && (microtime(true) - $batch_started_at) < $max_batch_seconds) {
            $exam_table = $wpdb->prefix . 'cbt_exams';
            foreach ($exam_question_counts as $exam_id => $count) {
                $exam_id = (int) $exam_id;
                if ($exam_id <= 0) {
                    continue;
                }

                $wpdb->update(
                    $exam_table,
                    [
                        'total_questions' => max(0, (int) $count),
                        'updated_at' => current_time('mysql'),
                    ],
                    ['id' => $exam_id],
                    ['%d', '%s'],
                    ['%d']
                );
            }

            self::reset_cbt_global_token_options();
            CBT_UI_State::clear_all();
            CBT_Cache::reset_plugin_cache_state();
            self::clear_seed_progress_transients($token);

            $message = sprintf(
                'Dataset uji preset %s selesai. Subject: %d, Exam: %d, Question: %d, Guru: %d, Siswa: %d. Password default: %s. Akun test khusus: %s / %s.',
                (string) ($preset['label'] ?? ucfirst((string) ($state['preset_key'] ?? 'small'))),
                (int) ($preset['subjects'] ?? 0),
                (int) ($preset['exams'] ?? 0),
                (int) ($preset['questions'] ?? 0),
                (int) ($preset['teachers'] ?? 0),
                (int) ($preset['students'] ?? 0),
                self::TEST_DATA_SEED_DEFAULT_PASSWORD,
                self::TEST_DATA_SEED_SPECIAL_USERNAME,
                self::TEST_DATA_SEED_SPECIAL_PASSWORD
            );
            if ($failed_user_delete_count > 0) {
                $message .= ' User lama yang gagal dihapus: ' . $failed_user_delete_count . '.';
            }

            self::redirect_maintenance_page($message, null, 'seed');
        }

        $state_saved = set_transient(self::get_seed_progress_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        if (!$state_saved) {
            if (!empty($state['foreign_keys_disabled'])) {
                $wpdb->query('SET FOREIGN_KEY_CHECKS = 1');
            }
            self::clear_seed_progress_transients($token);
            self::redirect_maintenance_page(null, 'Gagal menyimpan progres generator data uji. Silakan mulai ulang.', 'seed');
        }

        wp_safe_redirect(add_query_arg(
            [
                'page' => 'cbt-maintenance',
                'cbt_seed_progress_token' => $token,
            ],
            admin_url('admin.php')
        ));
        exit;
    }

    /**
     * @return array<string,mixed>|WP_Error
     */
    private static function normalize_exam_save_payload(array $request)
    {
        $id = isset($request['id']) ? absint(wp_unslash($request['id'])) : 0;
        $subject_id = isset($request['subject_id']) ? absint(wp_unslash($request['subject_id'])) : 0;
        $title = isset($request['title']) ? sanitize_text_field(wp_unslash($request['title'])) : '';
        $description = isset($request['description']) ? wp_kses_post(wp_unslash($request['description'])) : '';
        $duration = max(1, isset($request['duration_minutes']) ? absint(wp_unslash($request['duration_minutes'])) : 60);
        $randomize = isset($request['randomize_questions']) ? 1 : 0;
        $randomize_options = isset($request['randomize_options']) ? 1 : 0;
        $status = isset($request['status']) ? sanitize_text_field(wp_unslash($request['status'])) : 'draft';
        $allowed_statuses = ['draft', 'published', 'closed'];
        if (!in_array($status, $allowed_statuses, true)) {
            $status = 'draft';
        }
        $starts_at = isset($request['starts_at']) ? self::from_datetime_local((string) wp_unslash($request['starts_at'])) : null;
        $ends_at = isset($request['ends_at']) ? self::from_datetime_local((string) wp_unslash($request['ends_at'])) : null;
        $target_kelas_raw = isset($request['target_kelas']) ? wp_unslash($request['target_kelas']) : '';
        $target_kelas = self::normalize_target_kelas_csv($target_kelas_raw);
        $raw_source_question_ids = isset($request['source_question_ids']) && is_array($request['source_question_ids'])
            ? wp_unslash($request['source_question_ids'])
            : [];
        $source_question_ids = array_values(array_unique(array_filter(array_map('absint', $raw_source_question_ids))));

        if ($subject_id <= 0) {
            return new WP_Error('invalid_subject', 'Mapel wajib dipilih.');
        }
        if ($title === '') {
            return new WP_Error('invalid_title', 'Judul exam wajib diisi.');
        }
        if ($starts_at !== null && $ends_at !== null && strtotime($ends_at) < strtotime($starts_at)) {
            return new WP_Error('invalid_schedule', 'Waktu selesai tidak boleh lebih awal dari waktu mulai.');
        }
        if ($id <= 0 && empty($source_question_ids)) {
            return new WP_Error('invalid_questions', 'Pilih minimal 1 soal untuk exam baru.');
        }

        return [
            'id' => $id,
            'subject_id' => $subject_id,
            'title' => $title,
            'description' => $description,
            'duration' => $duration,
            'randomize' => $randomize,
            'randomize_options' => $randomize_options,
            'status' => $status,
            'starts_at' => $starts_at,
            'ends_at' => $ends_at,
            'target_kelas' => $target_kelas,
            'source_question_ids' => $source_question_ids,
        ];
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>|WP_Error
     */
    private static function upsert_exam_record_from_payload(array $payload, bool $is_admin_scope, int $current_user_id)
    {
        global $wpdb;

        $table = $wpdb->prefix . 'cbt_exams';
        $id = (int) ($payload['id'] ?? 0);
        $source_question_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($payload['source_question_ids'] ?? [])))));
        $existing_question_count = 0;
        if ($id > 0 && empty($source_question_ids)) {
            $existing_question_count = (int) $wpdb->get_var(
                $wpdb->prepare(
                    "SELECT COUNT(*) FROM {$wpdb->prefix}cbt_questions WHERE exam_id = %d AND COALESCE(is_active, 1) = 1",
                    $id
                )
            );
        }

        $data = [
            'subject_id' => (int) ($payload['subject_id'] ?? 0),
            'title' => (string) ($payload['title'] ?? ''),
            'description' => (string) ($payload['description'] ?? ''),
            'duration_minutes' => (int) ($payload['duration'] ?? 60),
            'total_questions' => $existing_question_count,
            'randomize_questions' => (int) ($payload['randomize'] ?? 0),
            'randomize_options' => (int) ($payload['randomize_options'] ?? 0),
            'status' => (string) ($payload['status'] ?? 'draft'),
            'starts_at' => $payload['starts_at'] ?? null,
            'ends_at' => $payload['ends_at'] ?? null,
            'target_kelas' => (string) ($payload['target_kelas'] ?? ''),
            'updated_at' => current_time('mysql'),
        ];

        $saved_exam_id = $id;
        if ($id > 0) {
            if (!$is_admin_scope) {
                $owned_exam = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM {$table} WHERE id = %d AND created_by = %d",
                    $id,
                    $current_user_id
                ));
                if ($owned_exam === 0) {
                    return new WP_Error('unauthorized_exam', 'Unauthorized exam update.');
                }
            }

            $updated = $wpdb->update(
                $table,
                $data,
                ['id' => $id],
                ['%d', '%s', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s'],
                ['%d']
            );
            if ($updated === false) {
                return new WP_Error('update_failed', 'Gagal mengupdate exam.');
            }
        } else {
            $data['created_by'] = $current_user_id;
            $data['created_at'] = current_time('mysql');

            $inserted = $wpdb->insert(
                $table,
                $data,
                ['%d', '%s', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s']
            );
            if (!$inserted) {
                return new WP_Error('insert_failed', 'Gagal membuat exam.');
            }

            $saved_exam_id = (int) $wpdb->insert_id;
        }

        return [
            'exam_id' => $saved_exam_id,
            'existing_question_count' => $existing_question_count,
            'is_update' => $id > 0,
        ];
    }

    /**
     * @return array<string,string>
     */
    private static function finalize_exam_save_operation(int $saved_exam_id, int $original_exam_id, ?int $synced_questions, int $current_user_id): array
    {
        global $wpdb;

        $table = $wpdb->prefix . 'cbt_exams';
        if ($saved_exam_id > 0 && $synced_questions !== null) {
            $wpdb->update(
                $table,
                [
                    'total_questions' => $synced_questions,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $saved_exam_id],
                ['%d', '%s'],
                ['%d']
            );
            self::clear_exam_attempt_states($saved_exam_id);
        }

        $message = ($original_exam_id > 0) ? 'Exam updated' : 'Exam created';
        if ($synced_questions !== null) {
            $message .= ' - ' . $synced_questions . ' soal tersinkron.';
        }
        $exam_list_state = self::get_exam_list_state_from_request($_POST);

        CBT_Cache::invalidate_catalog();
        CBT_Cache::invalidate_exam($saved_exam_id);
        self::clear_exam_builder_selection_state('cbt_exam_builder_new', $current_user_id);
        self::clear_exam_builder_selection_state('cbt_exam_builder_edit_' . $saved_exam_id, $current_user_id);

        return [
            'message' => $message,
            'redirect_url' => add_query_arg(
                self::add_exam_list_state_args(
                    [
                        'page' => 'cbt-exams',
                        'cbt_exam_panel' => 'list',
                        'cbt_msg' => $message,
                        'cbt_saved_exam_id' => (int) $saved_exam_id,
                    ],
                    $exam_list_state
                ),
                admin_url('admin.php')
            ),
        ];
    }

    public static function handle_start_exam_save_progress(): void
    {
        if (!self::can_manage_exams()) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        check_admin_referer('cbt_save_exam');
        check_ajax_referer('cbt_exam_builder_state', 'nonce');

        $is_admin_scope = self::is_admin_scope();
        $current_user_id = get_current_user_id();
        $payload = self::normalize_exam_save_payload($_POST);
        if (is_wp_error($payload)) {
            wp_send_json_error(['message' => $payload->get_error_message()], 400);
        }

        $save_result = self::upsert_exam_record_from_payload($payload, $is_admin_scope, $current_user_id);
        if (is_wp_error($save_result)) {
            wp_send_json_error(['message' => $save_result->get_error_message()], 400);
        }

        global $wpdb;
        $question_table = $wpdb->prefix . 'cbt_questions';
        $saved_exam_id = (int) ($save_result['exam_id'] ?? 0);
        $token = strtolower((string) wp_generate_password(24, false, false));
        $selected_source_question_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($payload['source_question_ids'] ?? [])))));
        $existing_exam_question_ids = array_values(array_unique(array_filter(array_map(
            'absint',
            (array) $wpdb->get_col(
                $wpdb->prepare(
                    "SELECT id FROM {$question_table} WHERE exam_id = %d ORDER BY id ASC",
                    $saved_exam_id
                )
            )
        ))));

        $state = [
            'user_id' => $current_user_id,
            'exam_id' => $saved_exam_id,
            'original_exam_id' => (int) ($payload['id'] ?? 0),
            'selected_source_question_ids' => $selected_source_question_ids,
            'total_sources' => count($selected_source_question_ids),
            'processed_sources' => 0,
            'updated_existing_count' => 0,
            'created_new_count' => 0,
            'removed_question_count' => 0,
            'matched_existing_question_ids' => [],
            'existing_exam_question_ids' => $existing_exam_question_ids,
            'is_admin_scope' => $is_admin_scope ? 1 : 0,
            'current_user_id' => $current_user_id,
            'phase' => !empty($selected_source_question_ids) ? 'sync' : 'finalize',
            'message' => !empty($selected_source_question_ids)
                ? 'Menyiapkan sinkronisasi soal exam.'
                : 'Merapikan data exam.',
            'started_at' => time(),
        ];

        $state = self::continue_exam_save_progress_state($state);
        if (is_wp_error($state)) {
            wp_send_json_error(['message' => $state->get_error_message()], 500);
        }

        $response = self::build_exam_save_progress_payload($state);
        $response['token'] = $token;
        if (!empty($response['complete'])) {
            wp_send_json_success($response);
        }

        $saved = set_transient(self::get_exam_save_progress_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        if (!$saved) {
            wp_send_json_error(['message' => 'Gagal menyimpan state progress update exam.'], 500);
        }

        wp_send_json_success($response);
    }

    public static function handle_continue_exam_save_progress(): void
    {
        if (!self::can_manage_exams()) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        check_ajax_referer('cbt_exam_builder_state', 'nonce');

        $token = isset($_POST['token']) ? sanitize_key((string) wp_unslash($_POST['token'])) : '';
        $state = self::get_exam_save_progress_state_for_current_user($token);
        if (!is_array($state)) {
            wp_send_json_error(['message' => 'Sesi progress update exam tidak ditemukan atau sudah berakhir.'], 404);
        }

        $state = self::continue_exam_save_progress_state($state);
        if (is_wp_error($state)) {
            self::clear_exam_save_progress_state($token);
            wp_send_json_error(['message' => $state->get_error_message()], 500);
        }

        $response = self::build_exam_save_progress_payload($state);
        $response['token'] = $token;

        if (!empty($response['complete'])) {
            self::clear_exam_save_progress_state($token);
            wp_send_json_success($response);
        }

        $saved = set_transient(self::get_exam_save_progress_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        if (!$saved) {
            self::clear_exam_save_progress_state($token);
            wp_send_json_error(['message' => 'Gagal menyimpan lanjutan progress update exam.'], 500);
        }

        wp_send_json_success($response);
    }

    /**
     * @param array<string,mixed> $state
     * @return array<string,mixed>|WP_Error
     */
    private static function continue_exam_save_progress_state(array $state)
    {
        $phase = sanitize_key((string) ($state['phase'] ?? 'sync'));
        if ($phase === 'sync') {
            return self::run_exam_save_sync_batch($state);
        }

        if ($phase === 'cleanup') {
            $exam_id = (int) ($state['exam_id'] ?? 0);
            $existing_exam_question_ids = array_values(array_unique(array_filter(array_map(
                'absint',
                (array) ($state['existing_exam_question_ids'] ?? [])
            ))));
            $matched_existing_question_ids = array_values(array_unique(array_filter(array_map(
                'absint',
                (array) ($state['matched_existing_question_ids'] ?? [])
            ))));
            $stale_question_ids = array_values(array_diff($existing_exam_question_ids, $matched_existing_question_ids));
            if (!empty($stale_question_ids)) {
                $cleanup_result = self::archive_or_delete_exam_questions($exam_id, $stale_question_ids);
                if (is_wp_error($cleanup_result)) {
                    return $cleanup_result;
                }
                $state['removed_question_count'] = count($stale_question_ids);
            }

            $state['phase'] = 'finalize';
            $state['message'] = 'Merapikan cache exam, attempt, dan data builder.';
            return $state;
        }

        if ($phase === 'finalize') {
            $saved_exam_id = (int) ($state['exam_id'] ?? 0);
            $original_exam_id = (int) ($state['original_exam_id'] ?? 0);
            $current_user_id = (int) ($state['current_user_id'] ?? 0);
            $total_sources = max(0, (int) ($state['total_sources'] ?? 0));
            $synced_questions = $total_sources > 0 ? max(0, (int) ($state['processed_sources'] ?? 0)) : null;
            $finalize_result = self::finalize_exam_save_operation(
                $saved_exam_id,
                $original_exam_id,
                $synced_questions,
                $current_user_id
            );

            $state['phase'] = 'complete';
            $state['message'] = (string) ($finalize_result['message'] ?? 'Exam berhasil disimpan.');
            $state['redirect_url'] = (string) ($finalize_result['redirect_url'] ?? '');

            return $state;
        }

        return $state;
    }

    /**
     * @param array<string,mixed> $state
     * @return array<string,mixed>|WP_Error
     */
    private static function run_exam_save_sync_batch(array $state)
    {
        global $wpdb;

        $exam_id = (int) ($state['exam_id'] ?? 0);
        $current_user_id = (int) ($state['current_user_id'] ?? 0);
        $is_admin_scope = !empty($state['is_admin_scope']);
        $source_question_ids = array_values(array_unique(array_filter(array_map(
            'absint',
            (array) ($state['selected_source_question_ids'] ?? [])
        ))));
        $total_sources = count($source_question_ids);
        $processed_sources = max(0, min($total_sources, (int) ($state['processed_sources'] ?? 0)));

        if ($exam_id <= 0) {
            return new WP_Error('invalid_exam', 'Exam tidak valid untuk diproses.');
        }
        if ($total_sources <= 0 || $processed_sources >= $total_sources) {
            $state['phase'] = 'cleanup';
            $state['message'] = 'Meninjau soal lama yang tidak lagi dipakai.';
            return $state;
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $option_table = $wpdb->prefix . 'cbt_options';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $batch_size = self::get_exam_save_progress_chunk_size();
        $max_batch_seconds = self::get_exam_save_progress_max_batch_seconds();
        $preserve_attempt_history = self::exam_has_attempt_records($exam_id);
        $batch_source_ids = array_slice($source_question_ids, $processed_sources, $batch_size);
        if (empty($batch_source_ids)) {
            $state['phase'] = 'cleanup';
            $state['message'] = 'Meninjau soal lama yang tidak lagi dipakai.';
            return $state;
        }

        $source_placeholders = implode(',', array_fill(0, count($batch_source_ids), '%d'));
        $source_query_params = $batch_source_ids;
        $source_sql = "SELECT q.*
                       FROM {$question_table} q
                       INNER JOIN {$exam_table} e ON e.id = q.exam_id
                       WHERE q.id IN ({$source_placeholders})";
        if (!$is_admin_scope) {
            $source_sql .= ' AND e.created_by = %d';
            $source_query_params[] = $current_user_id;
        }
        $source_rows = $wpdb->get_results($wpdb->prepare($source_sql, ...$source_query_params), ARRAY_A);
        $source_by_id = [];
        foreach ((array) $source_rows as $source_row) {
            $source_by_id[(int) ($source_row['id'] ?? 0)] = $source_row;
        }

        $ordered_sources = [];
        foreach ($batch_source_ids as $source_question_id) {
            if (isset($source_by_id[$source_question_id])) {
                $ordered_sources[] = $source_by_id[$source_question_id];
            }
        }
        if (empty($ordered_sources) || count($ordered_sources) !== count($batch_source_ids)) {
            return new WP_Error('invalid_questions', 'Soal sumber tidak ditemukan saat proses update exam.');
        }

        $ordered_source_ids = array_map(static function ($row): int {
            return (int) ($row['id'] ?? 0);
        }, $ordered_sources);
        $option_placeholders = implode(',', array_fill(0, count($ordered_source_ids), '%d'));
        $option_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT * FROM {$option_table} WHERE question_id IN ({$option_placeholders}) ORDER BY id ASC",
                ...$ordered_source_ids
            ),
            ARRAY_A
        );
        $options_by_question = [];
        foreach ((array) $option_rows as $option_row) {
            $question_id = (int) ($option_row['question_id'] ?? 0);
            if ($question_id <= 0) {
                continue;
            }
            if (!isset($options_by_question[$question_id])) {
                $options_by_question[$question_id] = [];
            }
            $options_by_question[$question_id][] = $option_row;
        }

        $detail_by_question = [];
        foreach ($ordered_sources as $source_row) {
            $source_question_id = (int) ($source_row['id'] ?? 0);
            $source_question_type = (string) ($source_row['question_type'] ?? '');
            $detail_by_question[$source_question_id] = self::get_question_type_detail($source_question_id, $source_question_type);
        }

        $existing_exam_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, source_question_id, COALESCE(is_active, 1) AS is_active
                 FROM {$question_table}
                 WHERE exam_id = %d
                 ORDER BY COALESCE(is_active, 1) DESC, id ASC",
                $exam_id
            ),
            ARRAY_A
        );
        $matched_existing_lookup = array_fill_keys(
            array_values(array_unique(array_filter(array_map('absint', (array) ($state['matched_existing_question_ids'] ?? []))))),
            true
        );
        $existing_by_source = [];
        $candidate_question_ids = [];
        foreach ((array) $existing_exam_rows as $existing_exam_row) {
            $existing_question_id = (int) ($existing_exam_row['id'] ?? 0);
            if ($existing_question_id <= 0 || isset($matched_existing_lookup[$existing_question_id])) {
                continue;
            }

            $is_active_existing = (int) ($existing_exam_row['is_active'] ?? 1) === 1;
            if ($preserve_attempt_history && !$is_active_existing) {
                continue;
            }

            $existing_source_question_id = (int) ($existing_exam_row['source_question_id'] ?? 0);
            if ($existing_source_question_id > 0) {
                if (!isset($existing_by_source[$existing_source_question_id])) {
                    $existing_by_source[$existing_source_question_id] = [];
                }
                $existing_by_source[$existing_source_question_id][] = $existing_question_id;
            }

            $candidate_question_ids[] = $existing_question_id;
        }

        $existing_snapshots = [];
        $processed_this_batch = 0;
        $batch_started_at = microtime(true);
        $now = current_time('mysql');
        foreach ($ordered_sources as $source_row) {
            $source_question_id = (int) ($source_row['id'] ?? 0);
            $source_snapshot = self::build_exam_sync_source_snapshot(
                $source_row,
                $options_by_question[$source_question_id] ?? [],
                $detail_by_question[$source_question_id] ?? []
            );

            $matched_question_id = 0;
            if (isset($existing_by_source[$source_question_id])) {
                while (!empty($existing_by_source[$source_question_id])) {
                    $candidate_question_id = (int) array_shift($existing_by_source[$source_question_id]);
                    if ($candidate_question_id > 0 && !isset($matched_existing_lookup[$candidate_question_id])) {
                        $matched_question_id = $candidate_question_id;
                        break;
                    }
                }
            }

            if ($matched_question_id <= 0) {
                foreach ($candidate_question_ids as $candidate_question_id) {
                    $candidate_question_id = (int) $candidate_question_id;
                    if ($candidate_question_id <= 0 || isset($matched_existing_lookup[$candidate_question_id])) {
                        continue;
                    }
                    if (!isset($existing_snapshots[$candidate_question_id])) {
                        $existing_snapshots[$candidate_question_id] = self::get_question_sync_snapshot($candidate_question_id);
                    }
                    $candidate_snapshot = (array) ($existing_snapshots[$candidate_question_id] ?? []);
                    if (empty($candidate_snapshot)) {
                        continue;
                    }

                    if (self::question_snapshots_are_legacy_descendant_match($candidate_snapshot, $source_snapshot)) {
                        $matched_question_id = $candidate_question_id;
                        break;
                    }
                }
            }

            if ($matched_question_id > 0) {
                $target_snapshot = (array) ($existing_snapshots[$matched_question_id] ?? []);
                $updated_exam_id = $preserve_attempt_history
                    ? self::link_existing_exam_question_to_source(
                        $matched_question_id,
                        $source_question_id,
                        $target_snapshot
                    )
                    : self::apply_source_snapshot_to_question(
                        $matched_question_id,
                        $source_question_id,
                        $source_snapshot,
                        $target_snapshot
                    );
                if ($updated_exam_id <= 0) {
                    return new WP_Error('update_failed', 'Gagal menyinkronkan salah satu soal exam yang sudah ada.');
                }

                $matched_existing_lookup[$matched_question_id] = true;
                $state['matched_existing_question_ids'][$matched_question_id] = $matched_question_id;
                $state['updated_existing_count'] = ((int) ($state['updated_existing_count'] ?? 0)) + 1;
            } else {
                $question_type = (string) ($source_snapshot['question_type'] ?? 'multiple_choice');
                $inserted_question = $wpdb->insert(
                    $question_table,
                    [
                        'exam_id' => $exam_id,
                        'source_question_id' => $source_question_id,
                        'is_active' => 1,
                        'question_text' => (string) ($source_snapshot['question_text'] ?? ''),
                        'question_type' => $question_type,
                        'points' => (float) ($source_snapshot['points'] ?? 1),
                        'correct_text' => (string) ($source_snapshot['correct_text'] ?? ''),
                        'explanation' => (string) ($source_snapshot['explanation'] ?? ''),
                        'created_at' => $now,
                        'updated_at' => $now,
                    ],
                    ['%d', '%d', '%d', '%s', '%s', '%f', '%s', '%s', '%s', '%s']
                );
                if (!$inserted_question) {
                    return new WP_Error('insert_failed', 'Gagal menyalin salah satu soal ke exam.');
                }

                $new_question_id = (int) $wpdb->insert_id;
                foreach ((array) ($source_snapshot['options'] ?? []) as $source_option) {
                    $wpdb->insert(
                        $option_table,
                        [
                            'question_id' => $new_question_id,
                            'option_key' => (string) ($source_option['option_key'] ?? ''),
                            'option_text' => (string) ($source_option['option_text'] ?? ''),
                            'is_correct' => (int) ($source_option['is_correct'] ?? 0),
                            'created_at' => $now,
                        ],
                        ['%d', '%s', '%s', '%d', '%s']
                    );
                }

                self::save_question_type_detail(
                    $new_question_id,
                    $question_type,
                    (string) ($source_snapshot['normalized_detail_text'] ?? '')
                );
                $state['created_new_count'] = ((int) ($state['created_new_count'] ?? 0)) + 1;
            }

            $processed_this_batch++;
            if ($processed_this_batch >= 1 && (microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                break;
            }
        }

        $state['processed_sources'] = min($total_sources, $processed_sources + $processed_this_batch);
        if ((int) $state['processed_sources'] >= $total_sources) {
            $state['phase'] = 'cleanup';
            $state['message'] = 'Meninjau soal lama yang tidak lagi dipakai.';
        } else {
            $state['phase'] = 'sync';
            $state['message'] = sprintf(
                'Menyinkronkan soal %d dari %d.',
                (int) $state['processed_sources'],
                $total_sources
            );
        }

        return $state;
    }

    /**
     * @param array<string,mixed> $source_row
     * @param array<int,array<string,mixed>> $source_options
     * @param array<string,mixed> $source_detail
     * @return array<string,mixed>
     */
    private static function build_exam_sync_source_snapshot(array $source_row, array $source_options, array $source_detail): array
    {
        $question_type = (string) ($source_row['question_type'] ?? 'multiple_choice');
        $detail_text = '';
        if ($question_type === 'true_false') {
            $detail_value = isset($source_detail['correct_value'])
                ? (int) $source_detail['correct_value']
                : self::normalize_true_false_value((string) ($source_row['correct_text'] ?? ''));
            $detail_text = ($detail_value === 0) ? 'false' : 'true';
        } elseif ($question_type === 'short_answer') {
            $detail_text = (string) ($source_detail['correct_text'] ?? ($source_row['correct_text'] ?? ''));
        } elseif ($question_type === 'essay') {
            $detail_text = (string) ($source_detail['rubric_text'] ?? ($source_row['correct_text'] ?? ''));
        }

        return [
            'question_text' => (string) ($source_row['question_text'] ?? ''),
            'question_type' => $question_type,
            'points' => (float) ($source_row['points'] ?? 1),
            'correct_text' => (string) ($source_row['correct_text'] ?? ''),
            'explanation' => (string) ($source_row['explanation'] ?? ''),
            'normalized_detail_text' => $detail_text,
            'options' => $source_options,
        ];
    }

    /**
     * @param array<string,mixed> $state
     * @return array<string,mixed>
     */
    private static function build_exam_save_progress_payload(array $state): array
    {
        $phase = sanitize_key((string) ($state['phase'] ?? 'sync'));
        $phase_labels = [
            'sync' => 'Sinkron Soal',
            'cleanup' => 'Bersihkan Soal Lama',
            'finalize' => 'Finalize Exam',
            'complete' => 'Selesai',
        ];
        $total_sources = max(0, (int) ($state['total_sources'] ?? 0));
        $processed_sources = max(0, min($total_sources, (int) ($state['processed_sources'] ?? 0)));
        if ($total_sources > 0) {
            if ($phase === 'sync') {
                $percent = 8 + (((float) $processed_sources / (float) $total_sources) * 84);
            } elseif ($phase === 'cleanup') {
                $percent = 94.0;
            } elseif ($phase === 'finalize') {
                $percent = 98.0;
            } else {
                $percent = 100.0;
            }
        } else {
            $percent = ($phase === 'complete') ? 100.0 : 92.0;
        }

        $stats = [];
        if ($total_sources > 0) {
            $stats[] = sprintf('%d/%d soal', $processed_sources, $total_sources);
        }
        $updated_existing_count = max(0, (int) ($state['updated_existing_count'] ?? 0));
        $created_new_count = max(0, (int) ($state['created_new_count'] ?? 0));
        $removed_question_count = max(0, (int) ($state['removed_question_count'] ?? 0));
        if ($updated_existing_count > 0) {
            $stats[] = 'Update: ' . $updated_existing_count;
        }
        if ($created_new_count > 0) {
            $stats[] = 'Tambah baru: ' . $created_new_count;
        }
        if ($removed_question_count > 0) {
            $stats[] = 'Dibersihkan: ' . $removed_question_count;
        }

        return [
            'phase' => $phase,
            'phase_label' => $phase_labels[$phase] ?? 'Memproses Exam',
            'message' => (string) ($state['message'] ?? 'Memproses exam.'),
            'processed_questions' => $processed_sources,
            'total_questions' => $total_sources,
            'updated_existing_count' => $updated_existing_count,
            'created_new_count' => $created_new_count,
            'removed_question_count' => $removed_question_count,
            'percent' => round(min(100.0, max(0.0, $percent)), 2),
            'complete' => ($phase === 'complete'),
            'redirect_url' => (string) ($state['redirect_url'] ?? ''),
            'stats' => implode(' | ', $stats),
        ];
    }

    public static function handle_save_exam(): void
    {
        if (!self::can_manage_exams()) {
            wp_die('Unauthorized');
        }

        check_admin_referer('cbt_save_exam');

        global $wpdb;

        $table = $wpdb->prefix . 'cbt_exams';
        $is_admin_scope = self::is_admin_scope();
        $current_user_id = get_current_user_id();
        $exam_list_state = self::get_exam_list_state_from_request($_POST);

        $id = isset($_POST['id']) ? absint($_POST['id']) : 0;
        $subject_id = isset($_POST['subject_id']) ? absint($_POST['subject_id']) : 0;
        $title = isset($_POST['title']) ? sanitize_text_field(wp_unslash($_POST['title'])) : '';
        $description = isset($_POST['description']) ? wp_kses_post(wp_unslash($_POST['description'])) : '';
        $duration = max(1, isset($_POST['duration_minutes']) ? absint($_POST['duration_minutes']) : 60);
        $randomize = isset($_POST['randomize_questions']) ? 1 : 0;
        $randomize_options = isset($_POST['randomize_options']) ? 1 : 0;
        $status = isset($_POST['status']) ? sanitize_text_field(wp_unslash($_POST['status'])) : 'draft';
        $allowed_statuses = ['draft', 'published', 'closed'];
        if (!in_array($status, $allowed_statuses, true)) {
            $status = 'draft';
        }
        $starts_at = isset($_POST['starts_at']) ? self::from_datetime_local((string) wp_unslash($_POST['starts_at'])) : null;
        $ends_at = isset($_POST['ends_at']) ? self::from_datetime_local((string) wp_unslash($_POST['ends_at'])) : null;
        $target_kelas_raw = isset($_POST['target_kelas']) ? wp_unslash($_POST['target_kelas']) : '';
        $target_kelas = self::normalize_target_kelas_csv($target_kelas_raw);

        $raw_source_question_ids = isset($_POST['source_question_ids']) && is_array($_POST['source_question_ids'])
            ? wp_unslash($_POST['source_question_ids'])
            : [];
        $source_question_ids = array_values(array_unique(array_filter(array_map('absint', $raw_source_question_ids))));

        if ($subject_id <= 0) {
            self::redirect_exam_with_error('Mapel wajib dipilih.', $id);
        }
        if ($title === '') {
            self::redirect_exam_with_error('Judul exam wajib diisi.', $id);
        }
        if ($starts_at !== null && $ends_at !== null && strtotime($ends_at) < strtotime($starts_at)) {
            self::redirect_exam_with_error('Waktu selesai tidak boleh lebih awal dari waktu mulai.', $id);
        }
        if ($id <= 0 && empty($source_question_ids)) {
            self::redirect_exam_with_error('Pilih minimal 1 soal untuk exam baru.');
        }

        $existing_question_count = 0;
        if ($id > 0 && empty($source_question_ids)) {
            $existing_question_count = (int) $wpdb->get_var(
                $wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}cbt_questions WHERE exam_id = %d AND COALESCE(is_active, 1) = 1", $id)
            );
        }

        $data = [
            'subject_id' => $subject_id,
            'title' => $title,
            'description' => $description,
            'duration_minutes' => $duration,
            'total_questions' => $existing_question_count,
            'randomize_questions' => $randomize,
            'randomize_options' => $randomize_options,
            'status' => $status,
            'starts_at' => $starts_at,
            'ends_at' => $ends_at,
            'target_kelas' => $target_kelas,
            'updated_at' => current_time('mysql'),
        ];

        $saved_exam_id = $id;
        if ($id > 0) {
            if (!$is_admin_scope) {
                $owned_exam = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM {$table} WHERE id = %d AND created_by = %d",
                    $id,
                    $current_user_id
                ));
                if ($owned_exam === 0) {
                    wp_die('Unauthorized exam update.');
                }
            }

            $updated = $wpdb->update(
                $table,
                $data,
                ['id' => $id],
                ['%d', '%s', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s'],
                ['%d']
            );
            if ($updated === false) {
                self::redirect_exam_with_error('Gagal mengupdate exam.', $id);
            }
        } else {
            $data['created_by'] = $current_user_id;
            $data['created_at'] = current_time('mysql');

            $inserted = $wpdb->insert(
                $table,
                $data,
                ['%d', '%s', '%s', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%d', '%s']
            );
            if (!$inserted) {
                self::redirect_exam_with_error('Gagal membuat exam.');
            }

            $saved_exam_id = (int) $wpdb->insert_id;
        }

        $synced_questions = null;
        if (!empty($source_question_ids)) {
            $sync_result = self::sync_exam_questions_from_sources(
                $saved_exam_id,
                $source_question_ids,
                $is_admin_scope,
                $current_user_id
            );
            if (is_wp_error($sync_result)) {
                self::redirect_exam_with_error($sync_result->get_error_message(), $saved_exam_id);
            }

            $synced_questions = (int) $sync_result;
            $wpdb->update(
                $table,
                [
                    'total_questions' => $synced_questions,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $saved_exam_id],
                ['%d', '%s'],
                ['%d']
            );

            self::clear_exam_attempt_states($saved_exam_id);
        }

        $msg = ($id > 0) ? 'Exam updated' : 'Exam created';
        if ($synced_questions !== null) {
            $msg .= ' - ' . $synced_questions . ' soal tersinkron.';
        }

        CBT_Cache::invalidate_catalog();
        CBT_Cache::invalidate_exam($saved_exam_id);
        self::clear_exam_builder_selection_state('cbt_exam_builder_new', $current_user_id);
        self::clear_exam_builder_selection_state('cbt_exam_builder_edit_' . $saved_exam_id, $current_user_id);

        wp_safe_redirect(add_query_arg(
            self::add_exam_list_state_args(
                [
                    'page' => 'cbt-exams',
                    'cbt_exam_panel' => 'list',
                    'cbt_msg' => $msg,
                    'cbt_saved_exam_id' => (int) $saved_exam_id,
                ],
                $exam_list_state
            ),
            admin_url('admin.php')
        ));
        exit;
    }

    public static function handle_delete_exam(): void
    {
        if (!self::can_manage_exams()) {
            wp_die('Unauthorized');
        }

        $id = isset($_GET['id']) ? absint($_GET['id']) : 0;
        check_admin_referer('cbt_delete_exam_' . $id);
        $exam_list_state = self::get_exam_list_state_from_request($_GET);

        if ($id > 0) {
            global $wpdb;
            $exam_title = (string) $wpdb->get_var(
                $wpdb->prepare("SELECT title FROM {$wpdb->prefix}cbt_exams WHERE id = %d", $id)
            );
            if (stripos($exam_title, 'Bank Soal - ') === 0) {
                wp_safe_redirect(add_query_arg(
                    self::add_exam_list_state_args(
                        [
                            'page' => 'cbt-exams',
                            'cbt_exam_panel' => 'list',
                            'cbt_err' => 'Exam bank soal tidak boleh dihapus dari menu ini.',
                        ],
                        $exam_list_state
                    ),
                    admin_url('admin.php')
                ));
                exit;
            }

            if (!self::is_admin_scope()) {
                $owned_exam = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM {$wpdb->prefix}cbt_exams WHERE id = %d AND created_by = %d",
                    $id,
                    get_current_user_id()
                ));
                if ($owned_exam === 0) {
                    wp_die('Unauthorized exam delete.');
                }
            }

            $wpdb->delete($wpdb->prefix . 'cbt_exams', ['id' => $id], ['%d']);
        }

        if ($id > 0) {
            CBT_Cache::invalidate_catalog();
            CBT_Cache::invalidate_exam($id);
        }

        wp_safe_redirect(add_query_arg(
            self::add_exam_list_state_args(
                [
                    'page' => 'cbt-exams',
                    'cbt_exam_panel' => 'list',
                    'cbt_msg' => 'Exam deleted',
                ],
                $exam_list_state
            ),
            admin_url('admin.php')
        ));
        exit;
    }

    /**
     * @return int|WP_Error
     */
    private static function sync_exam_questions_from_sources(
        int $exam_id,
        array $source_question_ids,
        bool $is_admin_scope,
        int $current_user_id
    ) {
        global $wpdb;

        if ($exam_id <= 0) {
            return new WP_Error('invalid_exam', 'Exam tidak valid.');
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $option_table = $wpdb->prefix . 'cbt_options';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $preserve_attempt_history = self::exam_has_attempt_records($exam_id);
        $source_question_ids = array_values(array_unique(array_filter(array_map('absint', $source_question_ids))));

        if (empty($source_question_ids)) {
            return new WP_Error('empty_questions', 'Pilih minimal 1 soal.');
        }

        $source_placeholders = implode(',', array_fill(0, count($source_question_ids), '%d'));
        $query_params = $source_question_ids;

        $source_sql = "SELECT q.*
                       FROM {$question_table} q
                       INNER JOIN {$exam_table} e ON e.id = q.exam_id
                       WHERE q.id IN ({$source_placeholders})";

        if (!$is_admin_scope) {
            $source_sql .= ' AND e.created_by = %d';
            $query_params[] = $current_user_id;
        }

        $source_rows = $wpdb->get_results($wpdb->prepare($source_sql, ...$query_params), ARRAY_A);
        $source_by_id = [];
        foreach ((array) $source_rows as $source_row) {
            $source_by_id[(int) ($source_row['id'] ?? 0)] = $source_row;
        }

        $ordered_sources = [];
        foreach ($source_question_ids as $source_question_id) {
            if (isset($source_by_id[$source_question_id])) {
                $ordered_sources[] = $source_by_id[$source_question_id];
            }
        }

        if (empty($ordered_sources)) {
            return new WP_Error('invalid_questions', 'Soal sumber tidak ditemukan.');
        }

        $ordered_source_ids = array_map(static function ($row): int {
            return (int) ($row['id'] ?? 0);
        }, $ordered_sources);

        $option_placeholders = implode(',', array_fill(0, count($ordered_source_ids), '%d'));
        $option_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT * FROM {$option_table} WHERE question_id IN ({$option_placeholders}) ORDER BY id ASC",
                ...$ordered_source_ids
            ),
            ARRAY_A
        );

        $options_by_question = [];
        foreach ((array) $option_rows as $option_row) {
            $question_id = (int) ($option_row['question_id'] ?? 0);
            if ($question_id <= 0) {
                continue;
            }
            if (!isset($options_by_question[$question_id])) {
                $options_by_question[$question_id] = [];
            }
            $options_by_question[$question_id][] = $option_row;
        }

        $detail_by_question = [];
        foreach ($ordered_sources as $source_row) {
            $source_question_id = (int) ($source_row['id'] ?? 0);
            $source_question_type = (string) ($source_row['question_type'] ?? '');
            $detail_by_question[$source_question_id] = self::get_question_type_detail($source_question_id, $source_question_type);
        }

        $existing_exam_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, source_question_id, COALESCE(is_active, 1) AS is_active
                 FROM {$question_table}
                 WHERE exam_id = %d
                 ORDER BY COALESCE(is_active, 1) DESC, id ASC",
                $exam_id
            ),
            ARRAY_A
        );

        $existing_by_source = [];
        $existing_snapshots = [];
        $unmatched_existing_ids = [];
        foreach ((array) $existing_exam_rows as $existing_exam_row) {
            $existing_question_id = (int) ($existing_exam_row['id'] ?? 0);
            if ($existing_question_id <= 0) {
                continue;
            }

            $is_active_existing = (int) ($existing_exam_row['is_active'] ?? 1) === 1;
            if ($preserve_attempt_history && !$is_active_existing) {
                continue;
            }

            $existing_source_question_id = (int) ($existing_exam_row['source_question_id'] ?? 0);
            if ($existing_source_question_id > 0) {
                if (!isset($existing_by_source[$existing_source_question_id])) {
                    $existing_by_source[$existing_source_question_id] = [];
                }
                $existing_by_source[$existing_source_question_id][] = $existing_question_id;
            }

            $existing_snapshots[$existing_question_id] = self::get_question_sync_snapshot($existing_question_id);
            $unmatched_existing_ids[$existing_question_id] = $existing_question_id;
        }

        $inserted_count = 0;
        $now = current_time('mysql');

        foreach ($ordered_sources as $source_row) {
            $source_question_id = (int) ($source_row['id'] ?? 0);
            $question_type = (string) ($source_row['question_type'] ?? 'multiple_choice');
            $source_options = $options_by_question[$source_question_id] ?? [];
            $source_detail = $detail_by_question[$source_question_id] ?? [];
            $detail_text = '';
            if ($question_type === 'true_false') {
                $detail_value = isset($source_detail['correct_value'])
                    ? (int) $source_detail['correct_value']
                    : self::normalize_true_false_value((string) ($source_row['correct_text'] ?? ''));
                $detail_text = ($detail_value === 0) ? 'false' : 'true';
            } elseif ($question_type === 'short_answer') {
                $detail_text = (string) ($source_detail['correct_text'] ?? ($source_row['correct_text'] ?? ''));
            } elseif ($question_type === 'essay') {
                $detail_text = (string) ($source_detail['rubric_text'] ?? ($source_row['correct_text'] ?? ''));
            }

            $source_snapshot = [
                'question_text' => (string) ($source_row['question_text'] ?? ''),
                'question_type' => $question_type,
                'points' => (float) ($source_row['points'] ?? 1),
                'correct_text' => (string) ($source_row['correct_text'] ?? ''),
                'explanation' => (string) ($source_row['explanation'] ?? ''),
                'normalized_detail_text' => $detail_text,
                'options' => $source_options,
            ];

            $matched_question_id = 0;
            if (isset($existing_by_source[$source_question_id]) && !empty($existing_by_source[$source_question_id])) {
                $matched_question_id = (int) array_shift($existing_by_source[$source_question_id]);
            }

            if ($matched_question_id <= 0 && !empty($unmatched_existing_ids)) {
                foreach ($unmatched_existing_ids as $candidate_question_id) {
                    $candidate_snapshot = (array) ($existing_snapshots[$candidate_question_id] ?? []);
                    if (empty($candidate_snapshot)) {
                        continue;
                    }

                    if (self::question_snapshots_are_legacy_descendant_match($candidate_snapshot, $source_snapshot)) {
                        $matched_question_id = (int) $candidate_question_id;
                        break;
                    }
                }
            }

            if ($matched_question_id > 0) {
                $target_snapshot = (array) ($existing_snapshots[$matched_question_id] ?? []);
                $updated_exam_id = $preserve_attempt_history
                    ? self::link_existing_exam_question_to_source(
                        $matched_question_id,
                        $source_question_id,
                        $target_snapshot
                    )
                    : self::apply_source_snapshot_to_question(
                        $matched_question_id,
                        $source_question_id,
                        $source_snapshot,
                        $target_snapshot
                    );
                if ($updated_exam_id <= 0) {
                    return new WP_Error('update_failed', 'Gagal menyinkronkan salah satu soal exam yang sudah ada.');
                }

                unset($unmatched_existing_ids[$matched_question_id]);
                $inserted_count++;
                continue;
            }

            $inserted_question = $wpdb->insert(
                $question_table,
                [
                    'exam_id' => $exam_id,
                    'source_question_id' => $source_question_id,
                    'is_active' => 1,
                    'question_text' => (string) ($source_row['question_text'] ?? ''),
                    'question_type' => $question_type,
                    'points' => (float) ($source_row['points'] ?? 1),
                    'correct_text' => (string) ($source_row['correct_text'] ?? ''),
                    'explanation' => (string) ($source_row['explanation'] ?? ''),
                    'created_at' => $now,
                    'updated_at' => $now,
                ],
                ['%d', '%d', '%d', '%s', '%s', '%f', '%s', '%s', '%s', '%s']
            );

            if (!$inserted_question) {
                return new WP_Error('insert_failed', 'Gagal menyalin salah satu soal ke exam.');
            }

            $new_question_id = (int) $wpdb->insert_id;
            foreach ($source_options as $source_option) {
                $wpdb->insert(
                    $option_table,
                    [
                        'question_id' => $new_question_id,
                        'option_key' => (string) ($source_option['option_key'] ?? ''),
                        'option_text' => (string) ($source_option['option_text'] ?? ''),
                        'is_correct' => (int) ($source_option['is_correct'] ?? 0),
                        'created_at' => $now,
                    ],
                    ['%d', '%s', '%s', '%d', '%s']
                );
            }

            self::save_question_type_detail($new_question_id, $question_type, $detail_text);
            $inserted_count++;
        }

        if (!empty($unmatched_existing_ids)) {
            $stale_question_ids = array_values(array_filter(array_map('absint', array_values($unmatched_existing_ids))));
            if (!empty($stale_question_ids)) {
                $cleanup_result = self::archive_or_delete_exam_questions($exam_id, $stale_question_ids);
                if (is_wp_error($cleanup_result)) {
                    return $cleanup_result;
                }
            }
        }

        return $inserted_count;
    }

    private static function clear_exam_attempt_states(int $exam_id): void
    {
        global $wpdb;

        if ($exam_id <= 0) {
            return;
        }

        $attempt_table = $wpdb->prefix . 'cbt_attempts';
        $attempt_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT id
                 FROM {$attempt_table}
                 WHERE exam_id = %d",
                $exam_id
            )
        );

        $attempt_ids = array_values(array_unique(array_filter(array_map('absint', (array) $attempt_ids))));
        if (empty($attempt_ids)) {
            return;
        }

        CBT_Cache::invalidate_attempts($attempt_ids);
        CBT_UI_State::clear_attempt_states_by_attempt_ids($attempt_ids);
        if (class_exists('CBT_Runtime')) {
            foreach ($attempt_ids as $attempt_id) {
                CBT_Runtime::clear_attempt_runtime((int) $attempt_id);
            }
        }
    }

    private static function exam_has_attempt_records(int $exam_id): bool
    {
        global $wpdb;

        if ($exam_id <= 0) {
            return false;
        }

        $attempt_table = $wpdb->prefix . 'cbt_attempts';
        $attempt_count = (int) $wpdb->get_var(
            $wpdb->prepare(
                "SELECT COUNT(*)
                 FROM {$attempt_table}
                 WHERE exam_id = %d",
                $exam_id
            )
        );

        return $attempt_count > 0;
    }

    private static function link_existing_exam_question_to_source(
        int $target_question_id,
        int $source_question_id,
        array $target_snapshot = []
    ): int {
        global $wpdb;

        if ($target_question_id <= 0 || $source_question_id <= 0) {
            return 0;
        }

        if (empty($target_snapshot)) {
            $target_snapshot = self::get_question_sync_snapshot($target_question_id);
        }
        if (empty($target_snapshot)) {
            return 0;
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $updated = $wpdb->update(
            $question_table,
            [
                'source_question_id' => $source_question_id,
                'is_active' => 1,
                'updated_at' => current_time('mysql'),
            ],
            ['id' => $target_question_id],
            ['%d', '%d', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return 0;
        }

        return (int) ($target_snapshot['exam_id'] ?? 0);
    }

    private static function is_bank_exam_title(string $exam_title): bool
    {
        return stripos($exam_title, 'Bank Soal - ') === 0;
    }

    private static function is_bank_question_snapshot(array $snapshot): bool
    {
        return self::is_bank_exam_title((string) ($snapshot['exam_title'] ?? ''));
    }

    /**
     * @return array<string,mixed>
     */
    private static function get_question_sync_snapshot(int $question_id): array
    {
        global $wpdb;

        if ($question_id <= 0) {
            return [];
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $option_table = $wpdb->prefix . 'cbt_options';

        $row = $wpdb->get_row(
            $wpdb->prepare(
                "SELECT q.*, e.subject_id, e.title AS exam_title
                 FROM {$question_table} q
                 INNER JOIN {$exam_table} e ON e.id = q.exam_id
                 WHERE q.id = %d
                 LIMIT 1",
                $question_id
            ),
            ARRAY_A
        );
        if (!is_array($row) || empty($row)) {
            return [];
        }

        $options = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, option_key, option_text, is_correct
                 FROM {$option_table}
                 WHERE question_id = %d
                 ORDER BY id ASC",
                $question_id
            ),
            ARRAY_A
        );

        $question_type = (string) ($row['question_type'] ?? '');
        $detail = self::get_question_type_detail($question_id, $question_type);
        $normalized_detail_text = '';
        if ($question_type === 'true_false') {
            $detail_value = array_key_exists('correct_value', $detail)
                ? (int) $detail['correct_value']
                : self::normalize_true_false_value((string) ($row['correct_text'] ?? ''));
            $normalized_detail_text = ($detail_value === 0) ? 'false' : 'true';
        } elseif ($question_type === 'short_answer') {
            $normalized_detail_text = (string) ($detail['correct_text'] ?? ($row['correct_text'] ?? ''));
        } elseif ($question_type === 'essay') {
            $normalized_detail_text = (string) ($detail['rubric_text'] ?? ($row['correct_text'] ?? ''));
        } elseif ($question_type === 'true_false_matrix') {
            $normalized_detail_text = (string) ($row['correct_text'] ?? '');
        }

        return [
            'question_id' => (int) ($row['id'] ?? 0),
            'exam_id' => (int) ($row['exam_id'] ?? 0),
            'subject_id' => (int) ($row['subject_id'] ?? 0),
            'exam_title' => (string) ($row['exam_title'] ?? ''),
            'source_question_id' => (int) ($row['source_question_id'] ?? 0),
            'question_text' => (string) ($row['question_text'] ?? ''),
            'question_type' => $question_type,
            'points' => (float) ($row['points'] ?? 0),
            'correct_text' => (string) ($row['correct_text'] ?? ''),
            'explanation' => (string) ($row['explanation'] ?? ''),
            'normalized_detail_text' => $normalized_detail_text,
            'options' => is_array($options) ? $options : [],
        ];
    }

    /**
     * @param array<int,array<string,mixed>> $options
     * @return array<int,array<string,mixed>>
     */
    private static function normalize_question_sync_options(array $options): array
    {
        $normalized = [];

        foreach ($options as $index => $option_row) {
            $option = (array) $option_row;
            $option_key = trim((string) ($option['option_key'] ?? ''));
            $normalized[] = [
                'id' => (int) ($option['id'] ?? 0),
                'option_key' => $option_key,
                'match_key' => $option_key !== '' ? $option_key : '__idx_' . $index,
                'option_text' => (string) ($option['option_text'] ?? ''),
                'is_correct' => ((int) ($option['is_correct'] ?? 0) === 1) ? 1 : 0,
            ];
        }

        return $normalized;
    }

    /**
     * @return array<int,array<string,mixed>>
     */
    private static function option_sync_signature(array $options): array
    {
        $signature = [];
        foreach (self::normalize_question_sync_options($options) as $option) {
            $signature[] = [
                'match_key' => (string) ($option['match_key'] ?? ''),
                'option_text' => (string) ($option['option_text'] ?? ''),
                'is_correct' => (int) ($option['is_correct'] ?? 0),
            ];
        }

        return $signature;
    }

    private static function question_snapshots_are_sync_equivalent(array $left, array $right): bool
    {
        return
            (string) ($left['question_text'] ?? '') === (string) ($right['question_text'] ?? '') &&
            (string) ($left['question_type'] ?? '') === (string) ($right['question_type'] ?? '') &&
            round((float) ($left['points'] ?? 0), 2) === round((float) ($right['points'] ?? 0), 2) &&
            (string) ($left['correct_text'] ?? '') === (string) ($right['correct_text'] ?? '') &&
            (string) ($left['explanation'] ?? '') === (string) ($right['explanation'] ?? '') &&
            (string) ($left['normalized_detail_text'] ?? '') === (string) ($right['normalized_detail_text'] ?? '') &&
            self::option_sync_signature((array) ($left['options'] ?? [])) === self::option_sync_signature((array) ($right['options'] ?? []));
    }

    private static function question_snapshots_are_legacy_descendant_match(array $candidate, array $source): bool
    {
        if (self::question_snapshots_are_sync_equivalent($candidate, $source)) {
            return true;
        }

        return
            (string) ($candidate['question_type'] ?? '') === (string) ($source['question_type'] ?? '') &&
            round((float) ($candidate['points'] ?? 0), 2) === round((float) ($source['points'] ?? 0), 2) &&
            (string) ($candidate['correct_text'] ?? '') === (string) ($source['correct_text'] ?? '') &&
            (string) ($candidate['explanation'] ?? '') === (string) ($source['explanation'] ?? '') &&
            (string) ($candidate['normalized_detail_text'] ?? '') === (string) ($source['normalized_detail_text'] ?? '') &&
            self::option_sync_signature((array) ($candidate['options'] ?? [])) === self::option_sync_signature((array) ($source['options'] ?? [])) &&
            self::question_texts_look_related(
                (string) ($candidate['question_text'] ?? ''),
                (string) ($source['question_text'] ?? '')
            );
    }

    private static function question_texts_look_related(string $left, string $right): bool
    {
        $left = strtolower(trim(preg_replace('/\s+/', ' ', wp_strip_all_tags($left))));
        $right = strtolower(trim(preg_replace('/\s+/', ' ', wp_strip_all_tags($right))));
        if ($left === '' || $right === '') {
            return false;
        }

        if ($left === $right) {
            return true;
        }

        if (strpos($left, $right) !== false || strpos($right, $left) !== false) {
            return true;
        }

        similar_text($left, $right, $percent);
        return $percent >= 82.0;
    }

    /**
     * @return int[]
     */
    private static function collect_descendant_question_ids_for_source(int $source_question_id, array $reference_snapshot): array
    {
        global $wpdb;

        if ($source_question_id <= 0 || empty($reference_snapshot)) {
            return [];
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $direct_descendant_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT id
                 FROM {$question_table}
                 WHERE source_question_id = %d
                   AND id <> %d",
                $source_question_id,
                $source_question_id
            )
        );

        $target_question_ids = [];
        foreach ((array) $direct_descendant_ids as $target_question_id) {
            $target_question_id = (int) $target_question_id;
            if ($target_question_id > 0) {
                $target_question_ids[$target_question_id] = $target_question_id;
            }
        }

        foreach (self::find_legacy_descendant_question_ids($source_question_id, $reference_snapshot) as $target_question_id) {
            $target_question_id = (int) $target_question_id;
            if ($target_question_id > 0) {
                $target_question_ids[$target_question_id] = $target_question_id;
            }
        }

        return array_values($target_question_ids);
    }

    /**
     * @return int[]
     */
    private static function propagate_bank_question_update(int $source_question_id, array $before_snapshot, array $after_snapshot): array
    {
        global $wpdb;

        if ($source_question_id <= 0 || empty($before_snapshot) || empty($after_snapshot)) {
            return [];
        }

        $affected_exam_ids = [];
        foreach (self::collect_descendant_question_ids_for_source($source_question_id, $before_snapshot) as $target_question_id) {
            $target_snapshot = self::get_question_sync_snapshot($target_question_id);
            if (empty($target_snapshot)) {
                continue;
            }

            $affected_exam_id = self::apply_source_snapshot_to_question(
                $target_question_id,
                $source_question_id,
                $after_snapshot,
                $target_snapshot
            );
            if ($affected_exam_id > 0) {
                $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
            }
        }

        return array_values($affected_exam_ids);
    }

    /**
     * @return array{scanned_sources:int,updated_questions:int,new_links:int,affected_exams:int,error?:string}
     */
    public static function run_question_source_backfill(): array
    {
        global $wpdb;

        $question_table = $wpdb->prefix . 'cbt_questions';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$question_table}", 0);
        if (!is_array($columns) || !in_array('source_question_id', $columns, true)) {
            return [
                'scanned_sources' => 0,
                'updated_questions' => 0,
                'new_links' => 0,
                'affected_exams' => 0,
                'error' => 'Kolom source_question_id belum tersedia. Muat ulang plugin atau jalankan upgrade terlebih dahulu.',
            ];
        }

        $bank_question_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT q.id
                 FROM {$question_table} q
                 INNER JOIN {$exam_table} e ON e.id = q.exam_id
                 WHERE e.title LIKE %s
                 ORDER BY q.id ASC",
                'Bank Soal - %'
            )
        );

        $claimed_question_ids = [];
        $updated_question_ids = [];
        $new_link_ids = [];
        $affected_exam_ids = [];
        $scanned_sources = 0;

        foreach ((array) $bank_question_ids as $source_question_id) {
            $source_question_id = (int) $source_question_id;
            if ($source_question_id <= 0) {
                continue;
            }

            $source_snapshot = self::get_question_sync_snapshot($source_question_id);
            if (empty($source_snapshot) || !self::is_bank_question_snapshot($source_snapshot)) {
                continue;
            }

            $scanned_sources++;
            foreach (self::collect_descendant_question_ids_for_source($source_question_id, $source_snapshot) as $target_question_id) {
                $target_question_id = (int) $target_question_id;
                if ($target_question_id <= 0 || isset($claimed_question_ids[$target_question_id])) {
                    continue;
                }

                $target_snapshot = self::get_question_sync_snapshot($target_question_id);
                if (empty($target_snapshot)) {
                    continue;
                }

                $affected_exam_id = self::apply_source_snapshot_to_question(
                    $target_question_id,
                    $source_question_id,
                    $source_snapshot,
                    $target_snapshot
                );
                if ($affected_exam_id <= 0) {
                    continue;
                }

                $claimed_question_ids[$target_question_id] = true;
                $updated_question_ids[$target_question_id] = $target_question_id;
                if ((int) ($target_snapshot['source_question_id'] ?? 0) !== $source_question_id) {
                    $new_link_ids[$target_question_id] = $target_question_id;
                }
                $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
            }
        }

        if (!empty($affected_exam_ids)) {
            CBT_Cache::invalidate_exams(array_values($affected_exam_ids));
        }

        return [
            'scanned_sources' => $scanned_sources,
            'updated_questions' => count($updated_question_ids),
            'new_links' => count($new_link_ids),
            'affected_exams' => count($affected_exam_ids),
        ];
    }

    /**
     * @return int[]
     */
    private static function find_legacy_descendant_question_ids(int $source_question_id, array $before_snapshot): array
    {
        global $wpdb;

        $source_exam_id = (int) ($before_snapshot['exam_id'] ?? 0);
        $subject_id = (int) ($before_snapshot['subject_id'] ?? 0);
        if ($source_question_id <= 0 || $source_exam_id <= 0 || $subject_id <= 0) {
            return [];
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $candidate_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT q.id
                 FROM {$question_table} q
                 INNER JOIN {$exam_table} e ON e.id = q.exam_id
                 WHERE e.subject_id = %d
                   AND e.title NOT LIKE %s
                   AND q.exam_id <> %d
                   AND q.id <> %d
                   AND (q.source_question_id IS NULL OR q.source_question_id = 0)
                   AND q.question_type = %s
                   AND q.points = %f
                   AND COALESCE(q.correct_text, '') = %s
                   AND COALESCE(q.explanation, '') = %s",
                $subject_id,
                'Bank Soal - %',
                $source_exam_id,
                $source_question_id,
                (string) ($before_snapshot['question_type'] ?? ''),
                (float) ($before_snapshot['points'] ?? 0),
                (string) ($before_snapshot['correct_text'] ?? ''),
                (string) ($before_snapshot['explanation'] ?? '')
            )
        );

        $matched_ids = [];
        foreach ((array) $candidate_ids as $candidate_id) {
            $candidate_id = (int) $candidate_id;
            if ($candidate_id <= 0) {
                continue;
            }

            $candidate_snapshot = self::get_question_sync_snapshot($candidate_id);
            if (empty($candidate_snapshot)) {
                continue;
            }

            if (!self::question_snapshots_are_legacy_descendant_match($candidate_snapshot, $before_snapshot)) {
                continue;
            }

            $matched_ids[] = $candidate_id;
        }

        return $matched_ids;
    }

    private static function apply_source_snapshot_to_question(
        int $target_question_id,
        int $source_question_id,
        array $source_snapshot,
        array $target_snapshot = []
    ): int {
        global $wpdb;

        if ($target_question_id <= 0 || $source_question_id <= 0 || empty($source_snapshot)) {
            return 0;
        }

        if (empty($target_snapshot)) {
            $target_snapshot = self::get_question_sync_snapshot($target_question_id);
        }
        if (empty($target_snapshot)) {
            return 0;
        }

        $question_table = $wpdb->prefix . 'cbt_questions';
        $now = current_time('mysql');
        $question_type = (string) ($source_snapshot['question_type'] ?? 'multiple_choice');
        $correct_text = (string) ($source_snapshot['correct_text'] ?? '');
        $explanation = (string) ($source_snapshot['explanation'] ?? '');
        $old_question_type = (string) ($target_snapshot['question_type'] ?? '');

        $updated = $wpdb->update(
            $question_table,
            [
                'source_question_id' => $source_question_id,
                'is_active' => 1,
                'question_text' => (string) ($source_snapshot['question_text'] ?? ''),
                'question_type' => $question_type,
                'points' => (float) ($source_snapshot['points'] ?? 0),
                'correct_text' => $correct_text !== '' ? $correct_text : null,
                'explanation' => $explanation !== '' ? $explanation : null,
                'updated_at' => $now,
            ],
            ['id' => $target_question_id],
            ['%d', '%d', '%s', '%s', '%f', '%s', '%s', '%s'],
            ['%d']
        );
        if ($updated === false) {
            return 0;
        }

        $option_id_map = self::sync_question_options_from_snapshot(
            $target_question_id,
            (array) ($source_snapshot['options'] ?? []),
            (array) ($target_snapshot['options'] ?? [])
        );

        self::save_question_type_detail(
            $target_question_id,
            $question_type,
            (string) ($source_snapshot['normalized_detail_text'] ?? '')
        );

        if ($old_question_type !== $question_type) {
            self::clear_question_answer_records($target_question_id, true);
            if (class_exists('CBT_Runtime')) {
                CBT_Runtime::remap_active_attempt_answers_for_question($target_question_id, [], true);
            }
        } elseif (self::question_type_uses_choice_options($question_type)) {
            self::remap_question_answer_option_ids($target_question_id, $option_id_map);
            if (class_exists('CBT_Runtime')) {
                CBT_Runtime::remap_active_attempt_answers_for_question($target_question_id, $option_id_map, false);
            }
        }

        return (int) ($target_snapshot['exam_id'] ?? 0);
    }

    /**
     * @param array<int,int> $question_ids
     * @return true|WP_Error
     */
    private static function archive_or_delete_exam_questions(int $exam_id, array $question_ids)
    {
        global $wpdb;

        $question_table = $wpdb->prefix . 'cbt_questions';
        $question_ids = array_values(array_unique(array_filter(array_map('absint', $question_ids))));
        if ($exam_id <= 0 || empty($question_ids)) {
            return true;
        }

        $protected_ids = self::find_historical_question_ids($exam_id, $question_ids);
        $archive_ids = array_values(array_intersect($question_ids, $protected_ids));
        $delete_ids = array_values(array_diff($question_ids, $archive_ids));
        $now = current_time('mysql');

        if (!empty($archive_ids)) {
            $archive_placeholders = implode(',', array_fill(0, count($archive_ids), '%d'));
            $archive_result = $wpdb->query(
                $wpdb->prepare(
                    "UPDATE {$question_table}
                     SET is_active = 0,
                         updated_at = %s
                     WHERE exam_id = %d
                       AND id IN ({$archive_placeholders})",
                    $now,
                    $exam_id,
                    ...$archive_ids
                )
            );
            if ($archive_result === false) {
                return new WP_Error('archive_removed_failed', 'Gagal mengarsipkan soal exam yang sudah dipakai attempt.');
            }
        }

        if (!empty($delete_ids)) {
            $delete_placeholders = implode(',', array_fill(0, count($delete_ids), '%d'));
            $deleted_removed = $wpdb->query(
                $wpdb->prepare(
                    "DELETE FROM {$question_table}
                     WHERE exam_id = %d
                       AND id IN ({$delete_placeholders})",
                    $exam_id,
                    ...$delete_ids
                )
            );
            if ($deleted_removed === false) {
                return new WP_Error('delete_removed_failed', 'Gagal menghapus soal exam yang sudah tidak dipakai.');
            }
        }

        return true;
    }

    /**
     * @param array<int,int> $question_ids
     * @return int[]
     */
    private static function find_historical_question_ids(int $exam_id, array $question_ids): array
    {
        global $wpdb;

        $answer_table = $wpdb->prefix . 'cbt_answers';
        $attempt_table = $wpdb->prefix . 'cbt_attempts';
        $question_ids = array_values(array_unique(array_filter(array_map('absint', $question_ids))));
        if ($exam_id <= 0 || empty($question_ids)) {
            return [];
        }

        $protected = [];
        $placeholders = implode(',', array_fill(0, count($question_ids), '%d'));
        $answered_question_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT DISTINCT question_id
                 FROM {$answer_table}
                 WHERE question_id IN ({$placeholders})",
                ...$question_ids
            )
        );
        foreach ((array) $answered_question_ids as $answered_question_id) {
            $answered_question_id = (int) $answered_question_id;
            if ($answered_question_id > 0) {
                $protected[$answered_question_id] = $answered_question_id;
            }
        }

        $attempt_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT question_order
                 FROM {$attempt_table}
                 WHERE exam_id = %d
                   AND question_order IS NOT NULL
                   AND question_order <> ''",
                $exam_id
            ),
            ARRAY_A
        );
        $candidate_lookup = array_fill_keys($question_ids, true);
        foreach ((array) $attempt_rows as $attempt_row) {
            $decoded = json_decode((string) ($attempt_row['question_order'] ?? ''), true);
            if (!is_array($decoded)) {
                continue;
            }

            foreach ($decoded as $candidate_question_id) {
                $candidate_question_id = (int) $candidate_question_id;
                if ($candidate_question_id > 0 && isset($candidate_lookup[$candidate_question_id])) {
                    $protected[$candidate_question_id] = $candidate_question_id;
                }
            }
        }

        return array_values($protected);
    }

    /**
     * @param array<int,array<string,mixed>> $desired_options
     * @param array<int,array<string,mixed>> $existing_options
     * @return array<int,int>
     */
    private static function sync_question_options_from_snapshot(int $question_id, array $desired_options, array $existing_options = []): array
    {
        global $wpdb;

        $option_table = $wpdb->prefix . 'cbt_options';
        if ($question_id <= 0) {
            return [];
        }

        if (empty($existing_options)) {
            $existing_options = $wpdb->get_results(
                $wpdb->prepare(
                    "SELECT id, option_key, option_text, is_correct
                     FROM {$option_table}
                     WHERE question_id = %d
                     ORDER BY id ASC",
                    $question_id
                ),
                ARRAY_A
            );
        }

        $normalized_existing = self::normalize_question_sync_options((array) $existing_options);
        $normalized_desired = self::normalize_question_sync_options($desired_options);

        $existing_ids_by_match_key = [];
        foreach ($normalized_existing as $existing_option) {
            $existing_id = (int) ($existing_option['id'] ?? 0);
            $match_key = (string) ($existing_option['match_key'] ?? '');
            if ($existing_id <= 0 || $match_key === '') {
                continue;
            }

            $existing_ids_by_match_key[$match_key] = $existing_id;
        }

        $new_ids_by_match_key = [];
        $used_existing_ids = [];
        $now = current_time('mysql');

        foreach ($normalized_desired as $desired_option) {
            $match_key = (string) ($desired_option['match_key'] ?? '');
            $existing_id = $match_key !== '' && isset($existing_ids_by_match_key[$match_key])
                ? (int) $existing_ids_by_match_key[$match_key]
                : 0;

            if ($existing_id > 0) {
                $wpdb->update(
                    $option_table,
                    [
                        'option_key' => (string) ($desired_option['option_key'] ?? ''),
                        'option_text' => (string) ($desired_option['option_text'] ?? ''),
                        'is_correct' => (int) ($desired_option['is_correct'] ?? 0),
                    ],
                    ['id' => $existing_id],
                    ['%s', '%s', '%d'],
                    ['%d']
                );
                $used_existing_ids[$existing_id] = true;
                $new_ids_by_match_key[$match_key] = $existing_id;
                continue;
            }

            $inserted = $wpdb->insert(
                $option_table,
                [
                    'question_id' => $question_id,
                    'option_key' => (string) ($desired_option['option_key'] ?? ''),
                    'option_text' => (string) ($desired_option['option_text'] ?? ''),
                    'is_correct' => (int) ($desired_option['is_correct'] ?? 0),
                    'created_at' => $now,
                ],
                ['%d', '%s', '%s', '%d', '%s']
            );
            if (!$inserted) {
                continue;
            }

            $new_option_id = (int) $wpdb->insert_id;
            if ($new_option_id > 0) {
                $used_existing_ids[$new_option_id] = true;
                $new_ids_by_match_key[$match_key] = $new_option_id;
            }
        }

        foreach ($normalized_existing as $existing_option) {
            $existing_id = (int) ($existing_option['id'] ?? 0);
            if ($existing_id <= 0 || isset($used_existing_ids[$existing_id])) {
                continue;
            }
            $wpdb->delete($option_table, ['id' => $existing_id], ['%d']);
        }

        $old_to_new = [];
        foreach ($existing_ids_by_match_key as $match_key => $old_option_id) {
            $new_option_id = (int) ($new_ids_by_match_key[$match_key] ?? 0);
            if ($old_option_id > 0 && $new_option_id > 0) {
                $old_to_new[$old_option_id] = $new_option_id;
            }
        }

        return $old_to_new;
    }

    private static function question_type_uses_choice_options(string $question_type): bool
    {
        return in_array($question_type, ['multiple_choice', 'multiple_answer', 'true_false'], true);
    }

    /**
     * @param array<int,int> $option_id_map
     */
    private static function remap_question_answer_option_ids(int $question_id, array $option_id_map): void
    {
        global $wpdb;

        if ($question_id <= 0) {
            return;
        }

        $answer_table = $wpdb->prefix . 'cbt_answers';
        $answer_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, attempt_id, selected_option_ids
                 FROM {$answer_table}
                 WHERE question_id = %d
                   AND selected_option_ids IS NOT NULL
                   AND selected_option_ids <> ''",
                $question_id
            ),
            ARRAY_A
        );

        $affected_attempt_ids = [];
        foreach ((array) $answer_rows as $answer_row) {
            $answer_id = (int) ($answer_row['id'] ?? 0);
            if ($answer_id <= 0) {
                continue;
            }

            $existing_option_ids = json_decode((string) ($answer_row['selected_option_ids'] ?? ''), true);
            if (!is_array($existing_option_ids)) {
                $existing_option_ids = [];
            }
            $existing_option_ids = array_values(array_unique(array_filter(array_map('intval', $existing_option_ids), static function (int $option_id): bool {
                return $option_id > 0;
            })));
            sort($existing_option_ids);

            $remapped_option_ids = [];
            foreach ($existing_option_ids as $existing_option_id) {
                $existing_option_id = (int) $existing_option_id;
                $new_option_id = isset($option_id_map[$existing_option_id]) ? (int) $option_id_map[$existing_option_id] : 0;
                if ($new_option_id > 0) {
                    $remapped_option_ids[] = $new_option_id;
                }
            }

            $remapped_option_ids = array_values(array_unique($remapped_option_ids));
            sort($remapped_option_ids);
            if ($remapped_option_ids === $existing_option_ids) {
                continue;
            }
            $selected_option_ids = !empty($remapped_option_ids) ? wp_json_encode($remapped_option_ids) : null;

            $wpdb->update(
                $answer_table,
                [
                    'selected_option_ids' => $selected_option_ids,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $answer_id],
                ['%s', '%s'],
                ['%d']
            );
            $attempt_id = (int) ($answer_row['attempt_id'] ?? 0);
            if ($attempt_id > 0) {
                $affected_attempt_ids[$attempt_id] = $attempt_id;
            }
        }

        if (!empty($affected_attempt_ids)) {
            CBT_Cache::invalidate_attempts(array_values($affected_attempt_ids));
        }
    }

    private static function clear_question_answer_records(int $question_id, bool $clear_answer_text): void
    {
        global $wpdb;

        if ($question_id <= 0) {
            return;
        }

        $answer_table = $wpdb->prefix . 'cbt_answers';
        $affected_attempt_ids = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT DISTINCT attempt_id
                 FROM {$answer_table}
                 WHERE question_id = %d",
                $question_id
            )
        );
        $fields = [
            'selected_option_ids' => null,
            'is_correct' => null,
            'score_awarded' => 0,
            'updated_at' => current_time('mysql'),
        ];
        $formats = ['%s', '%d', '%f', '%s'];

        if ($clear_answer_text) {
            $fields['answer_text'] = null;
            array_splice($formats, 1, 0, ['%s']);
        }

        $wpdb->update(
            $answer_table,
            $fields,
            ['question_id' => $question_id],
            $formats,
            ['%d']
        );

        if (!empty($affected_attempt_ids)) {
            CBT_Cache::invalidate_attempts(array_map('intval', (array) $affected_attempt_ids));
        }
    }

    private static function redirect_exam_with_error(string $message, int $edit_id = 0): void
    {
        $args = self::add_exam_list_state_args([
            'page' => 'cbt-exams',
            'cbt_err' => $message,
        ], self::get_exam_list_state_from_request($_POST));
        if ($edit_id > 0) {
            $args['edit'] = $edit_id;
        }
        wp_safe_redirect(add_query_arg($args, admin_url('admin.php')));
        exit;
    }

    private static function redirect_maintenance_page(?string $message = null, ?string $error = null, ?string $tab = null): void
    {
        $args = ['page' => 'cbt-maintenance'];
        if ($tab === null || $tab === '') {
            $requested_tab = isset($_REQUEST['cbt_maintenance_tab'])
                ? sanitize_key((string) wp_unslash($_REQUEST['cbt_maintenance_tab']))
                : '';
            if (in_array($requested_tab, ['reset', 'seed', 'load'], true)) {
                $tab = $requested_tab;
            }
        }
        if ($tab !== null && $tab !== '' && in_array($tab, ['reset', 'seed', 'load'], true)) {
            $args['cbt_maintenance_tab'] = $tab;
        }
        if ($message !== null && $message !== '') {
            $args['cbt_msg'] = $message;
        }
        if ($error !== null && $error !== '') {
            $args['cbt_err'] = $error;
        }

        wp_safe_redirect(add_query_arg($args, admin_url('admin.php')));
        exit;
    }

    private static function get_reset_progress_state_key(string $token): string
    {
        return 'cbt_reset_progress_' . $token;
    }

    private static function get_reset_progress_users_key(string $token): string
    {
        return 'cbt_reset_progress_users_' . $token;
    }

    private static function clear_reset_progress_transients(string $token): void
    {
        delete_transient(self::get_reset_progress_state_key($token));
        delete_transient(self::get_reset_progress_users_key($token));
    }

    private static function get_reset_progress_state_for_current_user(string $token): ?array
    {
        if ($token === '') {
            return null;
        }

        $state = get_transient(self::get_reset_progress_state_key($token));
        if (!is_array($state)) {
            return null;
        }

        $state_user_id = isset($state['user_id']) ? (int) $state['user_id'] : 0;
        if ($state_user_id <= 0 || $state_user_id !== get_current_user_id()) {
            return null;
        }

        return $state;
    }

    private static function get_reset_progress_table_batch_size(): int
    {
        $batch_size = (int) apply_filters('cbt_reset_progress_table_batch_size', 2);
        if ($batch_size < 1) {
            return 1;
        }
        if ($batch_size > 10) {
            return 10;
        }

        return $batch_size;
    }

    private static function get_reset_progress_user_batch_size(): int
    {
        $batch_size = (int) apply_filters('cbt_reset_progress_user_batch_size', 140);
        if ($batch_size < 20) {
            return 20;
        }
        if ($batch_size > 500) {
            return 500;
        }

        return $batch_size;
    }

    private static function get_reset_progress_max_batch_seconds(): float
    {
        $seconds = (float) apply_filters('cbt_reset_progress_batch_max_seconds', 8.0);
        if ($seconds < 2.0) {
            return 2.0;
        }
        if ($seconds > 25.0) {
            return 25.0;
        }

        return $seconds;
    }

