                'subjects' => 10,
                'exams' => 30,
                'questions' => 900,
                'students' => 300,
                'teachers' => 18,
                'classes' => 12,
                'rooms' => 6,
                'include_true_false_matrix' => true,
            ],
            'large' => [
                'label' => 'Large',
                'subjects' => 20,
                'exams' => 80,
                'questions' => 3200,
                'students' => 1200,
