    /**
     * @param array<string,mixed> $raw
     * @return array{label:string,subjects:int,exams:int,questions:int,students:int,teachers:int,classes:int,rooms:int,include_true_false_matrix:bool}
     */
    private static function normalize_test_data_seed_preset(array $raw): array
    {
        $defaults = self::test_data_seed_presets()['small'];

        return [
            'label' => isset($raw['label']) ? sanitize_text_field((string) $raw['label']) : (string) $defaults['label'],
            'subjects' => max(0, isset($raw['subjects']) ? (int) $raw['subjects'] : (int) $defaults['subjects']),
            'exams' => max(0, isset($raw['exams']) ? (int) $raw['exams'] : (int) $defaults['exams']),
            'questions' => max(0, isset($raw['questions']) ? (int) $raw['questions'] : (int) $defaults['questions']),
            'students' => max(0, isset($raw['students']) ? (int) $raw['students'] : (int) $defaults['students']),
            'teachers' => max(0, isset($raw['teachers']) ? (int) $raw['teachers'] : (int) $defaults['teachers']),
            'classes' => max(0, isset($raw['classes']) ? (int) $raw['classes'] : (int) $defaults['classes']),
            'rooms' => max(0, isset($raw['rooms']) ? (int) $raw['rooms'] : (int) $defaults['rooms']),
            'include_true_false_matrix' => !empty($raw['include_true_false_matrix']),
        ];
    }

    /**
     * @return array<string,string>
     */
    private static function get_test_data_seed_question_type_labels(): array
    {
        return [
            'multiple_choice' => 'Multiple Choice',
            'multiple_answer' => 'Multiple Answer',
            'true_false' => 'True/False',
            'true_false_matrix' => 'True/False Matrix',
            'short_answer' => 'Short Answer',
            'essay' => 'Essay',
        ];
    }

    /**
     * @return array<string,int>
     */
    private static function get_test_data_seed_question_type_counts(string $preset_key, int $total_questions): array
    {
        $counts = [];
        $cycle = self::test_data_seed_question_type_cycle($preset_key);
        $total_questions = max(0, $total_questions);
        if ($total_questions <= 0 || empty($cycle)) {
            return $counts;
        }

        $cycle_size = count($cycle);
        for ($index = 0; $index < $total_questions; $index++) {
            $question_type = (string) $cycle[$index % $cycle_size];
            if ($question_type === '') {
                continue;
            }
            if (!isset($counts[$question_type])) {
                $counts[$question_type] = 0;
            }
            $counts[$question_type] += 1;
        }

        return $counts;
    }

    /**
     * @param array<string,int> $question_type_counts
     */
    private static function format_test_data_seed_question_type_summary(
        array $question_type_counts,
        string $prefix = 'Tipe soal yang dibuat: ',
        int $max_items = 0
    ): string
    {
        $labels = self::get_test_data_seed_question_type_labels();
        $parts = [];
        foreach ($question_type_counts as $question_type => $question_count) {
            $count = (int) $question_count;
            if ($count <= 0) {
                continue;
            }

            $label = isset($labels[$question_type])
                ? (string) $labels[$question_type]
                : ucwords(str_replace('_', ' ', (string) $question_type));
            $parts[] = $label . ' ' . number_format_i18n($count);
            if ($max_items > 0 && count($parts) >= $max_items) {
                break;
            }
        }

        if (empty($parts)) {
            return 'Belum ada soal yang akan dibuat dari preset ini.';
        }

        return $prefix . implode(', ', $parts) . '.';
    }

    private static function describe_test_data_seed_phase_progress(array $state): string
    {
        $phase = sanitize_key((string) ($state['phase'] ?? 'reset_tables'));
        $preset = self::normalize_test_data_seed_preset((array) ($state['preset'] ?? []));

        switch ($phase) {
            case 'reset_tables':
                $tables = isset($state['tables']) && is_array($state['tables']) ? array_values((array) $state['tables']) : [];
                $table_total = count($tables);
                $table_index = max(0, min($table_total, (int) ($state['table_index'] ?? 0)));
                if ($table_total <= 0) {
                    return 'Menyiapkan reset tabel CBT.';
                }
                if ($table_index >= $table_total) {
                    return 'Semua tabel CBT sudah selesai dikosongkan.';
                }

                return sprintf(
                    'Reset tabel %s dari %s. Berikutnya: %s.',
                    number_format_i18n($table_index + 1),
                    number_format_i18n($table_total),
                    self::format_test_data_seed_table_label((string) $tables[$table_index])
                );

            case 'reset_users':
                $user_total = max(0, (int) ($state['reset_user_total'] ?? 0));
                $user_offset = max(0, min($user_total, (int) ($state['reset_user_offset'] ?? 0)));
                if ($user_total <= 0) {
                    return 'Tidak ada user lama yang perlu dihapus.';
                }

                return sprintf(
                    'User lama terhapus %s dari %s.',
                    number_format_i18n($user_offset),
                    number_format_i18n($user_total)
                );

            case 'seed_subjects':
                $subject_total = max(0, (int) ($preset['subjects'] ?? 0));
                $subject_offset = max(0, min($subject_total, (int) ($state['seed_subject_offset'] ?? 0)));
                $subject_created_count = max(0, (int) ($state['seed_subject_created_count'] ?? 0));
                $subject_updated_count = max(0, (int) ($state['seed_subject_updated_count'] ?? 0));

                return sprintf(
                    'Subject tersinkron %s dari %s. Baru %s, update %s.',
                    number_format_i18n($subject_offset),
                    number_format_i18n($subject_total),
                    number_format_i18n($subject_created_count),
                    number_format_i18n($subject_updated_count)
                );

            case 'seed_users':
                $teacher_total = max(0, (int) ($preset['teachers'] ?? 0));
                $student_total = max(0, (int) ($preset['students'] ?? 0));
                $user_total = $teacher_total + $student_total;
                $user_offset = max(0, min($user_total, (int) ($state['seed_user_offset'] ?? 0)));
                $teacher_processed = max(0, min($teacher_total, (int) ($state['seed_teacher_processed'] ?? 0)));
                $student_processed = max(0, min($student_total, (int) ($state['seed_student_processed'] ?? 0)));

                return sprintf(
                    'User tersinkron %s dari %s. Guru %s/%s, siswa %s/%s.',
                    number_format_i18n($user_offset),
                    number_format_i18n($user_total),
                    number_format_i18n($teacher_processed),
                    number_format_i18n($teacher_total),
                    number_format_i18n($student_processed),
                    number_format_i18n($student_total)
                );

            case 'seed_exams':
                $exam_total = max(0, (int) ($preset['exams'] ?? 0));
                $exam_offset = max(0, min($exam_total, (int) ($state['seed_exam_offset'] ?? 0)));
                $exam_created_count = max(0, (int) ($state['seed_exam_created_count'] ?? 0));
                $exam_updated_count = max(0, (int) ($state['seed_exam_updated_count'] ?? 0));

                return sprintf(
                    'Exam tersinkron %s dari %s. Baru %s, update %s.',
                    number_format_i18n($exam_offset),
                    number_format_i18n($exam_total),
                    number_format_i18n($exam_created_count),
                    number_format_i18n($exam_updated_count)
                );

            case 'seed_questions':
                $question_total = max(0, (int) ($preset['questions'] ?? 0));
                $question_offset = max(0, min($question_total, (int) ($state['seed_question_offset'] ?? 0)));
                $question_type_counts = isset($state['question_type_counts']) && is_array($state['question_type_counts'])
                    ? (array) $state['question_type_counts']
                    : [];
                $detail = sprintf(
                    'Soal dibuat %s dari %s.',
                    number_format_i18n($question_offset),
                    number_format_i18n($question_total)
                );
                if (!empty($question_type_counts)) {
                    $detail .= ' ' . self::format_test_data_seed_question_type_summary($question_type_counts, 'Distribusi sementara: ', 3);
                }

                return $detail;

            case 'finalize':
                return 'Merapikan hasil akhir, reset token global, dan membersihkan cache CBT.';

            default:
                return 'Generator sedang memproses dataset uji.';
        }
    }

    private static function format_test_data_seed_table_label(string $table_name): string
    {
        global $wpdb;

        $clean = str_replace('`', '', sanitize_text_field($table_name));
        if ($clean === '') {
            return 'Tabel CBT';
        }

        $prefix = isset($wpdb->prefix) ? (string) $wpdb->prefix : '';
        if ($prefix !== '' && strpos($clean, $prefix) === 0) {
            $clean = substr($clean, strlen($prefix));
        }
        if (strpos($clean, 'cbt_') === 0) {
            $clean = substr($clean, 4);
        }

        $clean = trim(str_replace('_', ' ', $clean));

        return $clean !== '' ? ucwords($clean) : 'Tabel CBT';
    }

    /**
     * @return array{preset:string,subjects:int,exams:int,questions:int,teachers:int,students:int,default_password:string,special_username:string,special_password:string,extra_note:string}|null
     */
    private static function parse_test_data_seed_completion_notice(string $message): ?array
    {
        $message = trim($message);
        if ($message === '') {
            return null;
        }

        $matched = preg_match(
            '/^Dataset uji preset\s+(.+?)\s+selesai\.\s+Subject:\s*(\d+),\s*Exam:\s*(\d+),\s*Question:\s*(\d+),\s*Guru:\s*(\d+),\s*Siswa:\s*(\d+)\.\s+Password default:\s*([^\.]+)\.\s+Akun test khusus:\s*([^\s\/]+)\s*\/\s*([^\.\s]+)\.\s*(.*)$/i',
            $message,
            $matches
        );
        if ($matched !== 1) {
            $matched = preg_match(
                '/^Dataset uji preset\s+(.+?)\s+selesai\.\s+Subject:\s*(\d+),\s*Exam:\s*(\d+),\s*Question:\s*(\d+),\s*Guru:\s*(\d+),\s*Siswa:\s*(\d+)\.\s+Password default:\s*([^\.]+)\.\s+Akun test khusus:\s*([^\s\/]+)\s*\/\s*([^\.\s]+)\.$/i',
                $message,
                $matches
            );
            if ($matched !== 1) {
                return null;
            }
            $matches[10] = '';
        }

        return [
            'preset' => sanitize_text_field((string) ($matches[1] ?? '')),
            'subjects' => max(0, (int) ($matches[2] ?? 0)),
            'exams' => max(0, (int) ($matches[3] ?? 0)),
            'questions' => max(0, (int) ($matches[4] ?? 0)),
            'teachers' => max(0, (int) ($matches[5] ?? 0)),
            'students' => max(0, (int) ($matches[6] ?? 0)),
            'default_password' => sanitize_text_field((string) ($matches[7] ?? '')),
            'special_username' => sanitize_user((string) ($matches[8] ?? ''), true),
            'special_password' => sanitize_text_field((string) ($matches[9] ?? '')),
            'extra_note' => isset($matches[10])
                ? sanitize_text_field((string) $matches[10])
                : '',
        ];
    }

    /**
     * @return array<string,string>
     */
    private static function get_test_data_seed_phase_labels(): array
    {
        return [
            'reset_tables' => 'Mengosongkan tabel CBT',
            'reset_users' => 'Menghapus user CBT',
            'seed_subjects' => 'Membuat subject uji',
            'seed_users' => 'Membuat user guru dan siswa',
            'seed_exams' => 'Membuat exam uji',
            'seed_questions' => 'Membuat bank soal uji',
            'finalize' => 'Finalisasi dataset uji',
        ];
    }

    private static function get_test_data_seed_batch_size(string $phase): int
    {
        switch ($phase) {
            case 'subjects':
                $batch_size = (int) apply_filters('cbt_test_data_seed_subject_batch_size', 12);
                if ($batch_size < 2) {
                    return 2;
                }
                if ($batch_size > 40) {
                    return 40;
                }
                return $batch_size;

            case 'users':
                $batch_size = (int) apply_filters('cbt_test_data_seed_user_batch_size', 160);
                if ($batch_size < 20) {
                    return 20;
                }
                if ($batch_size > 300) {
                    return 300;
                }
                return $batch_size;

            case 'exams':
                $batch_size = (int) apply_filters('cbt_test_data_seed_exam_batch_size', 14);
                if ($batch_size < 2) {
                    return 2;
                }
                if ($batch_size > 40) {
                    return 40;
                }
                return $batch_size;

            case 'questions':
            default:
                $batch_size = (int) apply_filters('cbt_test_data_seed_question_batch_size', 120);
                if ($batch_size < 20) {
                    return 20;
                }
                if ($batch_size > 250) {
                    return 250;
                }
                return $batch_size;
        }
    }

    private static function get_test_data_seed_max_batch_seconds(): float
    {
        $seconds = (float) apply_filters('cbt_test_data_seed_batch_max_seconds', 8.0);
        if ($seconds < 2.0) {
            return 2.0;
        }
        if ($seconds > 25.0) {
            return 25.0;
        }

        return $seconds;
    }

    /**
     * @return string[]
     */
    private static function build_test_data_seed_codes(string $prefix, int $count): array
    {
        $codes = [];
        if ($count <= 0) {
            return $codes;
        }

        $digits = max(2, strlen((string) $count));
        for ($number = 1; $number <= $count; $number++) {
            $codes[] = $prefix . str_pad((string) $number, $digits, '0', STR_PAD_LEFT);
        }

        return $codes;
    }

    /**
     * @return array{name:string,code:string,description:string}
     */
    private static function build_test_data_seed_subject_entry(int $offset): array
    {
        $number = $offset + 1;
        $label = str_pad((string) $number, 2, '0', STR_PAD_LEFT);

        return [
            'name' => 'TEST Subject ' . $label,
            'code' => 'TST' . $label,
            'description' => 'Dataset uji otomatis untuk subject ' . $label . '.',
        ];
    }

    /**
     * @param array{name:string,code:string,description:string} $entry
     * @return array{id:int,status:string,name:string,code:string}
     */
    private static function upsert_test_data_seed_subject(array $entry): array
    {
        global $wpdb;

        $table = $wpdb->prefix . 'cbt_subjects';
        $name = sanitize_text_field((string) ($entry['name'] ?? ''));
        $code = strtoupper(sanitize_key((string) ($entry['code'] ?? '')));
        $description = sanitize_textarea_field((string) ($entry['description'] ?? ''));
        if ($name === '' || $code === '') {
            return [
                'id' => 0,
                'status' => 'failed',
                'name' => $name,
                'code' => $code,
            ];
        }

        $existing_id = (int) $wpdb->get_var(
            $wpdb->prepare("SELECT id FROM {$table} WHERE code = %s ORDER BY id ASC LIMIT 1", $code)
        );

        if ($existing_id > 0) {
            $updated = $wpdb->update(
                $table,
                [
                    'name' => $name,
                    'code' => $code,
                    'description' => $description,
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $existing_id],
                ['%s', '%s', '%s', '%s'],
                ['%d']
            );

            return [
                'id' => $updated === false ? 0 : $existing_id,
                'status' => $updated === false ? 'failed' : 'updated',
                'name' => $name,
                'code' => $code,
            ];
        }

        $inserted = $wpdb->insert(
            $table,
            [
                'name' => $name,
                'code' => $code,
                'description' => $description,
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ],
            ['%s', '%s', '%s', '%s', '%s']
        );

        return [
            'id' => $inserted ? (int) $wpdb->insert_id : 0,
            'status' => $inserted ? 'created' : 'failed',
            'name' => $name,
            'code' => $code,
        ];
    }

    /**
     * @param array{label:string,subjects:int,exams:int,questions:int,students:int,teachers:int,classes:int,rooms:int,include_true_false_matrix:bool} $preset
     * @param string[] $kelas_codes
     * @param string[] $ruang_codes
     * @return array<int,array<string,string>>
     */
    private static function build_test_data_seed_user_rows(array $preset, int $offset, int $limit, array $kelas_codes, array $ruang_codes): array
    {
        $rows = [];
        $teacher_total = max(0, (int) ($preset['teachers'] ?? 0));
        $student_total = max(0, (int) ($preset['students'] ?? 0));
        $total = $teacher_total + $student_total;
        $agama_options = self::get_supported_agama_options();
        if ($limit <= 0 || $offset >= $total) {
            return $rows;
        }

        $end = min($offset + $limit, $total);
        for ($index = $offset; $index < $end; $index++) {
            $agama = !empty($agama_options)
                ? (string) $agama_options[$index % count($agama_options)]
                : '';

            if ($index < $teacher_total) {
                $number = $index + 1;
                $username = sprintf('test_guru_%04d', $number);
                $rows[] = [
                    'name' => sprintf('Guru Test %03d', $number),
                    'email' => $username . '@example.local',
                    'username' => $username,
                    'password' => self::TEST_DATA_SEED_DEFAULT_PASSWORD,
                    'role' => 'guru',
                    'kode_kelas' => '',
                    'kode_ruang' => !empty($ruang_codes) ? (string) $ruang_codes[($number - 1) % count($ruang_codes)] : '',
                    'agama' => $agama,
                    'foto' => '',
                    '__seed_kind' => 'teacher',
                ];
                continue;
            }

            $number = ($index - $teacher_total) + 1;
            if ($number === 1) {
                $rows[] = self::build_test_data_seed_special_student_row($kelas_codes, $ruang_codes, $agama_options);
                continue;
            }

            $username = sprintf('test_siswa_%04d', $number);
            $rows[] = [
                'name' => sprintf('Siswa Test %04d', $number),
                'email' => $username . '@example.local',
                'nisn' => sprintf('88%08d', $number),
                'username' => $username,
                'password' => self::TEST_DATA_SEED_DEFAULT_PASSWORD,
                'role' => 'siswa',
                'kode_kelas' => !empty($kelas_codes) ? (string) $kelas_codes[($number - 1) % count($kelas_codes)] : '',
                'kode_ruang' => !empty($ruang_codes) ? (string) $ruang_codes[($number - 1) % count($ruang_codes)] : '',
                'agama' => $agama,
                'foto' => '',
                '__seed_kind' => 'student',
            ];
        }

        return $rows;
    }

    /**
     * @param string[] $kelas_codes
     * @param string[] $ruang_codes
     * @param string[] $agama_options
     * @return array<string,string>
     */
    private static function get_test_data_seed_special_student_kelas_code(array $kelas_codes): string
    {
        return !empty($kelas_codes) ? sanitize_text_field((string) $kelas_codes[0]) : '';
    }

    /**
     * @param string[] $kelas_codes
     * @param string[] $ruang_codes
     * @param string[] $agama_options
     * @return array<string,string>
     */
    private static function build_test_data_seed_special_student_row(array $kelas_codes, array $ruang_codes, array $agama_options): array
    {
        $agama = in_array('Islam', $agama_options, true)
            ? 'Islam'
            : (!empty($agama_options) ? (string) reset($agama_options) : '');
        $special_kelas = self::get_test_data_seed_special_student_kelas_code($kelas_codes);

        return [
            'name' => strtoupper(self::TEST_DATA_SEED_SPECIAL_USERNAME),
            'email' => self::TEST_DATA_SEED_SPECIAL_USERNAME . '@example.local',
            'nisn' => '8899000001',
            'username' => self::TEST_DATA_SEED_SPECIAL_USERNAME,
            'password' => self::TEST_DATA_SEED_SPECIAL_PASSWORD,
            'role' => 'siswa',
            'kode_kelas' => $special_kelas,
            'kode_ruang' => !empty($ruang_codes) ? (string) $ruang_codes[0] : '',
            'agama' => $agama,
            'foto' => '',
            '__seed_kind' => 'student',
        ];
    }

    /**
     * @param array<int,array<string,mixed>> $subjects
     * @param string[] $kelas_codes
     * @return array<string,mixed>
     */
    private static function build_test_data_seed_exam_entry(
        int $offset,
        array $subjects,
        array $kelas_codes,
        string $preset_key,
        int $creator_id
    ): array {
        $subject_total = count($subjects);
        $subject_entry = $subject_total > 0
            ? (array) $subjects[$offset % $subject_total]
            : [];
        $subject_id = (int) ($subject_entry['id'] ?? 0);
        $subject_name = (string) ($subject_entry['name'] ?? 'TEST Subject');
        $exam_number = $offset + 1;

        $target_kelas = [];
        $kelas_total = count($kelas_codes);
        if ($kelas_total > 0) {
            $span = min($kelas_total, (($offset % 3) + 1));
            $start = $offset % $kelas_total;
            for ($idx = 0; $idx < $span; $idx++) {
                $target_kelas[] = (string) $kelas_codes[($start + $idx) % $kelas_total];
            }
            $target_kelas = array_values(array_unique($target_kelas));
        }
        $special_test_kelas = self::get_test_data_seed_special_student_kelas_code($kelas_codes);
        if ($special_test_kelas !== '') {
            array_unshift($target_kelas, $special_test_kelas);
            $target_kelas = array_values(array_unique($target_kelas));
        }

        $status_slot = $offset % 10;
        if ($status_slot < 5) {
            $status = 'published';
        } elseif ($status_slot < 8) {
            $status = 'draft';
        } else {
            $status = 'closed';
        }

        $schedule = self::build_test_data_seed_exam_schedule($status, $offset);
        $duration_cycle = [45, 60, 75, 90, 120];
        $duration = $duration_cycle[$offset % count($duration_cycle)];

        return [
            'subject_id' => $subject_id,
            'subject_name' => $subject_name,
            'title' => sprintf('TEST Exam %03d - %s', $exam_number, $subject_name),
            'description' => sprintf(
                'Dataset uji otomatis preset %s untuk %s. Target kelas: %s.',
                ucfirst($preset_key),
                $subject_name,
                !empty($target_kelas) ? implode(', ', $target_kelas) : 'Semua kelas test'
            ),
            'target_kelas' => implode(',', $target_kelas),
            'duration_minutes' => $duration,
            'total_questions' => 0,
            'randomize_questions' => ($offset % 2 === 0) ? 1 : 0,
            'status' => $status,
            'starts_at' => $schedule['starts_at'],
            'ends_at' => $schedule['ends_at'],
            'created_by' => $creator_id,
        ];
    }

    /**
     * @return array{starts_at:?string,ends_at:?string}
     */
    private static function build_test_data_seed_exam_schedule(string $status, int $offset): array
    {
        $now = current_time('timestamp', true);
        $timezone = wp_timezone();
        $starts_at = null;
        $ends_at = null;

        if ($status === 'published') {
            $starts_at = wp_date('Y-m-d H:i:s', $now - (($offset % 5) + 1) * HOUR_IN_SECONDS, $timezone);
            $ends_at = wp_date('Y-m-d H:i:s', $now + (($offset % 4) + 2) * DAY_IN_SECONDS, $timezone);
        } elseif ($status === 'closed') {
            $starts_at = wp_date('Y-m-d H:i:s', $now - (($offset % 5) + 2) * DAY_IN_SECONDS, $timezone);
            $ends_at = wp_date('Y-m-d H:i:s', $now - (($offset % 6) + 1) * HOUR_IN_SECONDS, $timezone);
        }

        return [
            'starts_at' => $starts_at,
            'ends_at' => $ends_at,
        ];
    }

    /**
     * @param array<string,mixed> $entry
     * @return array{id:int,status:string,subject_id:int,subject_name:string,title:string,target_kelas:string}
     */
    private static function upsert_test_data_seed_exam(array $entry): array
    {
        global $wpdb;

        $table = $wpdb->prefix . 'cbt_exams';
        $subject_id = (int) ($entry['subject_id'] ?? 0);
        $title = sanitize_text_field((string) ($entry['title'] ?? ''));
        $description = wp_kses_post((string) ($entry['description'] ?? ''));
        $target_kelas = self::normalize_target_kelas_csv((string) ($entry['target_kelas'] ?? ''));
        if ($subject_id <= 0 || $title === '') {
            return [
                'id' => 0,
                'status' => 'failed',
                'subject_id' => $subject_id,
                'subject_name' => sanitize_text_field((string) ($entry['subject_name'] ?? '')),
                'title' => $title,
                'target_kelas' => $target_kelas,
            ];
        }

        $data = [
            'subject_id' => $subject_id,
            'title' => $title,
            'description' => $description,
            'target_kelas' => $target_kelas,
            'duration_minutes' => max(1, (int) ($entry['duration_minutes'] ?? 60)),
            'total_questions' => max(0, (int) ($entry['total_questions'] ?? 0)),
            'randomize_questions' => !empty($entry['randomize_questions']) ? 1 : 0,
            'status' => sanitize_key((string) ($entry['status'] ?? 'draft')),
            'starts_at' => $entry['starts_at'] ?? null,
            'ends_at' => $entry['ends_at'] ?? null,
            'created_by' => max(0, (int) ($entry['created_by'] ?? 0)),
            'updated_at' => current_time('mysql'),
        ];

        $existing_id = (int) $wpdb->get_var(
            $wpdb->prepare(
                "SELECT id FROM {$table} WHERE subject_id = %d AND title = %s ORDER BY id ASC LIMIT 1",
                $subject_id,
                $title
            )
        );

        if ($existing_id > 0) {
            $updated = $wpdb->update(
                $table,
                $data,
                ['id' => $existing_id],
                ['%d', '%s', '%s', '%s', '%d', '%d', '%d', '%s', '%s', '%s', '%d', '%s'],
                ['%d']
            );

            return [
                'id' => $updated === false ? 0 : $existing_id,
                'status' => $updated === false ? 'failed' : 'updated',
                'subject_id' => $subject_id,
                'subject_name' => sanitize_text_field((string) ($entry['subject_name'] ?? '')),
                'title' => $title,
                'target_kelas' => $target_kelas,
            ];
        }

        $data['created_at'] = current_time('mysql');
        $inserted = $wpdb->insert(
            $table,
            $data,
            ['%d', '%s', '%s', '%s', '%d', '%d', '%d', '%s', '%s', '%s', '%d', '%s', '%s']
        );

        return [
            'id' => $inserted ? (int) $wpdb->insert_id : 0,
            'status' => $inserted ? 'created' : 'failed',
            'subject_id' => $subject_id,
            'subject_name' => sanitize_text_field((string) ($entry['subject_name'] ?? '')),
            'title' => $title,
            'target_kelas' => $target_kelas,
        ];
    }

    /**
     * @return string[]
     */
    private static function test_data_seed_question_type_cycle(string $preset_key): array
    {
        if ($preset_key === 'medium' || $preset_key === 'large') {
            return [
                'multiple_choice',
                'multiple_choice',
                'multiple_choice',
                'multiple_choice',
                'multiple_answer',
                'multiple_answer',
                'true_false',
                'true_false_matrix',
                'short_answer',
                'essay',
            ];
        }

        return [
            'multiple_choice',
            'multiple_choice',
            'multiple_choice',
            'multiple_choice',
            'multiple_choice',
            'multiple_answer',
            'multiple_answer',
            'true_false',
            'short_answer',
            'essay',
        ];
    }

    /**
     * @param array<int,array<string,mixed>> $exams
     * @return array<string,mixed>
     */
    private static function build_test_data_seed_question_row(int $offset, array $exams, string $preset_key): array
    {
        $exam_count = count($exams);
        $exam_entry = $exam_count > 0 ? (array) $exams[$offset % $exam_count] : [];
        $exam_id = (int) ($exam_entry['id'] ?? 0);
        $subject_name = sanitize_text_field((string) ($exam_entry['subject_name'] ?? 'TEST Subject'));
        $question_number = $offset + 1;
        $cycle = self::test_data_seed_question_type_cycle($preset_key);
        $exam_question_index = $exam_count > 0 ? intdiv($offset, $exam_count) : $offset;
        $question_type = (string) $cycle[$exam_question_index % max(1, count($cycle))];

        switch ($question_type) {
            case 'multiple_answer':
                $base = ($question_number % 12) + 2;
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'multiple_answer',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Pilih semua kelipatan dari %d.',
                        $question_number,
                        $subject_name,
                        $base
                    ),
                    'points' => 1.50,
                    'options' => implode('||', [
                        (string) ($base * 2),
                        (string) (($base * 2) + 1),
                        (string) ($base * 3),
                        (string) (($base * 3) + 1),
                    ]),
                    'correct_answer' => 'A,C',
                    'correct_text' => '',
                    'explanation' => 'Kelipatan yang benar adalah dua nilai yang habis dibagi tanpa sisa.',
                ];

            case 'true_false':
                $left = ($question_number % 21) + 9;
                $right = ($question_number % 8) + 3;
                $is_true = ($question_number % 2) === 0;
                $claim = $is_true ? ($left + $right) : ($left + $right + 1);
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'true_false',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Pernyataan: %d + %d = %d.',
                        $question_number,
                        $subject_name,
                        $left,
                        $right,
                        $claim
                    ),
                    'points' => 1.00,
                    'options' => '',
                    'correct_answer' => '',
                    'correct_text' => $is_true ? 'true' : 'false',
                    'explanation' => 'Periksa hasil operasi penjumlahan pada pernyataan tersebut.',
                ];

            case 'true_false_matrix':
                $base = ($question_number % 17) + 6;
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'true_false_matrix',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Tentukan Benar/Salah untuk setiap pernyataan berikut.',
                        $question_number,
                        $subject_name
                    ),
                    'points' => 2.00,
                    'options' => '',
                    'correct_answer' => '',
                    'correct_text' => implode("\n", [
                        'Bilangan ' . $base . ' adalah bilangan positif|true',
                        'Hasil ' . $base . ' + 1 sama dengan ' . $base . '|false',
                        'Hasil ' . $base . ' x 2 sama dengan ' . ($base * 2) . '|true',
                    ]),
                    'explanation' => 'Setiap baris dinilai terpisah sebagai benar atau salah.',
                ];

            case 'short_answer':
                $left = ($question_number % 14) + 6;
                $right = ($question_number % 9) + 4;
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'short_answer',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Isi hasil dari %d x %d pada jawaban singkat.',
                        $question_number,
                        $subject_name,
                        $left,
                        $right
                    ),
                    'points' => 1.25,
                    'options' => '',
                    'correct_answer' => '',
                    'correct_text' => (string) ($left * $right),
                    'explanation' => 'Jawaban singkat harus sama persis dengan hasil perkalian yang benar.',
                ];

            case 'essay':
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'essay',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Jelaskan langkah penyelesaian soal cerita sederhana yang melibatkan konsep %s.',
                        $question_number,
                        $subject_name,
                        strtolower($subject_name)
                    ),
                    'points' => 5.00,
                    'options' => '',
                    'correct_answer' => '',
                    'correct_text' => 'Rubrik: jawaban memuat konsep utama, langkah kerja runtut, dan kesimpulan yang konsisten.',
                    'explanation' => 'Penilaian essay mengikuti rubrik langkah, konsep, dan kesimpulan.',
                ];

            case 'multiple_choice':
            default:
                $left = ($question_number % 37) + 13;
                $right = ($question_number % 10) + 3;
                $correct = $left + $right;
                return [
                    'exam_id' => $exam_id,
                    'question_type' => 'multiple_choice',
                    'question_text' => sprintf(
                        'Soal %03d (%s). Berapakah hasil %d + %d?',
                        $question_number,
                        $subject_name,
                        $left,
                        $right
                    ),
                    'points' => 1.00,
                    'options' => implode('||', [
                        (string) ($correct + 2),
                        (string) $correct,
                        (string) max(1, $correct - 1),
                        (string) ($correct + 4),
                    ]),
                    'correct_answer' => 'B',
                    'correct_text' => '',
                    'explanation' => 'Jawaban benar adalah hasil penjumlahan kedua bilangan.',
                ];
        }
    }

    private static function insert_test_data_seed_question(array $row): string
    {
        global $wpdb;

        $question_type = self::map_import_question_type((string) ($row['question_type'] ?? ''));
        $question_text = trim(wp_kses_post((string) ($row['question_text'] ?? '')));
        $explanation = trim(wp_kses_post((string) ($row['explanation'] ?? '')));
        $exam_id = absint($row['exam_id'] ?? 0);
        if ($question_type === '' || $question_text === '' || $exam_id <= 0) {
            return 'failed';
        }

        $points = isset($row['points']) && $row['points'] !== '' ? (float) $row['points'] : 1.0;
        $points = max(0, $points);
        $options_input = (string) ($row['options'] ?? '');
        $correct_answer = (string) ($row['correct_answer'] ?? '');
        $correct_text = (string) ($row['correct_text'] ?? '');
        $options_raw = '';

        if (in_array($question_type, ['multiple_choice', 'multiple_answer'], true)) {
            $built = self::build_options_raw_from_import($options_input, $correct_answer, $question_type);
            if ($built === '') {
                return 'failed';
            }
            $options_raw = $built;
            $correct_text = '';
        } elseif ($question_type === 'true_false') {
            $normalized = strtolower(trim($correct_answer !== '' ? $correct_answer : $correct_text));
            $correct_text = in_array($normalized, ['false', '0', 'f', 'no', 'tidak'], true) ? 'false' : 'true';
            $options_raw = '';
        } elseif ($question_type === 'true_false_matrix') {
            $correct_text = self::normalize_true_false_matrix_payload((string) ($correct_text !== '' ? $correct_text : $correct_answer));
            if ($correct_text === '' || count(self::normalize_true_false_matrix_config($correct_text)) < 2) {
                return 'failed';
            }
            $options_raw = '';
        } elseif ($question_type === 'short_answer') {
            $correct_text = self::normalize_short_answer_payload((string) ($correct_text !== '' ? $correct_text : $correct_answer));
            if ($correct_text === '') {
                return 'failed';
            }
            $options_raw = '';
        } elseif ($question_type === 'essay') {
            $correct_text = trim($correct_text !== '' ? $correct_text : $correct_answer);
            if ($correct_text === '') {
                return 'failed';
            }
            $options_raw = '';
        }

        $inserted = $wpdb->insert(
            $wpdb->prefix . 'cbt_questions',
            [
                'exam_id' => $exam_id,
                'question_text' => $question_text,
                'question_type' => $question_type,
                'points' => $points,
                'correct_text' => $correct_text !== '' ? $correct_text : null,
                'explanation' => $explanation !== '' ? $explanation : null,
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ],
            ['%d', '%s', '%s', '%f', '%s', '%s', '%s', '%s']
        );
        if (!$inserted) {
            return 'failed';
        }

        $question_id = (int) $wpdb->insert_id;
        $options_to_insert = self::parse_options($options_raw);
        if ($question_type === 'true_false' && empty($options_to_insert)) {
            $true_is_correct = (strtolower($correct_text) === 'true') ? 1 : 0;
            $options_to_insert = [
                ['option_text' => 'True', 'is_correct' => $true_is_correct],
                ['option_text' => 'False', 'is_correct' => $true_is_correct ? 0 : 1],
            ];
        }

        foreach ($options_to_insert as $idx => $opt) {
            $wpdb->insert(
                $wpdb->prefix . 'cbt_options',
                [
                    'question_id' => $question_id,
                    'option_key' => chr(65 + $idx),
                    'option_text' => (string) ($opt['option_text'] ?? ''),
                    'is_correct' => (int) ($opt['is_correct'] ?? 0),
                    'created_at' => current_time('mysql'),
                ],
                ['%d', '%s', '%s', '%d', '%s']
            );
        }

        if ($question_type !== 'true_false_matrix') {
            self::save_question_type_detail($question_id, $question_type, $correct_text);
        }

        return 'created';
    }

    /**
     * @param array<string,mixed> $state
     */
    private static function calculate_test_data_seed_processed_units(array $state): int
    {
        $preset = self::normalize_test_data_seed_preset((array) ($state['preset'] ?? []));
        $table_total = isset($state['tables']) && is_array($state['tables']) ? count((array) $state['tables']) : 0;
        $table_units = min($table_total, max(0, (int) ($state['table_index'] ?? 0)));

        $reset_user_total = max(0, (int) ($state['reset_user_total'] ?? 0));
        $reset_user_offset = max(0, (int) ($state['reset_user_offset'] ?? 0));
        $reset_user_units = $reset_user_total > 0
            ? min($reset_user_offset, $reset_user_total)
            : (!empty($state['reset_users_placeholder_done']) ? 1 : 0);

        $subject_units = min(max(0, (int) ($state['seed_subject_offset'] ?? 0)), (int) ($preset['subjects'] ?? 0));
        $seed_user_total = (int) ($preset['teachers'] ?? 0) + (int) ($preset['students'] ?? 0);
        $seed_user_units = min(max(0, (int) ($state['seed_user_offset'] ?? 0)), $seed_user_total);
        $exam_units = min(max(0, (int) ($state['seed_exam_offset'] ?? 0)), (int) ($preset['exams'] ?? 0));
        $question_units = min(max(0, (int) ($state['seed_question_offset'] ?? 0)), (int) ($preset['questions'] ?? 0));

        $processed = $table_units + $reset_user_units + $subject_units + $seed_user_units + $exam_units + $question_units;
        $max_before_finalize = max(0, (int) ($state['total_units'] ?? 1) - 1);
        if ($processed > $max_before_finalize) {
            $processed = $max_before_finalize;
        }

        return max(0, $processed);
    }

    public static function handle_save_question(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        check_admin_referer('cbt_save_question');

        global $wpdb;

        $question_table = $wpdb->prefix . 'cbt_questions';
        $option_table = $wpdb->prefix . 'cbt_options';
        $exam_table = $wpdb->prefix . 'cbt_exams';
        $is_admin_scope = self::is_admin_scope();
        $current_user_id = get_current_user_id();

        $id = isset($_POST['id']) ? absint($_POST['id']) : 0;
        $exam_id = isset($_POST['exam_id']) ? absint($_POST['exam_id']) : 0;
        $subject_id = isset($_POST['subject_id']) ? absint($_POST['subject_id']) : 0;
        $question_text = isset($_POST['question_text']) ? wp_kses_post(wp_unslash($_POST['question_text'])) : '';
        $question_type = isset($_POST['question_type']) ? sanitize_text_field(wp_unslash($_POST['question_type'])) : 'multiple_choice';
        $points = isset($_POST['points']) ? (float) wp_unslash($_POST['points']) : 1.0;
        $correct_text_raw = isset($_POST['correct_text']) ? (string) wp_unslash($_POST['correct_text']) : '';
        $correct_text = sanitize_text_field($correct_text_raw);
        $essay_answer = isset($_POST['essay_answer']) ? wp_kses_post(wp_unslash($_POST['essay_answer'])) : '';
        $options_raw = isset($_POST['options']) ? wp_unslash($_POST['options']) : '';
        $return_page = self::normalize_question_page_slug(isset($_POST['return_page']) ? wp_unslash($_POST['return_page']) : 'cbt-question-bank');
        $forced_question_type = self::forced_question_type_for_page($return_page);
        $previous_exam_id = 0;
        $previous_question_snapshot = [];

        $allowed_types = ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        if (!in_array($question_type, $allowed_types, true)) {
            $question_type = 'multiple_choice';
        }
        if ($forced_question_type !== '') {
            $question_type = $forced_question_type;
        }

        $normalized_detail_text = '';
        if ($question_type === 'true_false') {
            $normalized_detail_text = self::normalize_true_false_value($correct_text) === 1 ? 'true' : 'false';
        } elseif ($question_type === 'true_false_matrix') {
            $normalized_detail_text = self::normalize_true_false_matrix_payload($correct_text_raw);
        } elseif ($question_type === 'short_answer') {
            $normalized_detail_text = self::normalize_short_answer_payload($correct_text_raw);
        } elseif ($question_type === 'essay') {
            $normalized_detail_text = trim($essay_answer);
        }

        if ($exam_id <= 0 && $subject_id > 0) {
            $exam_id = self::ensure_subject_question_bank_exam($subject_id, $is_admin_scope, $current_user_id);
        }

        if ($exam_id <= 0 || trim($question_text) === '' || $subject_id <= 0) {
            self::redirect_question_import_with_error('Subject dan pertanyaan wajib diisi.', $return_page);
        }

        if ($question_type === 'essay' && $normalized_detail_text === '') {
            self::redirect_question_import_with_error('Jawaban/acuan untuk soal essay wajib diisi.', $return_page);
        }

        if ($question_type === 'short_answer' && $normalized_detail_text === '') {
            self::redirect_question_import_with_error('Short Answer minimal harus punya 1 jawaban valid.', $return_page);
        }

        if ($question_type === 'true_false_matrix') {
            $matrix_rows = self::normalize_true_false_matrix_config($normalized_detail_text);
            if (count($matrix_rows) < 2) {
                self::redirect_question_import_with_error('True/False Matrix minimal harus punya 2 pernyataan.', $return_page);
            }
        }

        if (!$is_admin_scope) {
            $owned_exam = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$exam_table} WHERE id = %d AND created_by = %d",
                $exam_id,
                $current_user_id
            ));
            if ($owned_exam === 0) {
                wp_die('Unauthorized exam for question.');
            }
        }

        $data = [
            'exam_id' => $exam_id,
            'question_text' => $question_text,
            'question_type' => $question_type,
            'points' => $points,
            // Keep legacy field for backward compatibility; source of truth is per-type detail table.
            'correct_text' => $normalized_detail_text !== '' ? $normalized_detail_text : null,
            'updated_at' => current_time('mysql'),
        ];

        if ($id > 0) {
            $previous_question_snapshot = self::get_question_sync_snapshot($id);
            $previous_exam_id = (int) $wpdb->get_var(
                $wpdb->prepare("SELECT exam_id FROM {$question_table} WHERE id = %d", $id)
            );
            if (!$is_admin_scope) {
                $owned_question = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*)
                     FROM {$question_table} q
                     INNER JOIN {$exam_table} e ON e.id = q.exam_id
                     WHERE q.id = %d AND e.created_by = %d",
                    $id,
                    $current_user_id
                ));
                if ($owned_question === 0) {
                    wp_die('Unauthorized question update.');
                }
            }

            $wpdb->update(
                $question_table,
                $data,
                ['id' => $id],
                ['%d', '%s', '%s', '%f', '%s', '%s'],
                ['%d']
            );
            $question_id = $id;
        } else {
            $data['created_at'] = current_time('mysql');

            $wpdb->insert(
                $question_table,
                $data,
                ['%d', '%s', '%s', '%f', '%s', '%s', '%s']
            );
            $question_id = (int) $wpdb->insert_id;
        }

        if ($question_id > 0) {
            $wpdb->delete($option_table, ['question_id' => $question_id], ['%d']);

            $options_to_insert = self::parse_options($options_raw);

            if ($question_type === 'multiple_choice') {
                if (count($options_to_insert) < 2) {
                    self::redirect_question_import_with_error('Multiple Choice minimal harus punya 2 pilihan.', $return_page);
                }
                if (count($options_to_insert) > 5) {
                    self::redirect_question_import_with_error('Multiple Choice maksimal 5 pilihan.', $return_page);
                }

                $correct_count = 0;
                foreach ($options_to_insert as $opt) {
                    if ((int) ($opt['is_correct'] ?? 0) === 1) {
                        $correct_count++;
                    }
                }
                if ($correct_count !== 1) {
                    self::redirect_question_import_with_error('Multiple Choice harus memiliki tepat 1 jawaban benar.', $return_page);
                }
            }

            if ($question_type === 'multiple_answer') {
                if (count($options_to_insert) < 2) {
                    self::redirect_question_import_with_error('Multiple Answer minimal harus punya 2 pilihan.', $return_page);
                }
                if (count($options_to_insert) > 12) {
                    self::redirect_question_import_with_error('Multiple Answer maksimal 12 pilihan.', $return_page);
                }

                $correct_count = 0;
                foreach ($options_to_insert as $opt) {
                    if ((int) ($opt['is_correct'] ?? 0) === 1) {
                        $correct_count++;
                    }
                }
                if ($correct_count < 1) {
                    self::redirect_question_import_with_error('Multiple Answer harus memiliki minimal 1 jawaban benar.', $return_page);
                }
            }

            if ($question_type === 'true_false' && empty($options_to_insert)) {
                $true_is_correct = self::normalize_true_false_value($normalized_detail_text) === 1 ? 1 : 0;
                $options_to_insert = [
                    ['option_text' => 'True', 'is_correct' => $true_is_correct],
                    ['option_text' => 'False', 'is_correct' => $true_is_correct ? 0 : 1],
                ];
            }

            foreach ($options_to_insert as $idx => $opt) {
                $wpdb->insert(
                    $option_table,
                    [
                        'question_id' => $question_id,
                        'option_key' => chr(65 + $idx),
                        'option_text' => $opt['option_text'],
                        'is_correct' => (int) $opt['is_correct'],
                        'created_at' => current_time('mysql'),
                    ],
                    ['%d', '%s', '%s', '%d', '%s']
                );
            }

            self::save_question_type_detail($question_id, $question_type, $normalized_detail_text);
        }

        CBT_Cache::invalidate_catalog();
        $affected_exam_ids = [];
        if ($exam_id > 0) {
            $affected_exam_ids[$exam_id] = $exam_id;
        }
        if ($previous_exam_id > 0 && $previous_exam_id !== $exam_id) {
            $affected_exam_ids[$previous_exam_id] = $previous_exam_id;
        }

        if ($question_id > 0) {
            $current_question_snapshot = self::get_question_sync_snapshot($question_id);
            if (
                !empty($previous_question_snapshot) &&
                self::is_bank_question_snapshot($previous_question_snapshot) &&
                !empty($current_question_snapshot)
            ) {
                foreach (self::propagate_bank_question_update($question_id, $previous_question_snapshot, $current_question_snapshot) as $affected_exam_id) {
                    $affected_exam_id = (int) $affected_exam_id;
                    if ($affected_exam_id > 0) {
                        $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
                    }
                }
            }
        }

        foreach ($affected_exam_ids as $affected_exam_id) {
            CBT_Cache::invalidate_exam((int) $affected_exam_id);
        }

        wp_safe_redirect(add_query_arg(
            [
                'page' => $return_page,
                'cbt_msg' => 'Question saved',
            ],
            admin_url('admin.php')
        ));
        exit;
    }

    public static function handle_delete_question(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        $id = isset($_GET['id']) ? absint($_GET['id']) : 0;
        check_admin_referer('cbt_delete_question_' . $id);
        $return_page = self::normalize_question_page_slug(isset($_GET['return_page']) ? wp_unslash($_GET['return_page']) : 'cbt-question-bank');
        $filter_exam_id = isset($_GET['filter_exam_id']) ? absint($_GET['filter_exam_id']) : 0;
        $filter_type = isset($_GET['filter_type']) ? sanitize_text_field(wp_unslash($_GET['filter_type'])) : '';
        $question_per_page = self::normalize_standard_list_per_page(
            isset($_GET['question_per_page']) ? absint(wp_unslash($_GET['question_per_page'])) : 20
        );
        $question_paged = isset($_GET['question_paged']) ? max(1, absint(wp_unslash($_GET['question_paged']))) : 1;
        $allowed_filter_types = ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        if (!in_array($filter_type, $allowed_filter_types, true)) {
            $filter_type = '';
        }

        if ($id > 0) {
            global $wpdb;
            $affected_exam_id = (int) $wpdb->get_var(
                $wpdb->prepare("SELECT exam_id FROM {$wpdb->prefix}cbt_questions WHERE id = %d", $id)
            );
            if (!self::is_admin_scope()) {
                $owned_question = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*)
                     FROM {$wpdb->prefix}cbt_questions q
                     INNER JOIN {$wpdb->prefix}cbt_exams e ON e.id = q.exam_id
                     WHERE q.id = %d AND e.created_by = %d",
                    $id,
                    get_current_user_id()
                ));
                if ($owned_question === 0) {
                    wp_die('Unauthorized question delete.');
                }
            }
            $wpdb->delete($wpdb->prefix . 'cbt_questions', ['id' => $id], ['%d']);
            if ($affected_exam_id > 0) {
                CBT_Cache::invalidate_catalog();
                CBT_Cache::invalidate_exam($affected_exam_id);
            }
        }

        $redirect_args = [
            'page' => $return_page,
            'cbt_msg' => 'Question deleted',
            'cbt_question_per_page' => $question_per_page,
            'cbt_question_paged' => $question_paged,
        ];
        if ($filter_exam_id > 0) {
            $redirect_args['filter_exam_id'] = $filter_exam_id;
        }
        if ($filter_type !== '') {
            $redirect_args['filter_type'] = $filter_type;
        }

        wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
        exit;
    }

    public static function handle_bulk_delete_questions(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        self::prepare_runtime_for_bulk_user_import();

        $token = isset($_GET['cbt_question_delete_token']) ? sanitize_key((string) wp_unslash($_GET['cbt_question_delete_token'])) : '';
        if ($token !== '') {
            self::continue_bulk_delete_questions($token);
        }

        check_admin_referer('cbt_bulk_delete_questions');
        $return_page = self::normalize_question_page_slug(isset($_POST['return_page']) ? wp_unslash($_POST['return_page']) : 'cbt-question-bank');
        $filter_exam_id = isset($_POST['redirect_filter_exam_id']) ? absint($_POST['redirect_filter_exam_id']) : 0;
        $filter_type = isset($_POST['redirect_filter_type']) ? sanitize_text_field(wp_unslash($_POST['redirect_filter_type'])) : '';
        $question_per_page = self::normalize_standard_list_per_page(
            isset($_POST['redirect_question_per_page']) ? absint(wp_unslash($_POST['redirect_question_per_page'])) : 20
        );
        $question_paged = isset($_POST['redirect_question_paged']) ? max(1, absint(wp_unslash($_POST['redirect_question_paged']))) : 1;
        $allowed_filter_types = ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        if (!in_array($filter_type, $allowed_filter_types, true)) {
            $filter_type = '';
        }

        $raw_question_ids = isset($_POST['question_ids']) && is_array($_POST['question_ids']) ? wp_unslash($_POST['question_ids']) : [];
        $question_ids = array_values(array_unique(array_filter(array_map('absint', $raw_question_ids))));

        $redirect_args = [
            'page' => $return_page,
            'cbt_question_per_page' => $question_per_page,
            'cbt_question_paged' => $question_paged,
        ];
        if ($filter_exam_id > 0) {
            $redirect_args['filter_exam_id'] = $filter_exam_id;
        }
        if ($filter_type !== '') {
            $redirect_args['filter_type'] = $filter_type;
        }

        if (empty($question_ids)) {
            $redirect_args['cbt_err'] = 'Pilih minimal satu soal untuk dihapus.';
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }

        global $wpdb;
        $target_ids = $question_ids;
        if (!self::is_admin_scope()) {
            $placeholders = implode(',', array_fill(0, count($question_ids), '%d'));
            $query_params = array_merge($question_ids, [get_current_user_id()]);
            $target_ids = array_map(
                'intval',
                (array) $wpdb->get_col(
                    $wpdb->prepare(
                        "SELECT q.id
                         FROM {$wpdb->prefix}cbt_questions q
                         INNER JOIN {$wpdb->prefix}cbt_exams e ON e.id = q.exam_id
                         WHERE q.id IN ({$placeholders}) AND e.created_by = %d",
                        ...$query_params
                    )
                )
            );
        }

        if (empty($target_ids)) {
            $redirect_args['cbt_err'] = 'Tidak ada soal yang bisa dihapus.';
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }

        $affected_exam_ids = [];
        $placeholders = implode(',', array_fill(0, count($target_ids), '%d'));
        $exam_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT DISTINCT exam_id FROM {$wpdb->prefix}cbt_questions WHERE id IN ({$placeholders})",
                ...$target_ids
            ),
            ARRAY_A
        );
        foreach ((array) $exam_rows as $exam_row) {
            $exam_id = (int) ($exam_row['exam_id'] ?? 0);
            if ($exam_id > 0) {
                $affected_exam_ids[$exam_id] = $exam_id;
            }
        }

        $token = strtolower((string) wp_generate_password(24, false, false));
        $state = [
            'total' => count($target_ids),
            'offset' => 0,
            'deleted' => 0,
            'failed' => 0,
            'user_id' => get_current_user_id(),
            'started_at' => time(),
            'return_page' => $return_page,
            'filter_exam_id' => $filter_exam_id,
            'filter_type' => $filter_type,
            'question_per_page' => $question_per_page,
            'question_paged' => $question_paged,
            'affected_exam_ids' => array_values($affected_exam_ids),
        ];
        $rows_saved = set_transient(self::get_question_delete_rows_key($token), array_values($target_ids), 12 * HOUR_IN_SECONDS);
        $state_saved = set_transient(self::get_question_delete_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        if (!$rows_saved || !$state_saved) {
            self::clear_question_delete_transients($token);
            $redirect_args['cbt_err'] = 'Gagal menyiapkan sesi hapus soal. Coba lagi.';
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }

        $redirect_args['cbt_question_delete_token'] = $token;
        wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
        exit;
    }

    private static function continue_bulk_delete_questions(string $token): void
    {
        $state = self::get_question_delete_state_for_current_user($token);
        if (!is_array($state)) {
            self::clear_question_delete_transients($token);
            self::redirect_question_import_with_error('Sesi hapus soal berakhir. Silakan pilih ulang soal yang ingin dihapus.');
        }

        $return_page = self::normalize_question_page_slug((string) ($state['return_page'] ?? 'cbt-question-bank'));
        $filter_exam_id = isset($state['filter_exam_id']) ? absint($state['filter_exam_id']) : 0;
        $filter_type = isset($state['filter_type']) ? sanitize_text_field((string) $state['filter_type']) : '';
        $allowed_filter_types = ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        if (!in_array($filter_type, $allowed_filter_types, true)) {
            $filter_type = '';
        }
        $question_per_page = self::normalize_standard_list_per_page(isset($state['question_per_page']) ? (int) $state['question_per_page'] : 20);
        $question_paged = isset($state['question_paged']) ? max(1, (int) $state['question_paged']) : 1;
        $redirect_args = [
            'page' => $return_page,
            'cbt_question_per_page' => $question_per_page,
            'cbt_question_paged' => $question_paged,
        ];
        if ($filter_exam_id > 0) {
            $redirect_args['filter_exam_id'] = $filter_exam_id;
        }
        if ($filter_type !== '') {
            $redirect_args['filter_type'] = $filter_type;
        }

        $target_ids = get_transient(self::get_question_delete_rows_key($token));
        if (!is_array($target_ids) || empty($target_ids)) {
            self::clear_question_delete_transients($token);
            $redirect_args['cbt_err'] = 'Data batch hapus soal tidak ditemukan. Silakan pilih ulang soal.';
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }

        $target_ids = array_values(array_map('intval', $target_ids));
        $total = isset($state['total']) ? (int) $state['total'] : count($target_ids);
        $offset = isset($state['offset']) ? (int) $state['offset'] : 0;
        $deleted = isset($state['deleted']) ? (int) $state['deleted'] : 0;
        $failed = isset($state['failed']) ? (int) $state['failed'] : 0;
        if ($total <= 0 || empty($target_ids)) {
            self::clear_question_delete_transients($token);
            $redirect_args['cbt_err'] = 'Data hapus soal kosong.';
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }
        if ($offset < 0) {
            $offset = 0;
        }
        if ($offset > $total) {
            $offset = $total;
        }

        $affected_exam_ids = [];
        if (isset($state['affected_exam_ids']) && is_array($state['affected_exam_ids'])) {
            foreach ((array) $state['affected_exam_ids'] as $affected_exam_id) {
                $affected_exam_id = (int) $affected_exam_id;
                if ($affected_exam_id > 0) {
                    $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
                }
            }
        }

        $batch_size = self::get_question_delete_batch_size();
        $max_batch_seconds = self::get_question_delete_max_batch_seconds();
        $target_end = min($offset + $batch_size, $total);
        $end = $offset;
        $batch_started_at = microtime(true);

        global $wpdb;
        for ($index = $offset; $index < $target_end; $index++) {
            $question_id = isset($target_ids[$index]) ? (int) $target_ids[$index] : 0;
            if ($question_id <= 0) {
                $failed++;
                $end = $index + 1;
                continue;
            }

            $deleted_rows = $wpdb->delete($wpdb->prefix . 'cbt_questions', ['id' => $question_id], ['%d']);
            if ($deleted_rows) {
                $deleted += (int) $deleted_rows;
            } else {
                $failed++;
            }

            $end = $index + 1;
            if (($end - $offset) >= 1 && (microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                break;
            }
        }

        $state['offset'] = max($offset, $end);
        $state['deleted'] = $deleted;
        $state['failed'] = $failed;
        $state['affected_exam_ids'] = array_values($affected_exam_ids);

        if ((int) $state['offset'] < $total) {
            $state_saved = set_transient(self::get_question_delete_state_key($token), $state, 12 * HOUR_IN_SECONDS);
            if (!$state_saved) {
                self::clear_question_delete_transients($token);
                $redirect_args['cbt_err'] = 'Gagal menyimpan progres hapus soal. Silakan ulangi proses.';
                wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
                exit;
            }
            $redirect_args['cbt_question_delete_token'] = $token;
            wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
            exit;
        }

        self::clear_question_delete_transients($token);
        if ($deleted > 0) {
            CBT_Cache::invalidate_catalog();
            CBT_Cache::invalidate_exams(array_values($affected_exam_ids));
            $redirect_args['cbt_msg'] = sprintf('Hapus soal selesai. Total: %d, Deleted: %d, Failed: %d', $total, $deleted, $failed);
        } else {
            $redirect_args['cbt_err'] = 'Tidak ada soal yang berhasil dihapus.';
        }

        wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
        exit;
    }

    public static function handle_import_questions(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        self::prepare_runtime_for_bulk_user_import();

        $token = isset($_GET['cbt_question_import_token']) ? sanitize_key((string) wp_unslash($_GET['cbt_question_import_token'])) : '';
        if ($token !== '') {
            self::continue_question_import($token);
        }

        check_admin_referer('cbt_import_questions');
        $return_page = self::normalize_question_page_slug(isset($_POST['return_page']) ? wp_unslash($_POST['return_page']) : 'cbt-question-bank');
        $forced_import_type = self::forced_question_type_for_page($return_page);

        if (!isset($_FILES['question_file']) || !is_array($_FILES['question_file'])) {
            self::redirect_question_import_with_error('File tidak ditemukan.', $return_page);
        }

        $file = $_FILES['question_file'];
        $tmp_path = $file['tmp_name'] ?? '';
        $original_name = $file['name'] ?? '';
        $error_code = isset($file['error']) ? (int) $file['error'] : UPLOAD_ERR_NO_FILE;

        if ($error_code !== UPLOAD_ERR_OK || !$tmp_path) {
            self::redirect_question_import_with_error('Upload file gagal.', $return_page);
        }

        $default_exam_id = 0;
        $import_subject_id = isset($_POST['import_subject_id']) ? absint($_POST['import_subject_id']) : 0;
        if ($import_subject_id <= 0) {
            self::redirect_question_import_with_error('Subject utama wajib dipilih.', $return_page);
        }

        global $wpdb;
        $is_admin_scope = self::is_admin_scope();
        $default_exam_id = self::ensure_subject_question_bank_exam($import_subject_id, $is_admin_scope, get_current_user_id());
        if ($default_exam_id <= 0) {
            self::redirect_question_import_with_error('Gagal menyiapkan exam penampung untuk subject terpilih.', $return_page);
        }

        $requested_import_type = isset($_POST['import_question_type']) ? sanitize_text_field(wp_unslash($_POST['import_question_type'])) : 'all';
        $allowed_import_types = ['all', 'multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'];
        if (!in_array($requested_import_type, $allowed_import_types, true)) {
            $requested_import_type = 'all';
        }
        if ($forced_import_type !== '') {
            $requested_import_type = $forced_import_type;
        }

        $extension = strtolower((string) pathinfo((string) $original_name, PATHINFO_EXTENSION));
        $allowed_extensions = ['csv', 'xlsx'];
        if (in_array($requested_import_type, ['all', 'multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'], true)) {
            $allowed_extensions[] = 'docx';
        }

        if (!in_array($extension, $allowed_extensions, true)) {
            if (in_array($requested_import_type, ['multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay', 'all'], true)) {
                self::redirect_question_import_with_error('Format file harus CSV, XLSX, atau DOCX.', $return_page);
            }
            self::redirect_question_import_with_error('Untuk tipe soal ini, format file harus CSV atau XLSX.', $return_page);
        }

        if ($extension === 'docx' && !in_array($requested_import_type, ['all', 'multiple_choice', 'multiple_answer', 'true_false', 'true_false_matrix', 'short_answer', 'essay'], true)) {
            self::redirect_question_import_with_error('Import DOCX hanya tersedia untuk tab Multiple Choice, Multiple Answer, True/False, TF Matrix, Short Answer, dan Essay.', $return_page);
        }

        $require_question_type_column = ($requested_import_type === 'all');
        if ($extension === 'xlsx') {
            $parsed = self::parse_question_xlsx($tmp_path, $require_question_type_column);
        } elseif ($extension === 'docx') {
            $parsed = self::parse_question_docx($tmp_path);
        } else {
            $parsed = self::parse_question_csv($tmp_path, $require_question_type_column);
        }

        if (is_wp_error($parsed)) {
            self::redirect_question_import_with_error($parsed->get_error_message(), $return_page);
        }

        if ($requested_import_type !== 'all') {
            foreach ($parsed as &$row) {
                if (is_array($row)) {
                    $row['question_type'] = $requested_import_type;
                }
            }
            unset($row);
        }

        if (!is_array($parsed) || empty($parsed)) {
            self::redirect_question_import_with_error('Tidak ada data soal yang bisa diproses.', $return_page);
        }

        $token = strtolower((string) wp_generate_password(24, false, false));
        $current_user_id = get_current_user_id();
        $state = [
            'total' => count($parsed),
            'offset' => 0,
            'created' => 0,
            'failed' => 0,
            'user_id' => $current_user_id,
            'started_at' => time(),
            'return_page' => $return_page,
            'default_exam_id' => $default_exam_id,
            'is_admin_scope' => $is_admin_scope ? 1 : 0,
            'import_user_id' => $current_user_id,
            'affected_exam_ids' => [],
        ];

        $rows_saved = set_transient(self::get_question_import_rows_key($token), array_values($parsed), 12 * HOUR_IN_SECONDS);
        $state_saved = set_transient(self::get_question_import_state_key($token), $state, 12 * HOUR_IN_SECONDS);
        if (!$rows_saved || !$state_saved) {
            self::clear_question_import_transients($token);
            self::redirect_question_import_with_error('Gagal menyiapkan sesi import soal. Coba file lebih kecil atau ulangi import.', $return_page);
        }

        wp_safe_redirect(add_query_arg(
            [
                'page' => $return_page,
                'cbt_question_import_token' => $token,
            ],
            admin_url('admin.php')
        ));
        exit;
    }

    private static function continue_question_import(string $token): void
    {
        $state = self::get_question_import_state_for_current_user($token);
        if (!is_array($state)) {
            self::clear_question_import_transients($token);
            self::redirect_question_import_with_error('Sesi import soal berakhir. Silakan upload ulang file.');
        }

        $return_page = self::normalize_question_page_slug((string) ($state['return_page'] ?? 'cbt-question-bank'));
        $rows = get_transient(self::get_question_import_rows_key($token));
        if (!is_array($rows) || empty($rows)) {
            self::clear_question_import_transients($token);
            self::redirect_question_import_with_error('Data batch import soal tidak ditemukan. Silakan upload ulang file.', $return_page);
        }

        $rows = array_values($rows);
        $total = isset($state['total']) ? (int) $state['total'] : count($rows);
        $offset = isset($state['offset']) ? (int) $state['offset'] : 0;
        $created = isset($state['created']) ? (int) $state['created'] : 0;
        $failed = isset($state['failed']) ? (int) $state['failed'] : 0;
        $default_exam_id = isset($state['default_exam_id']) ? (int) $state['default_exam_id'] : 0;
        $is_admin_scope = !empty($state['is_admin_scope']);
        $import_user_id = isset($state['import_user_id']) ? (int) $state['import_user_id'] : get_current_user_id();
        if ($import_user_id <= 0) {
            $import_user_id = get_current_user_id();
        }

        if ($total <= 0 || empty($rows)) {
            self::clear_question_import_transients($token);
            self::redirect_question_import_with_error('Data import soal kosong.', $return_page);
        }
        if ($default_exam_id <= 0) {
            self::clear_question_import_transients($token);
            self::redirect_question_import_with_error('Exam penampung import tidak valid.', $return_page);
        }
        if ($offset < 0) {
            $offset = 0;
        }
        if ($offset > $total) {
            $offset = $total;
        }

        $affected_exam_ids = [];
        if (isset($state['affected_exam_ids']) && is_array($state['affected_exam_ids'])) {
            foreach ((array) $state['affected_exam_ids'] as $affected_exam_id) {
                $affected_exam_id = (int) $affected_exam_id;
                if ($affected_exam_id > 0) {
                    $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
                }
            }
        }

        $batch_size = self::get_question_import_batch_size();
        $max_batch_seconds = self::get_question_import_max_batch_seconds();
        $target_end = min($offset + $batch_size, $total);
        $end = $offset;
        $batch_started_at = microtime(true);
        $batch_affected_exam_ids = [];

        for ($index = $offset; $index < $target_end; $index++) {
            $row = isset($rows[$index]) && is_array($rows[$index]) ? (array) $rows[$index] : [];

            try {
                $result = self::import_single_question_row($row, $default_exam_id, $is_admin_scope, $import_user_id, $batch_affected_exam_ids);
            } catch (Throwable $exception) {
                $result = 'failed';
            }

            if ($result === 'created') {
                $created++;
            } else {
                $failed++;
            }

            $end = $index + 1;
            if (($end - $offset) >= 1 && (microtime(true) - $batch_started_at) >= $max_batch_seconds) {
                break;
            }
        }

        foreach ((array) $batch_affected_exam_ids as $affected_exam_id) {
            $affected_exam_id = (int) $affected_exam_id;
            if ($affected_exam_id > 0) {
                $affected_exam_ids[$affected_exam_id] = $affected_exam_id;
            }
        }

        $state['offset'] = max($offset, $end);
        $state['created'] = $created;
        $state['failed'] = $failed;
        $state['affected_exam_ids'] = array_values($affected_exam_ids);

        if ((int) $state['offset'] < $total) {
            $state_saved = set_transient(self::get_question_import_state_key($token), $state, 12 * HOUR_IN_SECONDS);
            if (!$state_saved) {
                self::clear_question_import_transients($token);
                self::redirect_question_import_with_error('Gagal menyimpan progres import soal.', $return_page);
            }
            wp_safe_redirect(add_query_arg(
                [
                    'page' => $return_page,
                    'cbt_question_import_token' => $token,
                ],
                admin_url('admin.php')
            ));
            exit;
        }

        self::clear_question_import_transients($token);

        if ($created > 0) {
            CBT_Cache::invalidate_catalog();
            CBT_Cache::invalidate_exams(array_values($affected_exam_ids));
        }

        $msg = sprintf('Import soal selesai. Total: %d, Created: %d, Failed: %d', $total, $created, $failed);
        wp_safe_redirect(add_query_arg(
            [
                'page' => $return_page,
                'cbt_msg' => $msg,
            ],
            admin_url('admin.php')
        ));
        exit;
    }

    public static function handle_download_question_template(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        check_admin_referer('cbt_download_question_template');

        $rows = self::question_template_rows();
        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename="cbt-question-import-template.csv"');
        $out = fopen('php://output', 'wb');
        if ($out === false) {
            wp_die('Gagal membuat file template.');
        }

        foreach ($rows as $row) {
            fputcsv($out, $row);
        }
        fclose($out);
        exit;
    }

    public static function handle_download_question_template_xlsx(): void
    {
        if (!current_user_can('cbt_manage_questions')) {
            wp_die('Unauthorized');
        }

        check_admin_referer('cbt_download_question_template_xlsx');

        if (!class_exists('\\PhpOffice\\PhpSpreadsheet\\Spreadsheet') || !class_exists('\\PhpOffice\\PhpSpreadsheet\\Writer\\Xlsx')) {
            wp_die('Library XLSX belum terpasang. Jalankan composer install pada plugin CBT.');
        }

        $spreadsheet = new \PhpOffice\PhpSpreadsheet\Spreadsheet();
        $sheet = $spreadsheet->getActiveSheet();
        $sheet->fromArray(self::question_template_rows(), null, 'A1');

        nocache_headers();
        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment; filename="cbt-question-import-template.xlsx"');
        header('Cache-Control: max-age=0');

        $writer = new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($spreadsheet);
        $writer->save('php://output');
        exit;
    }

